import sys
sys.path.insert(0,'/tmp')
from t2 import *
import os, time, subprocess, shlex
def run_htop(cmd_args, htoprc="/tmp/htoprc_test", pre=None, keys=["q"], w=100, h=30, wait=1.0):
    if pre is not None:
        open(htoprc,"w").write(pre)
    elif htoprc and os.path.exists(htoprc):
        os.remove(htoprc)
    cmd = f"TERM=xterm HTOPRC={htoprc} ./executable {cmd_args}" if htoprc else f"TERM=xterm ./executable {cmd_args}"
    start(cmd, w=w, h=h)
    time.sleep(0.3)
    txt=cap()
    for k in keys:
        if isinstance(k,(list,tuple)): tmux("send-keys","-t","t",*k)
        else: tmux("send-keys","-t","t","-l",k) if len(k)==1 and k not in ["q"] else tmux("send-keys","-t","t",k)
        time.sleep(0.4)
    time.sleep(0.3)
    after=cap()
    kill()
    time.sleep(0.2)
    rc=None
    if htoprc and os.path.exists(htoprc):
        rc=open(htoprc).read()
    return txt, after, rc

def show(args, **kw):
    txt,after,rc=run_htop(args, **kw)
    print(f"ARGS {args} keys={kw.get('keys',['q'])}")
    # print relevant rc lines
    if rc:
        print(rc)
    else:
        print("NO RC")
    print("----screen(head)----")
    print("\n".join(txt.splitlines()[9:20]))
    print("=====")

if __name__=="__main__":
    which=sys.argv[1] if len(sys.argv)>1 else "all"
    if which=="delay": show("-d 50")
    elif which=="tree": show("-t")
    elif which=="sort": show("-s PID")
    elif which=="mono": show("-C")
