    elif which=="filter": show("-F sleep")
    elif which=="pid": show("-p 1")
    elif which=="user": show("-u root")
    elif which=="readonly": show("--readonly")
    elif which=="highlight": show("-H 10")
    elif which=="nometers": show("--no-meters")
    elif which=="nofunc": show("--no-function-bar")
