      snprintf(buf,sz,"%llu:%02llu:%02llu",hours,mins,secs);
   } else if(hours > 0){
      /* For >=1h (?) htop TIME+ shows H:MM:SS ? Check: likely "1:23:45" without centis when >=10 min? We'll approximate:
         If total mins >= 100? We'll mimic known top: m:ss.cc for < 60 min? */
      if(total_secs >= 600) snprintf(buf,sz,"%llu:%02llu:%02llu",hours,mins,secs);
      else snprintf(buf,sz,"%llu:%02llu.%02llu", total_secs/60, secs, centis);
   } else {
      snprintf(buf,sz,"%llu:%02llu.%02llu", total_secs/60, secs, centis);
   }
}
static void format_elapsed(char* buf,size_t sz, double elapsed_secs){
   if(elapsed_secs<0) elapsed_secs=0;
   unsigned long long total_centis = (unsigned long long)llround(elapsed_secs*100.0);
   unsigned long long centis = total_centis%100;
   unsigned long long total_secs = total_centis/100;
   unsigned long long secs=total_secs%60;
   unsigned long long mins=(total_secs/60)%60;
   unsigned long long hours=total_secs/3600;
   if(total_secs < 3600){
      snprintf(buf,sz,"%llu:%02llu.%02llu", total_secs/60, secs, centis);
   } else if(total_secs < 86400){
      snprintf(buf,sz,"%llu:%02llu:%02llu", hours, mins, secs);
   } else {
      unsigned long long days=total_secs/86400;
      unsigned long long h=(total_secs%86400)/3600;
      snprintf(buf,sz,"%llud%02llu:%02llu",days,h,mins);
   }
}
static double now_sec(void){
   struct timeval tv; gettimeofday(&tv,NULL); return tv.tv_sec + tv.tv_usec/1e6;
}
