/* Config path discovery */
static int file_exists(const char* path){ struct stat st; return path && stat(path,&st)==0; }
static void make_dir_0700(const char* path){ if(path && *path) mkdir(path,0700); }

static char* get_default_config_filename(int* isDefaultPath, char** legacyPath){
   *isDefaultPath=0; if(legacyPath)*legacyPath=NULL;
   const char* htoprc=getenv("HTOPRC");
   if(htoprc!=NULL){
      return xstrdup(htoprc); /* even if empty/relative */
   }
   const char* xdg=getenv("XDG_CONFIG_HOME");
   const char* home=getenv("HOME");
   char* configDir=NULL;
   char* parentDir=NULL;
   if(xdg && xdg[0]=='/'){
      /* create xdg dir (one level) and xdg/htop */
      make_dir_0700(xdg);
      parentDir=xstrdup(xdg);
      configDir=str_cat3(xdg,"/htop",NULL);
      make_dir_0700(configDir);
   } else if(home && home[0]=='/'){
      char* dotconfig=str_cat3(home,"/.config",NULL);
      make_dir_0700(dotconfig);
      parentDir=dotconfig;
      configDir=str_cat3(dotconfig,"/htop",NULL);
      make_dir_0700(configDir);
      if(legacyPath) *legacyPath=str_cat3(home,"/.htoprc",NULL);
   } else {
      return NULL;
   }
   char* fn=str_cat3(configDir,"/htoprc",NULL);
   free(configDir); free(parentDir);
   *isDefaultPath=1;
   return fn;
}

/* Config parsing helpers */
static int parse_int_loose(const char* s, int def){
   if(!s) return def;
   char* end; long v=strtol(s,&end,10);
   if(end==s) return def;
   return (int)v;
}
static void parse_fields_string(const char* value, IntVec* out, int byName){
   /* tokens separated by space */
   iv_free(out); memset(out,0,sizeof(*out));
   char* dup=xstrdup(value);
   char* save=NULL;
   for(char* tok=strtok_r(dup," \t",&save); tok; tok=strtok_r(NULL," \t",&save)){
      if(byName){
         const ColDef* c=col_by_name(tok);
         if(c) iv_push(out,c->id);
      } else {
         char* end; long v=strtol(tok,&end,10);
         if(end!=tok){
            const ColDef* c=col_by_id((int)v);
            if(c) iv_push(out,c->id);
            else if(v==0 || v==1 || v==2) { /* pid/command/state ids are valid - already */ }
            else {
               /* Preserve unknown numeric? Original may skip unsupported fields. Skip */
            }
         }
      }
   }
   free(dup);
}
static void parse_meter_list(const char* value, StrVec* out){
   sv_free(out); memset(out,0,sizeof(*out));
   char* dup=xstrdup(value);
   char* save=NULL;
   for(char* tok=strtok_r(dup," \t",&save); tok; tok=strtok_r(NULL," \t",&save)){
      sv_push_dup(out,tok);
   }
   free(dup);
}
static void parse_mode_list(const char* value, IntVec* out){
   iv_free(out); memset(out,0,sizeof(*out));
   char* dup=xstrdup(value);
   char* save=NULL;
   for(char* tok=strtok_r(dup," \t",&save); tok; tok=strtok_r(NULL," \t",&save)){
      iv_push(out, (int)strtol(tok,NULL,10));
   }
   free(dup);
}

/* Read a config file. Return 1 if file openable and at least one line read (non-empty), 0 otherwise. */
static int settings_read_file(Settings* s, const char* filename){
   if(!filename || !*filename) return 0;
   FILE* f=fopen(filename,"r");
   if(!f) return 0;
   int readAny=0;
   char* line=NULL; size_t cap=0; ssize_t len;
   ScreenCfg* curScreen=NULL;
   int sawScreenDefinitions=0;
   ScreenCfg parsedScreens[MAX_SCREENS]; int numParsed=0;
   memset(parsedScreens,0,sizeof(parsedScreens));
   /* Legacy global values to apply to first screen after parse if no screen defns */
   int legacy_sort_key=-999, legacy_tree_sort_key=-999, legacy_sort_dir=0, legacy_tree_sort_dir=0, legacy_tree_view=-999, legacy_tree_by_pid=-999, legacy_all_collapsed=-999;
   int hasLegacySortDir=0,hasLegacyTreeSortDir=0;
   IntVec legacyFields={0}; int hasLegacyFields=0;
   while((len=getline(&line,&cap,f))>=0){
      readAny=1;
      while(len>0 && (line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;
      if(line[0]=='#' || line[0]==0) continue;
      /* screen definitions start with screen:Name=... subsequent .key=value lines belong to it */
      if(starts_with(line,"screen:")){
         char* eq=strchr(line,'=');
         if(!eq) continue;
         char* name=xstrndup(line+7, (size_t)(eq-(line+7)));
         if(numParsed<MAX_SCREENS){
            curScreen=&parsedScreens[numParsed++];
            screen_init_default(curScreen,name);
            parse_fields_string(eq+1,&curScreen->fields,1);
            sawScreenDefinitions=1;
         }
         free(name);
         continue;
      }
      if(line[0]=='.' && curScreen){
         char* eq=strchr(line,'=');
         if(!eq) continue;
         char* key=xstrndup(line+1,(size_t)(eq-(line+1)));
         const char* val=eq+1;
         if(strcmp(key,"sort_key")==0){ const ColDef*c=col_by_name(val); if(c) curScreen->sort_key=c->id; else curScreen->sort_key=parse_int_loose(val,curScreen->sort_key); }
         else if(strcmp(key,"tree_sort_key")==0){ const ColDef*c=col_by_name(val); if(c) curScreen->tree_sort_key=c->id; else curScreen->tree_sort_key=parse_int_loose(val,curScreen->tree_sort_key); }
         else if(strcmp(key,"sort_direction")==0) curScreen->sort_direction=parse_int_loose(val,curScreen->sort_direction);
         else if(strcmp(key,"tree_sort_direction")==0) curScreen->tree_sort_direction=parse_int_loose(val,curScreen->tree_sort_direction);
         else if(strcmp(key,"tree_view")==0) curScreen->tree_view=parse_int_loose(val,0);
         else if(strcmp(key,"tree_view_always_by_pid")==0) curScreen->tree_view_always_by_pid=parse_int_loose(val,0);
         else if(strcmp(key,"all_branches_collapsed")==0) curScreen->all_branches_collapsed=parse_int_loose(val,0);
         free(key);
         continue;
      }
      char* eq=strchr(line,'=');
      if(!eq) continue;
      *eq=0;
      const char* key=line;
      const char* val=eq+1;
      /* key-value pairs; parser in original is primitive: key is up to '=', no spaces trimming expected */
      if(strcmp(key,"fields")==0){ parse_fields_string(val,&legacyFields,0); hasLegacyFields=1; }
      else if(strcmp(key,"hide_kernel_threads")==0) s->hide_kernel_threads=parse_int_loose(val,0);
      else if(strcmp(key,"hide_userland_threads")==0) s->hide_userland_threads=parse_int_loose(val,0);
      else if(strcmp(key,"hide_running_in_container")==0) s->hide_running_in_container=parse_int_loose(val,0);
      else if(strcmp(key,"shadow_other_users")==0) s->shadow_other_users=parse_int_loose(val,0);
      else if(strcmp(key,"show_thread_names")==0) s->show_thread_names=parse_int_loose(val,0);
      else if(strcmp(key,"show_program_path")==0) s->show_program_path=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_base_name")==0) s->highlight_base_name=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_deleted_exe")==0) s->highlight_deleted_exe=parse_int_loose(val,0);
      else if(strcmp(key,"shadow_distribution_path_prefix")==0) s->shadow_distribution_path_prefix=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_megabytes")==0) s->highlight_megabytes=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_threads")==0) s->highlight_threads=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_changes")==0) s->highlight_changes=parse_int_loose(val,0);
      else if(strcmp(key,"highlight_changes_delay_secs")==0) s->highlight_changes_delay_secs=parse_int_loose(val,5);
      else if(strcmp(key,"find_comm_in_cmdline")==0) s->find_comm_in_cmdline=parse_int_loose(val,0);
      else if(strcmp(key,"strip_exe_from_cmdline")==0) s->strip_exe_from_cmdline=parse_int_loose(val,0);
      else if(strcmp(key,"show_merged_command")==0) s->show_merged_command=parse_int_loose(val,0);
      else if(strcmp(key,"header_margin")==0) s->header_margin=parse_int_loose(val,0);
      else if(strcmp(key,"screen_tabs")==0) s->screen_tabs=parse_int_loose(val,0);
      else if(strcmp(key,"detailed_cpu_time")==0) s->detailed_cpu_time=parse_int_loose(val,0);
      else if(strcmp(key,"cpu_count_from_one")==0) s->cpu_count_from_one=parse_int_loose(val,0);
      else if(strcmp(key,"show_cpu_usage")==0) s->show_cpu_usage=parse_int_loose(val,0);
      else if(strcmp(key,"show_cpu_frequency")==0) s->show_cpu_frequency=parse_int_loose(val,0);
      else if(strcmp(key,"show_cached_memory")==0) s->show_cached_memory=parse_int_loose(val,0);
      else if(strcmp(key,"update_process_names")==0) s->update_process_names=parse_int_loose(val,0);
      else if(strcmp(key,"account_guest_in_cpu_meter")==0) s->account_guest_in_cpu_meter=parse_int_loose(val,0);
      else if(strcmp(key,"color_scheme")==0) s->color_scheme=parse_int_loose(val,0);
      else if(strcmp(key,"enable_mouse")==0) s->enable_mouse=parse_int_loose(val,0);
      else if(strcmp(key,"delay")==0) s->delay=parse_int_loose(val,15);
      else if(strcmp(key,"hide_function_bar")==0) s->hide_function_bar=parse_int_loose(val,0);
      else if(strcmp(key,"header_layout")==0){ free(s->header_layout); s->header_layout=xstrdup(val); }
      else if(starts_with(key,"column_meters_")){
         int idx=atoi(key+strlen("column_meters_"));
         if(idx>=0 && idx<MAX_HEADER_COLS) parse_meter_list(val,&s->header[idx].meters);
      }
      else if(starts_with(key,"column_meter_modes_")){
         int idx=atoi(key+strlen("column_meter_modes_"));
         if(idx>=0 && idx<MAX_HEADER_COLS) parse_mode_list(val,&s->header[idx].modes);
      }
      else if(strcmp(key,"tree_view")==0) legacy_tree_view=parse_int_loose(val,0);
      else if(strcmp(key,"sort_key")==0) legacy_sort_key=parse_int_loose(val,0);
      else if(strcmp(key,"tree_sort_key")==0) legacy_tree_sort_key=parse_int_loose(val,0);
      else if(strcmp(key,"sort_direction")==0){ legacy_sort_dir=parse_int_loose(val,1); hasLegacySortDir=1; }
      else if(strcmp(key,"tree_sort_direction")==0){ legacy_tree_sort_dir=parse_int_loose(val,1); hasLegacyTreeSortDir=1; }
      else if(strcmp(key,"tree_view_always_by_pid")==0) legacy_tree_by_pid=parse_int_loose(val,0);
      else if(strcmp(key,"all_branches_collapsed")==0) legacy_all_collapsed=parse_int_loose(val,0);
      /* unknown ignored */
   }
   free(line);
   fclose(f);
   if(!readAny) return 0;
   if(sawScreenDefinitions){
      /* replace default screens with parsed */
      for(int i=0;i<s->num_screens;i++){ free(s->screens[i].name); iv_free(&s->screens[i].fields); }
      s->num_screens=numParsed;
      for(int i=0;i<numParsed;i++) s->screens[i]=parsedScreens[i];
   } else {
      for(int i=0;i<numParsed;i++){ free(parsedScreens[i].name); iv_free(&parsedScreens[i].fields); }
   }
   /* Apply legacy globals to first screen (Main). If screen defs existed, original still writes legacy globals mirroring first screen; reading both, which wins? 
      The generated file has legacy before screens, and screen values should reflect after. But if hand-edited file has differing legacy vs screen, unknown precedence. Test later. For now if sawScreenDefinitions, do NOT overwrite screen values with legacy unless fields legacy? Hmm.
      To handle files without screens (old) apply legacy. */
   if(!sawScreenDefinitions && s->num_screens>0){
      ScreenCfg* first=&s->screens[0];
      if(hasLegacyFields && legacyFields.count>0){ iv_free(&first->fields); first->fields=legacyFields; legacyFields.items=NULL; legacyFields.count=legacyFields.cap=0; }
      if(legacy_sort_key!=-999 && col_by_id(legacy_sort_key)) first->sort_key=legacy_sort_key;
      if(legacy_tree_sort_key!=-999 && col_by_id(legacy_tree_sort_key)) first->tree_sort_key=legacy_tree_sort_key;
      if(hasLegacySortDir) first->sort_direction=legacy_sort_dir;
      if(hasLegacyTreeSortDir) first->tree_sort_direction=legacy_tree_sort_dir;
      if(legacy_tree_view!=-999) first->tree_view=legacy_tree_view;
      if(legacy_tree_by_pid!=-999) first->tree_view_always_by_pid=legacy_tree_by_pid;
      if(legacy_all_collapsed!=-999) first->all_branches_collapsed=legacy_all_collapsed;
   }
   iv_free(&legacyFields);
   /* Clamp / normalize some values (?) delay clamped later? When config delay is e.g. 0 or 999, original maybe clamps on load/write. Check later */
   if(s->delay<1) {} /* keep for now; CLI clamping separate. Original may set at use */
   if(s->color_scheme<0) s->color_scheme=0;
   if(s->color_scheme>7) s->color_scheme=0; /* guess */
   if(s->num_screens<=0) settings_default_screens(s);
   if(s->active_screen<0||s->active_screen>=s->num_screens)s->active_screen=0;
   for(int i=0;i<s->num_screens;i++){
      ScreenCfg* sc=&s->screens[i];
      if(sc->fields.count==0){
         /* if screen had invalid fields, fill default PID Command? */
         iv_push(&sc->fields,0); iv_push(&sc->fields,1);
      }
      if(sc->sort_direction!=1 && sc->sort_direction!=-1) sc->sort_direction = sc->sort_direction<0?-1:1;
      if(sc->tree_sort_direction!=1 && sc->tree_sort_direction!=-1) sc->tree_sort_direction = sc->tree_sort_direction<0?-1:1;
      if(!col_by_id(sc->sort_key)) sc->sort_key=COL_PERCENT_CPU;
      if(!col_by_id(sc->tree_sort_key)) sc->tree_sort_key=COL_PID;
   }
   return 1;
}

static Settings* settings_new(void){
   Settings* s=xcalloc(1,sizeof(Settings));
   settings_set_pre_read_defaults(s);
   int isDef=0; char* legacyPath=NULL;
   s->filename=get_default_config_filename(&isDef,&legacyPath);
   s->filename_is_default_path=isDef;
   int readOk=0;
   char* readFrom=NULL;
   if(s->filename){
      readOk=settings_read_file(s,s->filename);
      if(readOk) readFrom=xstrdup(s->filename);
   }
   if(!readOk){
      /* try system config: /etc/htoprc (best guess) */
      const char* syscfg="/etc/htoprc";
      if(s->filename==NULL || strcmp(s->filename,syscfg)!=0){
         if(settings_read_file(s,syscfg)){ readOk=1; readFrom=xstrdup(syscfg); }
      }
   }
   if(!readOk && legacyPath){
      if(settings_read_file(s,legacyPath)){ readOk=1; readFrom=xstrdup(legacyPath); }
   }
   s->config_read_success=readOk;
   s->read_from_path=readFrom;
   if(!readOk){
      /* fresh defaults */
      s->screen_tabs=1;
      s->changed=1;
   } else {
      s->changed=0;
      /* if read from a different path than primary filename, migrate on save */
      if(s->filename && readFrom && strcmp(readFrom,s->filename)!=0) s->changed=1;
      if(!s->filename) s->changed=0; /* nowhere to write */
   }
   free(legacyPath);
   /* Fix modes length to meters */
   for(int c=0;c<MAX_HEADER_COLS;c++){
      while(s->header[c].modes.count < s->header[c].meters.count){
         const char* mn=s->header[c].meters.items[s->header[c].modes.count];
         const MeterDef* md=meter_by_name(mn);
         int dm = md?md->defaultMode: (meter_is_cpu_single(mn,NULL)?1:2);
         iv_push(&s->header[c].modes, dm);
      }
      if(s->header[c].modes.count > s->header[c].meters.count) s->header[c].modes.count=s->header[c].meters.count;
   }
   return s;
}

static int settings_write(Settings* s){
   if(!s->filename) return 0;
   const char* destOrig=s->filename;
   char* dest=NULL;
   /* Symlink handling: if dest is symlink, resolve; if cannot resolve abort */
   struct stat lst;
   if(lstat(destOrig,&lst)==0 && S_ISLNK(lst.st_mode)){
      char* rp=realpath(destOrig,NULL);
      if(!rp) return 0;
      dest=rp;
   } else {
      dest=xstrdup(destOrig);
   }
   struct stat st;
   if(stat(dest,&st)==0 && S_ISDIR(st.st_mode)){ free(dest); return 0; }
   /* Build temp template */
   char* tmpTemplate=NULL;
   const char* slash=strrchr(dest,'/');
   if(slash){
      size_t dirlen=(size_t)(slash-dest);
      if(dirlen==0) dirlen=1;
      tmpTemplate=xmalloc(dirlen+32);
      memcpy(tmpTemplate,dest,dirlen); tmpTemplate[dirlen]=0;
      if(dirlen==1 && dest[0]=='/') strcat(tmpTemplate,".tmp.XXXXXX");
      else strcat(tmpTemplate,"/.tmp.XXXXXX");
   } else {
      tmpTemplate=xstrdup(".tmp.XXXXXX");
   }
   int fd=mkstemp(tmpTemplate);
   if(fd<0){ free(tmpTemplate); free(dest); return 0; }
   FILE* f=fdopen(fd,"w");
   if(!f){ close(fd); unlink(tmpTemplate); free(tmpTemplate); free(dest); return 0; }
   ScreenCfg* first = s->num_screens>0? &s->screens[0] : NULL;
   fprintf(f,"# Beware! This file is rewritten by htop when settings are changed in the interface.\n");
   fprintf(f,"# The parser is also very primitive, and not human-friendly.\n");
   fprintf(f,"htop_version=%s\n",VERSION_STR);
   fprintf(f,"config_reader_min_version=3\n");
   fprintf(f,"fields=");
   if(first){
      for(int i=0;i<first->fields.count;i++){ if(i)fputc(' ',f); fprintf(f,"%d",first->fields.items[i]); }
   }
   fprintf(f,"\n");
   fprintf(f,"hide_kernel_threads=%d\n",s->hide_kernel_threads);
   fprintf(f,"hide_userland_threads=%d\n",s->hide_userland_threads);
   fprintf(f,"hide_running_in_container=%d\n",s->hide_running_in_container);
   fprintf(f,"shadow_other_users=%d\n",s->shadow_other_users);
   fprintf(f,"show_thread_names=%d\n",s->show_thread_names);
   fprintf(f,"show_program_path=%d\n",s->show_program_path);
   fprintf(f,"highlight_base_name=%d\n",s->highlight_base_name);
   fprintf(f,"highlight_deleted_exe=%d\n",s->highlight_deleted_exe);
   fprintf(f,"shadow_distribution_path_prefix=%d\n",s->shadow_distribution_path_prefix);
   fprintf(f,"highlight_megabytes=%d\n",s->highlight_megabytes);
   fprintf(f,"highlight_threads=%d\n",s->highlight_threads);
   fprintf(f,"highlight_changes=%d\n",s->highlight_changes);
   fprintf(f,"highlight_changes_delay_secs=%d\n",s->highlight_changes_delay_secs);
   fprintf(f,"find_comm_in_cmdline=%d\n",s->find_comm_in_cmdline);
   fprintf(f,"strip_exe_from_cmdline=%d\n",s->strip_exe_from_cmdline);
   fprintf(f,"show_merged_command=%d\n",s->show_merged_command);
   fprintf(f,"header_margin=%d\n",s->header_margin);
   fprintf(f,"screen_tabs=%d\n",s->screen_tabs);
   fprintf(f,"detailed_cpu_time=%d\n",s->detailed_cpu_time);
   fprintf(f,"cpu_count_from_one=%d\n",s->cpu_count_from_one);
   fprintf(f,"show_cpu_usage=%d\n",s->show_cpu_usage);
   fprintf(f,"show_cpu_frequency=%d\n",s->show_cpu_frequency);
   fprintf(f,"show_cached_memory=%d\n",s->show_cached_memory);
   fprintf(f,"update_process_names=%d\n",s->update_process_names);
   fprintf(f,"account_guest_in_cpu_meter=%d\n",s->account_guest_in_cpu_meter);
   fprintf(f,"color_scheme=%d\n",s->color_scheme);
   fprintf(f,"enable_mouse=%d\n",s->enable_mouse);
   fprintf(f,"delay=%d\n",s->delay);
   fprintf(f,"hide_function_bar=%d\n",s->hide_function_bar);
   fprintf(f,"header_layout=%s\n",s->header_layout?s->header_layout:"two_50_50");
   int ncols=header_layout_num_cols(header_layout_index(s->header_layout?s->header_layout:"two_50_50"));
   for(int c=0;c<ncols;c++){
      fprintf(f,"column_meters_%d=",c);
      for(int i=0;i<s->header[c].meters.count;i++){ if(i)fputc(' ',f); fprintf(f,"%s",s->header[c].meters.items[i]); }
      fprintf(f,"\n");
      fprintf(f,"column_meter_modes_%d=",c);
      for(int i=0;i<s->header[c].modes.count;i++){ if(i)fputc(' ',f); fprintf(f,"%d",s->header[c].modes.items[i]); }
      fprintf(f,"\n");
   }
   if(first){
      fprintf(f,"tree_view=%d\n",first->tree_view);
      fprintf(f,"sort_key=%d\n",first->sort_key);
      fprintf(f,"tree_sort_key=%d\n",first->tree_sort_key);
      fprintf(f,"sort_direction=%d\n",first->sort_direction);
      fprintf(f,"tree_sort_direction=%d\n",first->tree_sort_direction);
      fprintf(f,"tree_view_always_by_pid=%d\n",first->tree_view_always_by_pid);
      fprintf(f,"all_branches_collapsed=%d\n",first->all_branches_collapsed);
   }
   for(int si=0;si<s->num_screens;si++){
      ScreenCfg* sc=&s->screens[si];
      fprintf(f,"screen:%s=",sc->name);
      for(int i=0;i<sc->fields.count;i++){
         const ColDef* cd=col_by_id(sc->fields.items[i]);
         if(i)fputc(' ',f);
         fprintf(f,"%s",cd?cd->name:"PID");
      }
      fprintf(f,"\n");
      const ColDef* sk=col_by_id(sc->sort_key);
      const ColDef* tsk=col_by_id(sc->tree_sort_key);
      fprintf(f,".sort_key=%s\n",sk?sk->name:"PERCENT_CPU");
      fprintf(f,".tree_sort_key=%s\n",tsk?tsk->name:"PID");
      fprintf(f,".tree_view_always_by_pid=%d\n",sc->tree_view_always_by_pid);
      fprintf(f,".tree_view=%d\n",sc->tree_view);
      fprintf(f,".sort_direction=%d\n",sc->sort_direction);
      fprintf(f,".tree_sort_direction=%d\n",sc->tree_sort_direction);
      fprintf(f,".all_branches_collapsed=%d\n",sc->all_branches_collapsed);
   }
   int err = ferror(f);
   if(fclose(f)!=0) err=1;
   if(err){ unlink(tmpTemplate); free(tmpTemplate); free(dest); return 0; }
   if(rename(tmpTemplate,dest)!=0){
      /* Observed: empty dest leaves .tmp file; other failures clean up */
      if(dest[0]!='\0') unlink(tmpTemplate);
      free(tmpTemplate); free(dest); return 0;
   }
   /* if migrated from legacy/system, delete legacy ~/.htoprc if read_from is that and differs */
   if(s->read_from_path && s->filename && strcmp(s->read_from_path,s->filename)!=0){
      /* Only delete if read_from ends with /.htoprc (legacy) */
      const char* base=strrchr(s->read_from_path,'/');
      if(base && strcmp(base,"/.htoprc")==0) unlink(s->read_from_path);
   }
   free(tmpTemplate); free(dest);
   return 1;
}

