            if(!optarg || optarg[0]=='\0'){ fprintf(stderr,"Error: invalid filter value \"%s\".\n",optarg?optarg:""); exit(1); }
            free(flags.filter); flags.filter=xstrdup(optarg);
            break;
         }
         case 'n': {
            int v=parse_int_arg_or_die(optarg,"Error: invalid maximum iteration count \"%s\".\n");
            if(v<=0){ fprintf(stderr,"Error: maximum iteration count must be positive.\n"); exit(1); }
