            char* save=NULL;
            for(char* tok=strtok_r(dup,",",&save); tok; tok=strtok_r(NULL,",",&save)){
               char* end; long v=strtol(tok,&end,10);
               if(end!=tok) iv_push(&flags.pids,(int)v);
            }
            free(dup);
            break;
         }
         case 's': {
            if(optarg && strcmp(optarg,"help")==0){ print_sort_help(); exit(0); }
            const ColDef* cd= optarg? col_by_name(optarg):NULL;
            if(!cd){ fprintf(stderr,"Error: invalid column \"%s\".\n",optarg?optarg:""); exit(1); }
            flags.sortKey=cd->id; flags.sortKeySet=1;
            break;
         }
         case 'H': {
            const char* arg=optarg;
            if(!arg) arg=maybe_consume_next(argc,argv,&optind);
            flags.highlightSet=1;
            if(arg){
               flags.highlightDelay=parse_int_arg_or_die(arg,"Error: invalid highlight delay value \"%s\".\n");
               flags.highlightDelaySet=1;
            }
            break;
         }
         case 'u': {
            const char* arg=optarg;
            if(!arg) arg=maybe_consume_next(argc,argv,&optind);
            flags.userSet=1;
            if(arg){
               flags.userId=parse_user_or_die(arg);
               flags.userOnlySelf=0;
            } else {
               flags.userId=getuid(); flags.userOnlySelf=1;
            }
            break;
         }
         case OPT_NO_FUNCTION_BAR: flags.hideFunctionBarSet=1; break;
         case OPT_NO_METERS: flags.noMeters=1; break;
         case OPT_READONLY: flags.readonly=1; break;
         case '?':
         default:
            exit(1);
      }
