   if(optind<argc){
      fprintf(stderr,"Error: unsupported non-option ARGV-elements:");
      for(int i=optind;i<argc;i++){
         fprintf(stderr," %s",argv[i]);
         /* Note original format: "Error: unsupported non-option ARGV-elements: extra extra2\n" -> first has space after colon, additional separated by space. Our loop gives ": extra extra2" correct (colons without trailing space in fmt + space per) */
      }
      fprintf(stderr,"\n");
      exit(1);
   }
   return flags;
}
static void cli_apply_to_settings(const CLIFlags* flags, Settings* s){
   if(flags->delaySet){
      int d=flags->delay;
      if(d<1) d=1;
      if(d>100) d=100;
      s->delay=d;
   }
   if(flags->noMouseSet) s->enable_mouse=0;
   if(flags->hideFunctionBarSet) s->hide_function_bar=2;
   if(flags->highlightSet){
      s->highlight_changes=1;
      if(flags->highlightDelaySet){
         int v=flags->highlightDelay;
         if(v<1) v=1;
         s->highlight_changes_delay_secs=v;
      }
   }
   /* sort/tree apply to first screen? Or active? At startup active is first (Main). */
   ScreenCfg* sc=&s->screens[s->active_screen];
   if(flags->sortKeySet){
      const ColDef* cd=col_by_id(flags->sortKey);
      if(flags->treeSet){
         /* Combined -t -s: sort applies as tree sort? Observed -t -s TIME header shows TIME as tree sort and config? Need verify. Tentatively: if tree then tree_sort_key=sort, direction to default dir, tree_view=1.
            But earlier run -t -s TIME header marker on TIME (distance). And -s alone forced list view semantics. Let's implement according to probe later, for now: set tree_sort_key */
         sc->tree_sort_key=flags->sortKey;
         if(cd) sc->tree_sort_direction=cd->defaultDir;
         sc->tree_view=1;
      } else {
         sc->sort_key=flags->sortKey;
         if(cd) sc->sort_direction=cd->defaultDir;
         sc->tree_view=0;
      }
   }
   if(flags->treeSet && !flags->sortKeySet){
      sc->tree_view=1;
   }
}
