static int cpu_count_system(void){
   /* count cpuN lines in /proc/stat, fallback sysconf */
   FILE* f=fopen("/proc/stat","r");
   int cnt=0;
   if(f){
      char* line=NULL; size_t cap=0;
      while(getline(&line,&cap,f)>0){
         if(strncmp(line,"cpu",3)==0 && isdigit((unsigned char)line[3])) cnt++;
         else if(cnt>0 && line[0]!='c') { /* continue until intr */ if(strncmp(line,"intr",4)==0) break; }
      }
      free(line); fclose(f);
   }
   if(cnt<=0){ long n=sysconf(_SC_NPROCESSORS_ONLN); cnt = n>0?(int)n:1; }
   if(cnt>1024) cnt=1024;
   return cnt;
}
static void sysinfo_init(void){
   memset(&sysinfo,0,sizeof(sysinfo));
   sysinfo.cpuCount=cpu_count_system();
