      if(sysinfo.lastNetSampleTime>0 && t>sysinfo.lastNetSampleTime){
         double dt=t-sysinfo.lastNetSampleTime;
         sysinfo.netRecvRate=(rb>=sysinfo.netRecvBytesPrev)?(rb-sysinfo.netRecvBytesPrev)/dt:0;
         sysinfo.netSendRate=(sb>=sysinfo.netSendBytesPrev)?(sb-sysinfo.netSendBytesPrev)/dt:0;
