/* Cache for prev times, tagged, collapsed, command, firstSeen keyed by (pid, starttime) */
typedef struct CacheEntry {
   int pid;
   unsigned long long starttime_ticks;
   unsigned long long prev_utime_stime;
   unsigned long long prev_read_bytes, prev_write_bytes;
   unsigned long long prev_ctxt; /* not needed */
   int tagged;
   int show_children;
   double firstSeen;
   double lastSeen;
   char* cmdline_cached;
   int highlight; /* 0 normal, 1 new */
   struct CacheEntry* next;
} CacheEntry;
#define CACHE_BUCKETS 2048
static CacheEntry* procCache[CACHE_BUCKETS];
static CacheEntry* cache_get(int pid, unsigned long long starttime, int create){
   unsigned h=((unsigned)pid*2654435761u) % CACHE_BUCKETS;
   for(CacheEntry* e=procCache[h]; e; e=e->next) if(e->pid==pid && e->starttime_ticks==starttime) return e;
   if(!create) return NULL;
   CacheEntry* e=xcalloc(1,sizeof(CacheEntry)); e->pid=pid; e->starttime_ticks=starttime; e->show_children=1; e->firstSeen=now_sec(); e->next=procCache[h]; procCache[h]=e; return e;
}
static void cache_prune(double now){
   /* remove entries not seen (>now) maybe periodically: if lastSeen < now-? caller updates lastSeen only for present; entries with lastSeen set and <= now-1? But scans multiple per sec. Prune if lastSeen < current scan time -0.001 AND not ??? We'll prune entries whose lastSeen timestamp != last scan time using a scan id approach simplified: remove if now - lastSeen > 5 sec? Tagged dead processes vanish anyway */
   for(int i=0;i<CACHE_BUCKETS;i++){
      CacheEntry** pp=&procCache[i];
      while(*pp){
         CacheEntry* e=*pp;
         if(e->lastSeen>0 && now-e->lastSeen>60){ *pp=e->next; free(e->cmdline_cached); free(e); }
         else pp=&e->next;
      }
   }
}

/* user name cache */
typedef struct UserCache { uid_t uid; char* name; struct UserCache* next; } UserCache;
static UserCache* userCache=NULL;
static const char* user_name(uid_t uid){
   for(UserCache* u=userCache;u;u=u->next) if(u->uid==uid) return u->name;
   struct passwd* pw=getpwuid(uid);
   char buf[64];
   const char* name;
   if(pw) name=pw->pw_name; else { snprintf(buf,sizeof(buf),"%u",(unsigned)uid); name=buf; }
   UserCache* u=xcalloc(1,sizeof(UserCache)); u->uid=uid; u->name=xstrdup(name); u->next=userCache; userCache=u;
   return u->name;
}

/* file read helper */
static char* read_file_alloc(const char* path, size_t* outLen){
   FILE* f=fopen(path,"rb");
   if(!f) return NULL;
   size_t cap=4096,len=0; char* buf=xmalloc(cap);
   size_t n;
   while((n=fread(buf+len,1,cap-len,f))>0){
      len+=n;
      if(len+2048>cap){ cap*=2; buf=xrealloc(buf,cap); }
      if(len> (size_t)10*1024*1024) break;
   }
   fclose(f);
   if(outLen)*outLen=len;
   buf=xrealloc(buf,len+1); buf[len]=0;
   return buf;
}
static int read_small_file(const char* path, char* buf, size_t sz){
   FILE* f=fopen(path,"r"); if(!f) return 0;
   size_t n=fread(buf,1,sz-1,f); buf[n]=0; fclose(f); return 1;
}

/* condense cgroup - simple implementation according to man descriptions */
static char* condense_cgroup(const char* cg){
   if(!cg) return xstrdup("");
   /* Apply replacements per path component described: */
   /* We'll implement component wise:
      - "/system.slice" -> "/[S]"
      - "/user.slice" -> "/[U]" but if followed by /user-*.slice, dropping preceding /[U]
      - "/user-*.slice" -> "/[U:*]" (?) * is text after user- up to .slice
      - "/machine.slice" -> "/[M]"
      - "/machine-*.scope" -> "/[SNC:*]" uppercase (?) text
      - "/lxc.monitor.*" -> "/[LXC:*]"
      - "/lxc.payload.*" -> "/[lxc:*]"
      - "/*.slice" -> "/[*]"
      - "/*.scope" -> "/!*": * is basename without suffix
      - "/*.service" -> "/*"
   */
   if(strcmp(cg,"/")==0 || strcmp(cg,"")==0) return xstrdup(cg);
   StrVec comps={0};
   char* dup=xstrdup(cg);
   char* save=NULL;
   for(char* tok=strtok_r(dup,"/",&save); tok; tok=strtok_r(NULL,"/",&save)) sv_push_dup(&comps,tok);
   free(dup);
   /* transformed components */
   char* out=xmalloc(strlen(cg)*2+64); out[0]=0;
   for(int i=0;i<comps.count;i++){
      char* c=comps.items[i];
      char buf[512];
      if(strcmp(c,"system.slice")==0) snprintf(buf,sizeof(buf),"[S]");
      else if(strcmp(c,"machine.slice")==0) snprintf(buf,sizeof(buf),"[M]");
      else if(strcmp(c,"user.slice")==0){
         /* drop if next is user-*.slice */
         if(i+1<comps.count && starts_with(comps.items[i+1],"user-") && strstr(comps.items[i+1],".slice")) continue;
         snprintf(buf,sizeof(buf),"[U]");
      } else if(starts_with(c,"user-") && strstr(c,".slice")){
         /* * between user- and .slice */
         const char* a=c+5; const char* b=strstr(c,".slice"); char tmp[128]={0}; size_t l=b? (size_t)(b-a):strlen(a); if(l>100)l=100; memcpy(tmp,a,l);
         snprintf(buf,sizeof(buf),"[U:%s]",tmp);
      } else if(starts_with(c,"machine-") && strstr(c,".scope")){
         const char* a=c+8; const char* b=strstr(c,".scope"); char tmp[128]={0}; size_t l=b?(size_t)(b-a):strlen(a); if(l>100)l=100; memcpy(tmp,a,l);
         /* uppercase for monitor? Spec: basename? We'll keep as is (?) Uppercase ??? original says uppercase for monitor - complicated */
         snprintf(buf,sizeof(buf),"[SNC:%s]",tmp);
      } else if(starts_with(c,"lxc.monitor.")){
         snprintf(buf,sizeof(buf),"[LXC:%s]",c+12);
      } else if(starts_with(c,"lxc.payload.")){
         snprintf(buf,sizeof(buf),"[lxc:%s]",c+12);
      } else if(strstr(c,".slice") && strcmp(strstr(c,".slice"),".slice")==0){
         /* /*.slice -> /[*] where * is part before suffix */
         char tmp[256]={0}; size_t l=(size_t)(strstr(c,".slice")-c); if(l>200)l=200; memcpy(tmp,c,l);
         snprintf(buf,sizeof(buf),"[%s]",tmp);
      } else if(strstr(c,".scope") && strcmp(strstr(c,".scope"),".scope")==0){
         char tmp[256]={0}; size_t l=(size_t)(strstr(c,".scope")-c); if(l>200)l=200; memcpy(tmp,c,l);
         snprintf(buf,sizeof(buf),"!%s",tmp);
         /* leading / will be added below giving /!* */
      } else if(strstr(c,".service") && strcmp(strstr(c,".service"),".service")==0){
         char tmp[256]={0}; size_t l=(size_t)(strstr(c,".service")-c); if(l>200)l=200; memcpy(tmp,c,l);
         snprintf(buf,sizeof(buf),"%s",tmp);
      } else {
         snprintf(buf,sizeof(buf),"%s",c);
      }
      strcat(out,"/"); strcat(out,buf);
   }
   sv_free(&comps);
   if(out[0]==0) strcpy(out,"/");
   return out;
}
static char* guess_container(const char* cg, int* isContainerOut){
   if(isContainerOut)*isContainerOut=0;
   if(!cg || !*cg) return xstrdup("");
   if(strcmp(cg,"/")==0) return xstrdup("/");
   /* heuristics: look for docker, containerd, kubepods, lxc, machine-*.scope etc; return relevant component */
   /* Simplified: if cgroup contains "/docker/" or "docker-" extract id segment up to .scope / slash */
   const char* p=NULL;
   if((p=strstr(cg,"/docker/")) ) p+=8;
   else if((p=strstr(cg,"docker-"))) p+=7;
   else if((p=strstr(cg,"/kubepods/"))) {
      /* container maybe last component */
   }
   if(p){
      const char* end=p;
      while(*end && *end!='/' && *end!='.') end++;
      if(isContainerOut)*isContainerOut=1;
      return xstrndup(p,(size_t)(end-p));
   }
   /* lxc.payload.<name> */
   if((p=strstr(cg,"lxc.payload."))){ p+=12; const char* end=p; while(*end&&*end!='/')end++; if(isContainerOut)*isContainerOut=1; return xstrndup(p,(size_t)(end-p)); }
   /* As in observed for "/" , otherwise maybe return full cg? Original CONTAINER for a process in non-container systemd service maybe "/"? Need approximation: if no container detected return "/" */
   return xstrdup("/");
}

