static void sysinfo_scan_cpu(void){
   FILE* f=fopen("/proc/stat","r");
   if(!f) return;
   char* line=NULL; size_t cap=0; ssize_t len;
   while((len=getline(&line,&cap,f))>0){
      if(strncmp(line,"btime",5)==0){ sysinfo.btime=strtol(line+6,NULL,10); continue; }
      if(strncmp(line,"cpu",3)!=0 || !isdigit((unsigned char)line[3])){
         if(strncmp(line,"cpu ",4)==0) continue;
         if(strncmp(line,"intr",4)==0) break;
         continue;
      }
      int id=atoi(line+3);
      if(id<0 || id>=sysinfo.cpuCount) continue;
      unsigned long long v[10]={0};
      /* parse after "cpuN" */
      const char* p=strchr(line,' ');
      if(!p) continue;
      int got=sscanf(p,"%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",&v[0],&v[1],&v[2],&v[3],&v[4],&v[5],&v[6],&v[7],&v[8],&v[9]);
      if(got<4) continue;
      unsigned long long* prev=&sysinfo.prevCpuTimes[(size_t)id*10];
      unsigned long long totalPrev=0,totalNow=0;
      for(int i=0;i<10;i++){ totalPrev+=prev[i]; totalNow+=v[i]; }
      /* guest times are already included in user/nice in kernel, htop may subtract but approx */
      unsigned long long delta = totalNow>=totalPrev? totalNow-totalPrev:0;
      if(delta>0 && totalPrev>0){
         auto double pct(int idx){ return 100.0 * (double)(v[idx]-prev[idx])/(double)delta; }
         sysinfo.cpuUser[id]=pct(0);
         sysinfo.cpuNice[id]=pct(1);
         sysinfo.cpuSystem[id]=pct(2);
         sysinfo.cpuIdle[id]=pct(3);
         sysinfo.cpuIOWait[id]=pct(4);
         sysinfo.cpuIrq[id]=pct(5);
         sysinfo.cpuSoftIrq[id]=pct(6);
         sysinfo.cpuSteal[id]=pct(7);
         sysinfo.cpuGuest[id]=pct(8)+pct(9);
         sysinfo.cpuPercent[id]=100.0 - sysinfo.cpuIdle[id];
         if(sysinfo.cpuPercent[id]<0) sysinfo.cpuPercent[id]=0;
         if(sysinfo.cpuPercent[id]>100) sysinfo.cpuPercent[id]=100;
      } else {
         sysinfo.cpuUser[id]=sysinfo.cpuNice[id]=sysinfo.cpuSystem[id]=sysinfo.cpuIdle[id]=0;
      }
      memcpy(prev,v,sizeof(v));
   }
   free(line); fclose(f);
   /* load average & uptime */
   f=fopen("/proc/loadavg","r");
   if(f){ if(fscanf(f,"%lf %lf %lf",&sysinfo.load1,&sysinfo.load5,&sysinfo.load15)!=3){} fclose(f); }
   f=fopen("/proc/uptime","r");
   if(f){ if(fscanf(f,"%lf",&sysinfo.uptimeSec)!=1){} fclose(f); }
   /* CPU frequencies (best effort from /proc/cpuinfo "cpu MHz") */
   f=fopen("/proc/cpuinfo","r");
   if(f){
      char* l2=NULL; size_t c2=0; int idx=0;
      while(getline(&l2,&c2,f)>0){
         if(strncmp(l2,"cpu MHz",7)==0){
            const char* colon=strchr(l2,':'); if(colon && idx<512) sysinfo.cpuFreqMHz[idx++]=(int)strtod(colon+1,NULL);
         }
      }
      free(l2); fclose(f);
   }
}
