static int parse_stat_content(const char* content, Proc* pr, char** out_comm){
   const char* lp=strchr(content,'(');
   const char* rp=strrchr(content,')');
   if(!lp||!rp||rp<lp) return 0;
   if(out_comm) *out_comm=xstrndup(lp+1,(size_t)(rp-lp-1));
   const char* p=rp+1;
   /* fields after comm: state ppid pgrp session tty_nr tpgid flags minflt cminflt majflt cmajflt utime stime cutime cstime priority nice num_threads itrealvalue starttime vsize rss rsslim startcode endcode startstack kstkesp kstkeip signal blocked sigignore sigcatch wchan nswap cnswap exit_signal processor ... */
   char state=0;
   unsigned long long vs=0;
