   int num = sscanf(p," %c %d %d %d %d %d %lu %llu %llu %llu %llu %llu %llu %llu %llu %ld %ld %ld %*ld %llu %llu %ld",
      &state,&pr->ppid,&pr->pgrp,&pr->session,&pr->tty_nr,&pr->tpgid,&pr->flags,
      &pr->minflt,&pr->cminflt,&pr->majflt,&pr->cmajflt,&pr->utime,&pr->stime,&pr->cutime,&pr->cstime,
      &pr->priority,&pr->nice,&pr->nlwp,&pr->starttime_ticks,&vs,&rss);
   if(num<21) return 0;
   pr->state=state;
