static void free_proc(Proc* p){
   if(!p) return;
   free(p->comm); free(p->cmdline); free(p->exe); free(p->exe_path); free(p->cwd); free(p->cgroup); free(p->ccgroup); free(p->container); free(p->secattr); free(p->tty_name); free(p->user); free(p->tree_prefix);
   free(p);
}

static double lastScanTime=0;
static ProcVec scan_processes(Settings* settings, ScreenCfg* activeScreen, int primeOnly){
   (void)primeOnly;
   sysinfo_scan_cpu();
   sysinfo_scan_mem();
   sysinfo_scan_io();
   double now=now_sec();
   double period = lastScanTime>0 ? (now-lastScanTime) : 0;
   ProcVec vec={0};
   DIR* d=opendir("/proc");
   if(!d) return vec;
   struct dirent* ent;
   sysinfo.totalTasks=0; sysinfo.runningTasks=0; sysinfo.threadCount=0; sysinfo.kernelThreadCount=0;
   while((ent=readdir(d))!=NULL){
      if(!isdigit((unsigned char)ent->d_name[0])) continue;
      int pid=atoi(ent->d_name);
      if(pid<=0) continue;
      /* collect task ids */
      int tids[1024]; int ntids=0;
      tids[ntids++]=pid;
      char taskpath[128]; snprintf(taskpath,sizeof(taskpath),"/proc/%d/task",pid);
      DIR* td=opendir(taskpath);
      if(td){
         struct dirent* te;
         while((te=readdir(td))!=NULL){
            if(!isdigit((unsigned char)te->d_name[0]))continue;
            int tid=atoi(te->d_name);
            if(tid!=pid && ntids<1024) tids[ntids++]=tid;
         }
         closedir(td);
      }
      for(int ti=0; ti<ntids; ti++){
         int tid=tids[ti];
         int isThread = (tid!=pid);
         /* We'll still scan thread for counts; later filtering hides if hide_userland */
         char statpath[192];
         if(isThread) snprintf(statpath,sizeof(statpath),"/proc/%d/task/%d/stat",pid,tid);
         else snprintf(statpath,sizeof(statpath),"/proc/%d/stat",pid);
         char* content=read_file_alloc(statpath,NULL);
         if(!content) continue;
         Proc* pr=xcalloc(1,sizeof(Proc));
         pr->pid=tid; pr->tgid=pid; pr->isThread=isThread; pr->show_children=1; pr->sched_policy=0;
         char* comm=NULL;
         if(!parse_stat_content(content,pr,&comm)){ free(content); free(pr); free(comm); continue; }
         free(content);
         pr->comm=comm;
         /* kernel thread if PF_KTHREAD 0x200000 */
         pr->isKernelThread = (pr->flags & 0x200000) ? 1:0;
         /* TGID from status later overwritten? Keep pid (tgid) as set */
         /* starttime epoch */
         if(sysinfo.btime==0){
            /* read btime if not yet: scan_cpu already may have set while reading /proc/stat until intr break may miss btime which is after cpu lines? btime is after cpu/intr etc, our break at intr misses it. Read separately if zero */
            FILE* bf=fopen("/proc/stat","r");
            if(bf){ char* l=NULL; size_t c=0; while(getline(&l,&c,bf)>0){ if(strncmp(l,"btime",5)==0){ sysinfo.btime=strtol(l+6,NULL,10); break; } } free(l); fclose(bf); }
         }
         pr->starttime_epoch = (double)sysinfo.btime + (double)pr->starttime_ticks/(double)clk_tck_global;
         pr->elapsed = ((double)time(NULL) - pr->starttime_epoch);
         if(pr->elapsed<0) pr->elapsed=0;
         /* fill aux */
         fill_proc_aux(pr,settings,activeScreen);
         /* command */
         CacheEntry* ce=cache_get(pr->pid,pr->starttime_ticks,1);
         ce->lastSeen=now;
         pr->seenTime=ce->firstSeen;
         pr->tagged=ce->tagged;
         pr->show_children=ce->show_children;
         pr->collapsed = !ce->show_children;
         if(settings && !settings->update_process_names && ce->cmdline_cached){
            pr->cmdline=xstrdup(ce->cmdline_cached);
         } else {
            if(settings && settings->show_merged_command){
               /* merged: construct "exe (comm) cmdline..." approximation - refine later */
               char* cmd=get_cmdline_for(pr->pid,pr->tgid,pr->comm,NULL); /* without path stripping */
               /* Build merged string: if exe_path available and not in cmd, prefix? htop merged format: "exe comm cmdline"? Search memory: merged shows "/usr/bin/python3 (python3) -options" ??? We'll implement as below and refine via tests */
               if(pr->exe_path && pr->exe_path[0]){
                  char* merged=NULL;
                  /* try strip exe from cmdline if setting */
                  const char* rest=cmd;
                  if(settings->strip_exe_from_cmdline){
                     /* if cmd starts with exe basename or full path, strip first token */
                     char* sp=strchr(cmd,' ');
                     if(sp) rest=sp+1;
                     else rest="";
                  }
                  if(settings->find_comm_in_cmdline && pr->comm){
                     /* if comm appears ??? */
                  }
                  size_t need=strlen(pr->exe_path)+ (pr->comm?strlen(pr->comm):0) + strlen(rest)+16;
                  merged=xmalloc(need);
                  if(pr->comm && strcmp(pr->comm,pr->exe?pr->exe:"")!=0) snprintf(merged,need,"%s (%s) %s",pr->exe_path,pr->comm,rest);
                  else if(rest && *rest) snprintf(merged,need,"%s %s",pr->exe_path,rest);
                  else snprintf(merged,need,"%s",pr->exe_path);
                  trim_trailing_spaces(merged);
                  pr->cmdline=merged;
                  free(cmd);
               } else pr->cmdline=cmd;
            } else {
               pr->cmdline=get_cmdline_for(pr->pid,pr->tgid,pr->comm,settings);
               if(pr->isThread && settings && settings->show_thread_names){
                  /* show thread names: comm of thread */
                  free(pr->cmdline); pr->cmdline=xstrdup(pr->comm?pr->comm:"");
               }
            }
            if(ce->cmdline_cached) free(ce->cmdline_cached);
            ce->cmdline_cached=xstrdup(pr->cmdline?pr->cmdline:"");
         }
         /* CPU percent */
         unsigned long long total=pr->utime+pr->stime;
         if(ce->hasPrev_is_set_marker){} /* placeholder */
         if(period>0){
            if(ce->lastSeen>0 && false){}
         }
         /* cache prev handling: we store prev_utime ..., but need a flag if existed before this scan. Use hasPrev from ce->firstSeen < now? If entry newly created, prev is 0 and firstSeen==now (approx). Determine by a custom field: we reuse ce->highlight (?) Instead track via prev stored and a field in ce: we use ce->prev_ values and a boolean stored in ce->tagged?? No.
            We'll use an extra static approach: if ce->cmdline_cached was just created and ce->firstSeen==now and period from prime scan is small, original process has been scanned in prime, so at second scan firstSeen < now.
            Simpler: add condition that if ce->prev_utime_stime !=0 or entry existed in previous scan (we can mark with ce->highlight field as seen-count). Use ce->highlight as seen count.
         */
         if(ce->highlight>0 && period>0){
            double deltaTicks=(double)( (long long)total - (long long)ce->prev_utime_stime );
            if(deltaTicks<0) deltaTicks=0;
            pr->percent_cpu = 100.0 * (deltaTicks/(double)clk_tck_global) / period;
         } else if(ce->highlight==0 && period>0){
            /* new process appearing between scans: if it started after last scan, use total/period; if start before last scan (should not happen except prime first scan where period may be 0 or ...) */
            double startEpoch=pr->starttime_epoch;
            double prevScanEpoch = now-period;
            if(startEpoch >= prevScanEpoch){
               double elapsedSinceStart = now - startEpoch;
               if(elapsedSinceStart>0.001){
                  /* original new busy gave total/period not total/elapsed. Use total/period to match observed 90% */
                  pr->percent_cpu = 100.0 * ((double)total/(double)clk_tck_global)/period;
               } else pr->percent_cpu=0;
            } else {
               pr->percent_cpu=0;
            }
            pr->isNewProc=1;
         } else {
            pr->percent_cpu=0;
         }
         if(pr->percent_cpu<0)pr->percent_cpu=0;
         /* I/O rates similar */
         if(ce->highlight>0 && period>0){
            pr->io_read_rate = (pr->io_read_bytes>=ce->prev_read_bytes)? (pr->io_read_bytes-ce->prev_read_bytes)/period:0;
            pr->io_write_rate = (pr->io_write_bytes>=ce->prev_write_bytes)? (pr->io_write_bytes-ce->prev_write_bytes)/period:0;
         } else { pr->io_read_rate=pr->io_write_rate=0; }
         ce->prev_utime_stime=total;
         ce->prev_read_bytes=pr->io_read_bytes;
         ce->prev_write_bytes=pr->io_write_bytes;
         ce->highlight++; /* reused as seen count >0 */
         /* counts */
         if(!pr->isThread){
            /* tasks counting: original counts processes? Tasks text: total includes ??? */
         }
         if(pr->state=='R') sysinfo.runningTasks++;
         if(pr->isThread) sysinfo.threadCount++;
         if(pr->isKernelThread) sysinfo.kernelThreadCount++;
         sysinfo.totalTasks++;
         pv_push(&vec,pr);
      }
   }
   closedir(d);
   lastScanTime=now;
   cache_prune(now);
   return vec;
}
EOF
"}

