   char state=0;
   unsigned long long vs=0;
   long rss=0;
   int num = sscanf(p," %c %d %d %d %d %d %lu %llu %llu %llu %llu %llu %llu %llu %llu %ld %ld %ld %*ld %llu %llu %ld",
      &state,&pr->ppid,&pr->pgrp,&pr->session,&pr->tty_nr,&pr->tpgid,&pr->flags,
