      &pr->priority,&pr->nice,&pr->nlwp,&pr->starttime_ticks,&vs,&rss);
   if(num<21) return 0;
   pr->state=state;
   pr->vsize=vs;
   pr->rss_pages=rss;
   /* processor is field 39 overall (index: after rp, tokens: need scan tokens to get processor at position (39-3)=36 zero? Let's tokenize */
   {
