      }
      free(dup);
   }
   return 1;
}
static char* get_cmdline_for(int pid, int tgid, const char* comm, Settings* settings){
   char path[128];
   if(tgid>0 && tgid!=pid) snprintf(path,sizeof(path),"/proc/%d/cmdline",tgid);
   else snprintf(path,sizeof(path),"/proc/%d/cmdline",pid);
   size_t len=0; char* data=read_file_alloc(path,&len);
   if(!data || len==0){ free(data); data=NULL; /* fallback below*/ }
   char* result=NULL;
   if(data && len>0){
      /* replace NUL with space, trim trailing spaces/NULs, remove trailing? Also replace newline etc? */
      for(size_t i=0;i<len;i++) if(data[i]=='\0') data[i]=' ';
      /* convert control chars? cmdline arguments may contain spaces itself; original keeps */
