      if(sk==COL_M_PSS||sk==COL_M_PSSWP||sk==COL_M_PRIV) need_pss=1;
      if(sk==COL_EXE) need_exe=1;
      if(sk==COL_CWD) need_cwd=1;
      if(sk==COL_COMM) need_commfile=1;
      if(sk==COL_SECATTR) need_secattr=1;
      if(sk==COL_AUTOGROUP_ID||sk==COL_AUTOGROUP_NICE) need_autogroup=1;
      if(sk==COL_SCHEDULERPOLICY) need_sched=1;
   } else { need_io=need_cgroup=need_exe=need_status_mem=1; }
   if(settings && settings->show_merged_command) need_exe=1;
   if(settings && settings->hide_running_in_container) need_cgroup=1;

   /* status for uid, memory details, ctxt */
   snprintf(path,sizeof(path),"/proc/%d/status",pid);
   char* status=read_file_alloc(path,NULL);
   pr->m_lrs_kib=0;
   if(status){
      char* save=NULL;
      for(char* line=strtok_r(status,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
         unsigned long long v;
         if(starts_with(line,"Uid:")){ unsigned int u; if(sscanf(line+4,"%u",&u)==1) pr->uid=(uid_t)u; }
         else if(starts_with(line,"Tgid:")) pr->tgid=atoi(line+5);
         else if(need_status_mem && sscanf(line,"VmExe: %llu",&v)==1) pr->m_trs_kib=v;
         else if(need_status_mem && sscanf(line,"VmLib: %llu",&v)==1) pr->m_lrs_kib=v;
         else if(need_status_mem && starts_with(line,"VmData:")){ unsigned long long vd=0,vs2=0; sscanf(line,"VmData: %llu",&vd); pr->m_drs_kib=vd; (void)vs2; }
         else if(need_status_mem && starts_with(line,"VmStk:")){ unsigned long long vs2=0; sscanf(line,"VmStk: %llu",&vs2); pr->m_drs_kib+=vs2; }
         else if(need_status_mem && sscanf(line,"VmSwap: %llu",&v)==1) pr->m_swap_kib=v;
         else if(starts_with(line,"voluntary_ctxt_switches:")) pr->ctxt += strtoull(line+24,NULL,10);
         else if(starts_with(line,"nonvoluntary_ctxt_switches:")) pr->ctxt += strtoull(line+27,NULL,10);
         else if(sscanf(line,"RssAnon: %llu",&v)==1 && need_pss) { /* private approximation */ if(pr->m_priv_kib==0) pr->m_priv_kib=v; else pr->m_priv_kib+=0; }
         else if(sscanf(line,"VmRSS: %llu",&v)==1) { if(!pr->isThread) pr->m_resident_kib=v; }
      }
      free(status);
   }
   /* statm: size resident shared text lib data dt in pages */
   snprintf(path,sizeof(path),"/proc/%d/statm",pid);
   {
      char buf[256]={0};
      if(read_small_file(path,buf,sizeof(buf))){
         unsigned long long size=0,res=0,share=0,text=0,lib=0,data=0;
         if(sscanf(buf,"%llu %llu %llu %llu %llu %llu",&size,&res,&share,&text,&lib,&data)>=6){
            unsigned long pgk=page_size_kib();
            if(!pr->isThread || 1){
               pr->m_virt_kib=size*pgk;
               if(pr->m_resident_kib==0) pr->m_resident_kib=res*pgk;
               if(pr->isThread) pr->m_share_kib=0; else pr->m_share_kib=share*pgk;
               if(pr->m_trs_kib==0) pr->m_trs_kib=text*pgk;
               if(pr->m_drs_kib==0) pr->m_drs_kib=data*pgk;
               (void)lib;
            }
         }
      }
   }
   if(pr->m_virt_kib==0) pr->m_virt_kib=pr->vsize/1024;
   if(pr->m_resident_kib==0 && pr->rss_pages>0) pr->m_resident_kib=(unsigned long long)pr->rss_pages*page_size_kib();
   if(need_status_mem && pr->m_lrs_kib==0){
      /* M_LRS observed=2432 for sleep despite VmLib 1796. Original (?) LRS calculated from maps shared libs? It showed ??? status VmLib might not match because maybe they use statm lib field (0 on modern kernel) - hmm 2432 is ??? exe size? Let's leave VmLib for now and revisit with maps calculation later */
   }
   /* PSS from smaps_rollup if needed */
   if(need_pss){
      snprintf(path,sizeof(path),"/proc/%d/smaps_rollup",pid);
      char* sm=read_file_alloc(path,NULL);
      if(sm){
         char* save=NULL;
         for(char* line=strtok_r(sm,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
            unsigned long long v;
            if(sscanf(line,"Pss: %llu",&v)==1) pr->m_pss_kib=v;
            else if(sscanf(line,"Pss_Swap: %llu",&v)==1) pr->m_psswp_kib=v;
            else if(sscanf(line,"Private_Clean: %llu",&v)==1) pr->m_priv_kib += v; /* combined w/ anon approx double count risk */
            else if(sscanf(line,"Private_Dirty: %llu",&v)==1) pr->m_priv_kib += v;
         }
         /* If priv was set from RssAnon plus private clean/dirty, it overcounts; recompute? Observed M_PRIV for sleep 92 which equals RssAnon (92) and also Private total likely 92. So private_clean+dirty alone should be used, not plus anon. Adjust: if private sum >0, use it but subtract initial RssAnon? We added both: messy */
         free(sm);
      }
      if(pr->m_pss_kib==0) pr->m_pss_kib=pr->m_resident_kib; /* fallback */
   } else {
      pr->m_pss_kib=pr->m_resident_kib;
   }
   if(need_io){
      /* io file per process (tgid) - thread io uses task io? Use pr->pid path if exists */
      snprintf(path,sizeof(path),"/proc/%d/io",pr->pid);
      char* io=read_file_alloc(path,NULL);
      if(!io){ snprintf(path,sizeof(path),"/proc/%d/io",pid); io=read_file_alloc(path,NULL); }
      if(io){
         char* save=NULL;
         for(char* line=strtok_r(io,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
            unsigned long long v;
            if(sscanf(line,"rchar: %llu",&v)==1) pr->io_rchar=v;
            else if(sscanf(line,"wchar: %llu",&v)==1) pr->io_wchar=v;
            else if(sscanf(line,"syscr: %llu",&v)==1) pr->io_syscr=v;
            else if(sscanf(line,"syscw: %llu",&v)==1) pr->io_syscw=v;
            else if(sscanf(line,"read_bytes: %llu",&v)==1) pr->io_read_bytes=v;
            else if(sscanf(line,"write_bytes: %llu",&v)==1) pr->io_write_bytes=v;
            else if(sscanf(line,"cancelled_write_bytes: %llu",&v)==1) pr->io_cancelled=v;
         }
         free(io);
      }
      get_io_priority(pr->pid,&pr->io_priority_class,&pr->io_priority_level);
      if(pr->io_priority_class==0){
         /* observed default display "B4" (Best-effort based on nice). Original maps IOPRIO_CLASS_NONE to display using nice-> BE level? Process_getIOPriority? We'll set display class 2 level (nice+20)/5 ??? For nice0 =>4 */
         pr->io_priority_class=2;
         int lvl=(int)((pr->nice+20)/5);
         if(lvl<0)lvl=0; if(lvl>7)lvl=7; pr->io_priority_level=lvl;
         /* mark that it was none via? Column IO_PRIORITY original returns ??? It displayed B4 for sleep */
      }
   }
   if(need_oom){
      snprintf(path,sizeof(path),"/proc/%d/oom_score",pid);
      char buf[64]={0}; if(read_small_file(path,buf,sizeof(buf))) pr->oom=atoi(buf);
   }
   if(need_cgroup){
      snprintf(path,sizeof(path),"/proc/%d/cgroup",pid);
      char* cg=read_file_alloc(path,NULL);
      char* raw=NULL;
      if(cg){
         /* lines hierarchy:subsystems:path ; use last (0::) path */
         char* save=NULL;
         for(char* line=strtok_r(cg,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
            char* first=strchr(line,':'); if(!first) continue;
            char* second=strchr(first+1,':'); if(!second) continue;
            free(raw); raw=xstrdup(second+1);
         }
         free(cg);
      }
      pr->cgroup=raw?raw:xstrdup("/");
      pr->ccgroup=condense_cgroup(pr->cgroup);
      int isc=0; pr->container=guess_container(pr->cgroup,&isc); pr->is_container=isc;
   }
   if(need_commfile){
      snprintf(path,sizeof(path),"/proc/%d/comm",pr->pid);
      char buf[256]={0};
      if(read_small_file(path,buf,sizeof(buf))){
         /* replace comm for thread?? Only use for COMM column; comm field stores it. Keep pr->comm as task comm from stat which is same */
      }
   }
   if(need_exe || settings->show_merged_command){
      snprintf(path,sizeof(path),"/proc/%d/exe",pid);
      char buf[PATH_MAX]; ssize_t n=readlink(path,buf,sizeof(buf)-1);
      if(n>=0){ buf[n]=0; pr->exe_path=xstrdup(buf);
         /* (deleted) suffix */
         const char* suffix=" (deleted)";
         size_t bl=strlen(buf);
         if(bl>strlen(suffix) && strcmp(buf+bl-strlen(suffix),suffix)==0){ pr->exe_deleted=1; buf[bl-strlen(suffix)]=0; }
         const char* base=strrchr(buf,'/');
         pr->exe=xstrdup(base?base+1:buf);
      } else {
         pr->exe=xstrdup("");
      }
   }
   if(need_cwd){
      snprintf(path,sizeof(path),"/proc/%d/cwd",pid);
      char buf[PATH_MAX]; ssize_t n=readlink(path,buf,sizeof(buf)-1);
      if(n>=0){buf[n]=0; pr->cwd=xstrdup(buf);} else pr->cwd=xstrdup("");
   }
   if(need_secattr){
      snprintf(path,sizeof(path),"/proc/%d/attr/current",pid);
      size_t l=0; char* data=read_file_alloc(path,&l);
      if(data){ /* string may have trailing NUL; data len */ pr->secattr=trim_newline_dup(data); free(data); } else pr->secattr=xstrdup("");
   }
   if(need_autogroup){
      snprintf(path,sizeof(path),"/proc/%d/autogroup",pid);
      char buf[256]={0};
      if(read_small_file(path,buf,sizeof(buf))){
         long aid=0, anice=0;
         if(sscanf(buf,"/autogroup-%ld nice %ld",&aid,&anice)==2){ pr->autogroup_id=aid; pr->autogroup_nice=anice; }
      }
   }
   if(need_sched){
      pr->sched_policy=sched_getscheduler(pr->pid);
      if(pr->sched_policy<0) pr->sched_policy=0;
   }
   pr->user=xstrdup(user_name(pr->uid));
   if(sysinfo.memTotal>0) pr->percent_mem=100.0*(double)pr->m_resident_kib/(double)sysinfo.memTotal;
   /* TTY name */
   if(pr->tty_nr==0) pr->tty_name=xstrdup("(no tty)");
   else {
      /* decode dev_t: major=(tty>>8), minor=(tty&255)|((tty>>20)<<8) for pts? Simplistic look up via /proc/<pid>/fd/0 ? Or use pts naming: if major 136 pts/minor, 5 ptmx, 4 tty/minor */
      int major=(pr->tty_nr>>8)&0xfff;
      int minor=(pr->tty_nr&0xff) | ((pr->tty_nr>>12)&0xfff00);
      char buf[64];
      if(major==136) snprintf(buf,sizeof(buf),"pts/%d",minor);
      else if(major==4){ if(minor<64) snprintf(buf,sizeof(buf),"tty%d",minor); else snprintf(buf,sizeof(buf),"ttyS%d",minor-64); }
      else if(major==5 && minor==0) snprintf(buf,sizeof(buf),"tty");
      else if(major==5 && minor==1) snprintf(buf,sizeof(buf),"console");
      else snprintf(buf,sizeof(buf),"%d:%d",major,minor);
      pr->tty_name=xstrdup(buf);
   }
}

static void free_proc(Proc* p){
   if(!p) return;
   free(p->comm); free(p->cmdline); free(p->exe); free(p->exe_path); free(p->cwd); free(p->cgroup); free(p->ccgroup); free(p->container); free(p->secattr); free(p->tty_name); free(p->user); free(p->tree_prefix);
   free(p);
}

static double lastScanTime=0;
static ProcVec scan_processes(Settings* settings, ScreenCfg* activeScreen, int primeOnly){
   (void)primeOnly;
   sysinfo_scan_cpu();
   sysinfo_scan_mem();
   sysinfo_scan_io();
   double now=now_sec();
   double period = lastScanTime>0 ? (now-lastScanTime) : 0;
   ProcVec vec={0};
   DIR* d=opendir("/proc");
   if(!d) return vec;
   struct dirent* ent;
   sysinfo.totalTasks=0; sysinfo.runningTasks=0; sysinfo.threadCount=0; sysinfo.kernelThreadCount=0;
   while((ent=readdir(d))!=NULL){
      if(!isdigit((unsigned char)ent->d_name[0])) continue;
      int pid=atoi(ent->d_name);
      if(pid<=0) continue;
      /* collect task ids */
      int tids[1024]; int ntids=0;
      tids[ntids++]=pid;
      char taskpath[128]; snprintf(taskpath,sizeof(taskpath),"/proc/%d/task",pid);
      DIR* td=opendir(taskpath);
      if(td){
         struct dirent* te;
         while((te=readdir(td))!=NULL){
            if(!isdigit((unsigned char)te->d_name[0]))continue;
            int tid=atoi(te->d_name);
            if(tid!=pid && ntids<1024) tids[ntids++]=tid;
         }
         closedir(td);
      }
      for(int ti=0; ti<ntids; ti++){
         int tid=tids[ti];
         int isThread = (tid!=pid);
         /* We'll still scan thread for counts; later filtering hides if hide_userland */
         char statpath[192];
         if(isThread) snprintf(statpath,sizeof(statpath),"/proc/%d/task/%d/stat",pid,tid);
         else snprintf(statpath,sizeof(statpath),"/proc/%d/stat",pid);
         char* content=read_file_alloc(statpath,NULL);
         if(!content) continue;
         Proc* pr=xcalloc(1,sizeof(Proc));
         pr->pid=tid; pr->tgid=pid; pr->isThread=isThread; pr->show_children=1; pr->sched_policy=0;
         char* comm=NULL;
         if(!parse_stat_content(content,pr,&comm)){ free(content); free(pr); free(comm); continue; }
         free(content);
         pr->comm=comm;
         /* kernel thread if PF_KTHREAD 0x200000 */
         pr->isKernelThread = (pr->flags & 0x200000) ? 1:0;
         /* TGID from status later overwritten? Keep pid (tgid) as set */
         /* starttime epoch */
         if(sysinfo.btime==0){
            /* read btime if not yet: scan_cpu already may have set while reading /proc/stat until intr break may miss btime which is after cpu lines? btime is after cpu/intr etc, our break at intr misses it. Read separately if zero */
            FILE* bf=fopen("/proc/stat","r");
            if(bf){ char* l=NULL; size_t c=0; while(getline(&l,&c,bf)>0){ if(strncmp(l,"btime",5)==0){ sysinfo.btime=strtol(l+6,NULL,10); break; } } free(l); fclose(bf); }
         }
         pr->starttime_epoch = (double)sysinfo.btime + (double)pr->starttime_ticks/(double)clk_tck_global;
         pr->elapsed = ((double)time(NULL) - pr->starttime_epoch);
         if(pr->elapsed<0) pr->elapsed=0;
         /* fill aux */
         fill_proc_aux(pr,settings,activeScreen);
         /* command */
         CacheEntry* ce=cache_get(pr->pid,pr->starttime_ticks,1);
         ce->lastSeen=now;
         pr->seenTime=ce->firstSeen;
         pr->tagged=ce->tagged;
         pr->show_children=ce->show_children;
         pr->collapsed = !ce->show_children;
         if(settings && !settings->update_process_names && ce->cmdline_cached){
            pr->cmdline=xstrdup(ce->cmdline_cached);
         } else {
            if(settings && settings->show_merged_command){
               /* merged: construct "exe (comm) cmdline..." approximation - refine later */
               char* cmd=get_cmdline_for(pr->pid,pr->tgid,pr->comm,NULL); /* without path stripping */
               /* Build merged string: if exe_path available and not in cmd, prefix? htop merged format: "exe comm cmdline"? Search memory: merged shows "/usr/bin/python3 (python3) -options" ??? We'll implement as below and refine via tests */
               if(pr->exe_path && pr->exe_path[0]){
                  char* merged=NULL;
                  /* try strip exe from cmdline if setting */
                  const char* rest=cmd;
                  if(settings->strip_exe_from_cmdline){
                     /* if cmd starts with exe basename or full path, strip first token */
                     char* sp=strchr(cmd,' ');
                     if(sp) rest=sp+1;
                     else rest="";
                  }
                  if(settings->find_comm_in_cmdline && pr->comm){
                     /* if comm appears ??? */
                  }
                  size_t need=strlen(pr->exe_path)+ (pr->comm?strlen(pr->comm):0) + strlen(rest)+16;
                  merged=xmalloc(need);
                  if(pr->comm && strcmp(pr->comm,pr->exe?pr->exe:"")!=0) snprintf(merged,need,"%s (%s) %s",pr->exe_path,pr->comm,rest);
                  else if(rest && *rest) snprintf(merged,need,"%s %s",pr->exe_path,rest);
                  else snprintf(merged,need,"%s",pr->exe_path);
                  trim_trailing_spaces(merged);
                  pr->cmdline=merged;
                  free(cmd);
               } else pr->cmdline=cmd;
            } else {
               pr->cmdline=get_cmdline_for(pr->pid,pr->tgid,pr->comm,settings);
               if(pr->isThread && settings && settings->show_thread_names){
                  /* show thread names: comm of thread */
                  free(pr->cmdline); pr->cmdline=xstrdup(pr->comm?pr->comm:"");
               }
            }
            if(ce->cmdline_cached) free(ce->cmdline_cached);
            ce->cmdline_cached=xstrdup(pr->cmdline?pr->cmdline:"");
         }
         /* CPU percent */
         unsigned long long total=pr->utime+pr->stime;
         if(ce->hasPrev_is_set_marker){} /* placeholder */
         if(period>0){
            if(ce->lastSeen>0 && false){}
         }
         /* cache prev handling: we store prev_utime ..., but need a flag if existed before this scan. Use hasPrev from ce->firstSeen < now? If entry newly created, prev is 0 and firstSeen==now (approx). Determine by a custom field: we reuse ce->highlight (?) Instead track via prev stored and a field in ce: we use ce->prev_ values and a boolean stored in ce->tagged?? No.
            We'll use an extra static approach: if ce->cmdline_cached was just created and ce->firstSeen==now and period from prime scan is small, original process has been scanned in prime, so at second scan firstSeen < now.
            Simpler: add condition that if ce->prev_utime_stime !=0 or entry existed in previous scan (we can mark with ce->highlight field as seen-count). Use ce->highlight as seen count.
         */
         if(ce->highlight>0 && period>0){
            double deltaTicks=(double)( (long long)total - (long long)ce->prev_utime_stime );
            if(deltaTicks<0) deltaTicks=0;
            pr->percent_cpu = 100.0 * (deltaTicks/(double)clk_tck_global) / period;
         } else if(ce->highlight==0 && period>0){
            /* new process appearing between scans: if it started after last scan, use total/period; if start before last scan (should not happen except prime first scan where period may be 0 or ...) */
            double startEpoch=pr->starttime_epoch;
            double prevScanEpoch = now-period;
            if(startEpoch >= prevScanEpoch){
               double elapsedSinceStart = now - startEpoch;
               if(elapsedSinceStart>0.001){
                  /* original new busy gave total/period not total/elapsed. Use total/period to match observed 90% */
                  pr->percent_cpu = 100.0 * ((double)total/(double)clk_tck_global)/period;
               } else pr->percent_cpu=0;
            } else {
               pr->percent_cpu=0;
            }
            pr->isNewProc=1;
         } else {
            pr->percent_cpu=0;
         }
         if(pr->percent_cpu<0)pr->percent_cpu=0;
         /* I/O rates similar */
         if(ce->highlight>0 && period>0){
            pr->io_read_rate = (pr->io_read_bytes>=ce->prev_read_bytes)? (pr->io_read_bytes-ce->prev_read_bytes)/period:0;
            pr->io_write_rate = (pr->io_write_bytes>=ce->prev_write_bytes)? (pr->io_write_bytes-ce->prev_write_bytes)/period:0;
         } else { pr->io_read_rate=pr->io_write_rate=0; }
         ce->prev_utime_stime=total;
         ce->prev_read_bytes=pr->io_read_bytes;
         ce->prev_write_bytes=pr->io_write_bytes;
         ce->highlight++; /* reused as seen count >0 */
         /* counts */
         if(!pr->isThread){
            /* tasks counting: original counts processes? Tasks text: total includes ??? */
         }
         if(pr->state=='R') sysinfo.runningTasks++;
         if(pr->isThread) sysinfo.threadCount++;
         if(pr->isKernelThread) sysinfo.kernelThreadCount++;
         sysinfo.totalTasks++;
         pv_push(&vec,pr);
      }
   }
   closedir(d);
   lastScanTime=now;
   cache_prune(now);
   return vec;
}
EOF
"}

