/* Comparison */
static int cmp_longlong(long long a,long long b){ return (a>b)-(a<b); }
static int cmp_ull(unsigned long long a,unsigned long long b){ return (a>b)-(a<b); }
static int cmp_double(double a,double b){ if(a<b)return -1; if(a>b)return 1; return 0; }
static int proc_compare_by_key(Proc* a, Proc* b, int key){
   switch(key){
      case COL_PID: return cmp_longlong(a->pid,b->pid);
      case COL_Command: return strcmp(a->cmdline?a->cmdline:"", b->cmdline?b->cmdline:"");
      case COL_STATE: return cmp_longlong((unsigned char)a->state,(unsigned char)b->state);
