      case COL_NLWP: return cmp_longlong(a->nlwp,b->nlwp);
      case COL_TGID: return cmp_longlong(a->tgid,b->tgid);
      case COL_PERCENT_NORM_CPU: return cmp_double(a->percent_cpu,b->percent_cpu);
      case COL_ELAPSED: return cmp_double(a->elapsed,b->elapsed);
      case COL_SCHEDULERPOLICY: return cmp_longlong(a->sched_policy,b->sched_policy);
      case COL_RCHAR: return cmp_ull(a->io_rchar,b->io_rchar);
      case COL_WCHAR: return cmp_ull(a->io_wchar,b->io_wchar);
      case COL_SYSCR: return cmp_ull(a->io_syscr,b->io_syscr);
