      case COL_CNCLWB: return cmp_ull(a->io_cancelled,b->io_cancelled);
      case COL_IO_READ_RATE: return cmp_double(a->io_read_rate,b->io_read_rate);
      case COL_IO_WRITE_RATE: return cmp_double(a->io_write_rate,b->io_write_rate);
      case COL_IO_RATE: return cmp_double(a->io_read_rate+a->io_write_rate,b->io_read_rate+b->io_write_rate);
      case COL_CGROUP: return strcmp(a->cgroup?a->cgroup:"",b->cgroup?b->cgroup:"");
      case COL_OOM: return cmp_longlong(a->oom,b->oom);
      case COL_IO_PRIORITY: {
         int av=(a->io_priority_class<<8)|a->io_priority_level;
