      case COL_AUTOGROUP_NICE: return cmp_longlong(a->autogroup_nice,b->autogroup_nice);
      case COL_CCGROUP: return strcmp(a->ccgroup?a->ccgroup:"",b->ccgroup?b->ccgroup:"");
