      case COL_M_PRIV: return cmp_ull(a->m_priv_kib,b->m_priv_kib);
      case COL_GPU_TIME: return 0;
      case COL_GPU_PERCENT: return 0;
      case COL_ISCONTAINER: return cmp_longlong(a->is_container,b->is_container);
      default: return cmp_longlong(a->pid,b->pid);
   }
}
static int g_sort_key=COL_PERCENT_CPU, g_sort_dir=-1;
static int proc_qcmp(const void* pa, const void* pb){
   Proc* a=*(Proc* const*)pa; Proc* b=*(Proc* const*)pb;
   int r=proc_compare_by_key(a,b,g_sort_key);
   if(r!=0) return r*g_sort_dir;
   /* tie break by pid ascending (?) need check if direction influences tie. For now ascend always except when sort_key is PID direction already handled */
   return cmp_longlong(a->pid,b->pid);
}
