         int already=0; for(int i=0;i<res->display.count;i++) if(res->display.items[i]==pr){already=1;break;}
         if(already){ free(it.displayPrefix); free(it.childBasePrefix); continue; }
         pr->tree_depth=it.depth;
         free(pr->tree_prefix); pr->tree_prefix=it.displayPrefix; /* take ownership */
         pv_push(&res->display,pr);
         /* if collapsed (show_children==0) do not traverse children */
         if(pr->show_children || screen->all_branches_collapsed==0 && pr->show_children){
            /* collect children in sorted order (visible is sorted) */
            /* determine list first to know last */
            Proc* children[4096]; int nchild=0;
            for(int i=0;i<n && nchild<4096;i++){
               Proc* ch=visible.items[i];
               int effP=ch->isThread? ch->tgid: ch->ppid;
               if(effP==pr->pid && ch!=pr) children[nchild++]=ch;
            }
            /* push reverse */
            for(int ci=nchild-1; ci>=0; ci--){
               Proc* ch=children[ci];
               int isLast=(ci==nchild-1);
               /* display prefix for child */
               char* disp=NULL;
               const char* branch = isLast? "`- " : "|- ";
               if(it.depth==0){
                  /* child of root display prefix is just branch, unless root ??? example child of 1: "`- cmd" ; child of another root (523) python: "`- " also */
                  disp=xstrdup(branch);
               } else {
                  disp=str_cat3(it.childBasePrefix,branch,NULL);
               }
               /* childBasePrefix for grandchildren: base derived from child's position relative to parent */
               char* childBase=NULL;
               const char* continuation = isLast? "   " : "|  ";
               if(it.depth==0){
                  childBase=xstrdup(continuation);
               } else {
                  childBase=str_cat3(it.childBasePrefix,continuation,NULL);
               }
               if(sp>=n+16){ stack=xrealloc(stack,sizeof(StackItem)*( (n+16)*2)); }
               stack[sp].pr=ch; stack[sp].depth=it.depth+1; stack[sp].displayPrefix=disp; stack[sp].childBasePrefix=childBase; sp++;
            }
         }
         free(it.childBasePrefix);
      }
      free(stack); free(visited);
      free(visible.items);
      /* Edge: any visible not displayed due cycle / parent hidden collapsed (?) If parent collapsed, children intentionally not displayed (they were not pushed). If cycle unrelated, append remaining sorted */
      /* Note collapsed children already: they won't be in display; but our traversal only pushes children if show_children, so remaining check would erroneously append them. Need distinguish: Only append those whose ancestors not collapsed and parentExists but not visited due cycle. This is rare; skip append to preserve collapse behavior */
   }
}
static void free_scan(ScanResult* res){
   for(int i=0;i<res->all.count;i++) free_proc(res->all.items[i]);
   free(res->all.items); free(res->display.items);
   memset(res,0,sizeof(*res));
}

