      draw_meter(y,x,w1,"Memory",1,settings,scan);
      draw_meter(y,x+w1,w2,"Swap",1,settings,scan);
      return;
   }
   if(strcmp(name,"LoadAverage")==0){
      BarSeg segs[1]={{sysinfo.load1,CP_CPU_NORMAL,'|'}};
      char ov[64]; snprintf(ov,sizeof(ov),"%.2f/%.2f/%.2f",sysinfo.load1,sysinfo.load5,sysinfo.load15);
      draw_bar_generic(y,x,width,"Loa",segs,1,(double)sysinfo.cpuCount,ov); return;
   }
   if(strcmp(name,"Load")==0){
      BarSeg segs[1]={{sysinfo.load1,CP_CPU_NORMAL,'|'}}; char ov[32]; snprintf(ov,sizeof(ov),"%.2f",sysinfo.load1);
      draw_bar_generic(y,x,width,"Loa",segs,1,(double)sysinfo.cpuCount,ov); return;
   }
   if(strcmp(name,"Tasks")==0){
      /* Bar segments by states: approximate total tasks filled with sleeping (?) plus running */
      int total=sysinfo.totalTasks; int run=sysinfo.procsRunning;
      BarSeg segs[2]={{(double)(total-run>0?total-run:0),CP_CPU_NORMAL,'|'},{(double)run,CP_CPU_KERNEL,'|'}};
      char ov[64]; snprintf(ov,sizeof(ov),"%d/%d",run,total);
