static int compute_header_height(Settings* settings,int hideMeters){
   if(hideMeters) return 0;
   int layoutIdx=header_layout_index(settings->header_layout);
   int ncols=header_layout_num_cols(layoutIdx);
   int maxh=0;
   for(int c=0;c<ncols;c++){
      int h=0;
      for(int i=0;i<settings->header[c].meters.count;i++){
         int mode=i<settings->header[c].modes.count?settings->header[c].modes.items[i]:2;
         h+=meter_height(settings->header[c].meters.items[i],mode,settings);
      }
      if(h>maxh)maxh=h;
   }
   if(settings->header_margin) maxh+=2; /* top and bottom blank */
   return maxh;
}
static void draw_header(Settings* settings,ScanResult* scan,int hideMeters){
   if(hideMeters) return;
   int termW=getmaxx(stdscr);
   int margin=settings->header_margin?2:0;
   int totalWidth=termW - (settings->header_margin?4:0);
   if(totalWidth<0)totalWidth=0;
   int layoutIdx=header_layout_index(settings->header_layout);
   int perc[4]={0}; int ncols=0; header_layout_percents(layoutIdx,perc,&ncols);
   int startY=settings->header_margin?1:0;
   int cumulative=0;
   for(int c=0;c<ncols;c++){
      int nextCum=cumulative+perc[c];
      int x0 = margin + (int)lround((double)totalWidth*cumulative/100.0);
      int x1 = (c==ncols-1)? margin+totalWidth : margin + (int)lround((double)totalWidth*nextCum/100.0);
      int colW=x1-x0;
      int meterW=colW;
      if(c<ncols-1) meterW=colW-1;
      if(meterW<0)meterW=0;
      int y=startY;
      for(int i=0;i<settings->header[c].meters.count;i++){
         const char* mn=settings->header[c].meters.items[i];
         int mode=i<settings->header[c].modes.count?settings->header[c].modes.items[i]:2;
         draw_meter(y,x0,meterW,mn,mode,settings,scan);
         y+=meter_height(mn,mode,settings);
      }
      cumulative=nextCum;
   }
}

