   if(width<=0) return;
   int caplen=strlen(caption);
   draw_text_at(y,x,caption,CP_METER_TEXT,0,x+width);
   int bx=x+caplen;
   if(bx>=x+width) return;
   draw_text_at(y,bx,"[",CP_DEFAULT,A_BOLD,x+width);
   int barInner = width - caplen -2;
   if(barInner<0) barInner=0;
   int rx=bx+1;
   /* compute fill counts per seg */
   int filled[16]={0}; int filledTotal=0;
   if(total>0){
      double acc=0;
      for(int i=0;i<nsegs && i<16;i++){
         double frac=segs[i].value/total;
         if(frac<0)frac=0; if(frac>1)frac=1;
         int till=(int)lround((acc+segs[i].value)/total * barInner);
         int from=(int)lround(acc/total*barInner);
         if(till>barInner)till=barInner; if(from<0)from=0;
         filled[i]=till-from; if(filled[i]<0)filled[i]=0;
         acc+=segs[i].value;
      }
      for(int i=0;i<nsegs&&i<16;i++) filledTotal+=filled[i];
   }
   /* draw interiors: segments then spaces, then overlay text right-aligned replacing tail */
   char* interior=xmalloc(barInner+1);
   for(int i=0;i<barInner;i++) interior[i]=' ';
   interior[barInner]=0;
   /* We'll draw segment runs directly to preserve colors, then blanks, then overlay */
   int pos=0;
   for(int i=0;i<nsegs&&i<16;i++){
      for(int k=0;k<filled[i] && pos<barInner;k++){
         char s[2]={(char)segs[i].ch,0};
         draw_text_at(y,rx+pos,s,segs[i].colorPair,0,x+width);
         pos++;
      }
   }
   /* fill spaces are already blank from screen clear but ensure */
   if(overlay && *overlay){
      int olen=strlen(overlay);
      if(olen>barInner){
         /* truncate overlay to barInner from left (first chars) as observed for CPU */
         /* But Memory overlay is right aligned and should fit */
         char* trunc=xstrndup(overlay,barInner);
         draw_text_at(y,rx,trunc,CP_DEFAULT,A_BOLD,x+width);
         free(trunc);
      } else {
         int ox=rx+barInner-olen;
         draw_text_at(y,ox,overlay,CP_DEFAULT,A_BOLD,x+width);
      }
   }
   free(interior);
   if(bx+1+barInner < x+width) draw_text_at(y,bx+1+barInner,"]",CP_DEFAULT,A_BOLD,x+width);
}

/* History for graph meters */
#define GRAPH_HISTORY 256
typedef struct GraphHist { char name[64]; double values[GRAPH_HISTORY]; int idx; int count; double total; struct GraphHist* next; } GraphHist;
static GraphHist* graphHists=NULL;
static GraphHist* graph_hist_for(const char* name,double total){
   for(GraphHist* g=graphHists;g;g=g->next) if(strcmp(g->name,name)==0) return g;
   GraphHist* g=xcalloc(1,sizeof(GraphHist)); strncpy(g->name,name,sizeof(g->name)-1); g->total=total; g->next=graphHists; graphHists=g; return g;
}
static void graph_push(const char* name,double value,double total){
   GraphHist* g=graph_hist_for(name,total); g->total=total; g->values[g->idx]=value; g->idx=(g->idx+1)%GRAPH_HISTORY; if(g->count<GRAPH_HISTORY)g->count++;
}

