static int cpu_group_params(const char* name,int* start,int* count,int* subcols){
   int total=sysinfo.cpuCount; int half=(total+1)/2;
   /* Which half is first? Left gets ceil? For 96 equal. For odd, need original: first half likely (count+1)/2 */
   if(strcmp(name,"AllCPUs")==0){*start=0;*count=total;*subcols=1;return 1;}
   if(strcmp(name,"AllCPUs2")==0){*start=0;*count=total;*subcols=2;return 1;}
   if(strcmp(name,"AllCPUs4")==0){*start=0;*count=total;*subcols=4;return 1;}
   if(strcmp(name,"AllCPUs8")==0){*start=0;*count=total;*subcols=8;return 1;}
   if(strcmp(name,"LeftCPUs")==0){*start=0;*count=half;*subcols=1;return 1;}
   if(strcmp(name,"RightCPUs")==0){*start=half;*count=total-half;*subcols=1;return 1;}
   if(strcmp(name,"LeftCPUs2")==0){*start=0;*count=half;*subcols=2;return 1;}
   if(strcmp(name,"RightCPUs2")==0){*start=half;*count=total-half;*subcols=2;return 1;}
   if(strcmp(name,"LeftCPUs4")==0){*start=0;*count=half;*subcols=4;return 1;}
   if(strcmp(name,"RightCPUs4")==0){*start=half;*count=total-half;*subcols=4;return 1;}
   if(strcmp(name,"LeftCPUs8")==0){*start=0;*count=half;*subcols=8;return 1;}
   if(strcmp(name,"RightCPUs8")==0){*start=half;*count=total-half;*subcols=8;return 1;}
   return 0;
}
static int meter_height(const char* name,int mode,Settings* settings){
   if(strcmp(name,"!")==0) return 0;
   int start,count,subcols;
   if(cpu_group_params(name,&start,&count,&subcols)){
      if(count<=0)return 0;
      int rows=(count+subcols-1)/subcols;
      if(mode==3) return rows*3; /* graph height unknown approximation */
      if(mode==4) return rows*3;
      return rows;
   }
   if(mode==3 && meter_supports_bar(name)) return 3; /* graph meters are typically 3-4 rows? check later */
   if(mode==4 && meter_supports_bar(name)) return 3;
   /* MemorySwap & DiskIO combined are 1 */
   return 1;
}
static void draw_cpu_bar_cell(int y,int x,int width,int cpu,Settings* settings){
   if(width<=0)return;
   char caption[32]; cpu_label(cpu,caption,sizeof(caption),settings);
   /* caption color and label (?) */
   double user=sysinfo.cpuUser[cpu], nice=sysinfo.cpuNice[cpu], sys=sysinfo.cpuSystem[cpu], guest=sysinfo.cpuGuest[cpu];
   double iowait=sysinfo.cpuIOWait[cpu], irq=sysinfo.cpuIrq[cpu], soft=sysinfo.cpuSoftIrq[cpu], steal=sysinfo.cpuSteal[cpu];
   BarSeg segs[8]; int n=0;
   if(settings->detailed_cpu_time){
      segs[n++]=(BarSeg){nice,CP_CPU_NICE,'|'};
      segs[n++]=(BarSeg){user,CP_CPU_NORMAL,'|'};
      segs[n++]=(BarSeg){sys,CP_CPU_KERNEL,'|'};
      segs[n++]=(BarSeg){iowait,CP_CPU_IOWAIT,'|'};
      segs[n++]=(BarSeg){irq,CP_CPU_IRQ,'|'};
      segs[n++]=(BarSeg){soft,CP_CPU_SOFTIRQ,'|'};
      segs[n++]=(BarSeg){steal,CP_CPU_STEAL,'|'};
      segs[n++]=(BarSeg){guest,CP_CPU_GUEST,'|'};
   } else {
      /* Help: low/normal/kernel/guest */
      segs[n++]=(BarSeg){nice,CP_CPU_NICE,'|'};
      segs[n++]=(BarSeg){user,CP_CPU_NORMAL,'|'};
      segs[n++]=(BarSeg){sys+iowait+irq+soft+steal,CP_CPU_KERNEL,'|'};
      segs[n++]=(BarSeg){guest,CP_CPU_GUEST,'|'};
   }
   char overlay[64]="";
   if(settings->show_cpu_usage){
      double pct=sysinfo.cpuPercent[cpu];
      if(settings->show_cpu_frequency && sysinfo.cpuFreqMHz[cpu]>0){
         /* Frequency appended? format unknown */
         snprintf(overlay,sizeof(overlay),"%.1f%%",pct);
      } else snprintf(overlay,sizeof(overlay),"%.1f%%",pct);
   }
   /* Special truncation for bar: draw_bar_generic right-aligns if fits, else trunc left start. But CPU bars overlay expected is right aligned if fits, else first chars at left as observed. Our draw_bar handles >inner by left trunc start at rx. Good */
   draw_bar_generic(y,x,width,caption,segs,n,100.0,overlay);
}
static void draw_cpu_meter_as_mode(int y,int x,int width,int cpu,int mode,Settings* settings,ScanResult* scan){
   if(mode==2 || !meter_supports_bar("CPU")){
      char buf[256]; char namebuf[32]; snprintf(namebuf,sizeof(namebuf),"CPU(%d)",cpu+1); meter_full_text_line(namebuf,settings,buf,sizeof(buf),scan);
