      BarSeg segs[1]={{(double)used,CP_MEM_USED,'|'}}; char u[32],t[32],ov[64]; format_size_bytes_text(u,sizeof(u),used*1024ULL); format_size_bytes_text(t,sizeof(t),total*1024ULL); snprintf(ov,sizeof(ov),"%s/%s",u,t);
