   if(strcmp(name,"ZFSARC")==0){ draw_bar_generic(y,x,width,"ARC",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"0K/0K"); return; }
   if(strcmp(name,"ZFSCARC")==0){ draw_bar_generic(y,x,width,"ARC",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"N/A"); return; }
