         }
      }
      return;
   }
   int cpuIdx;
   if(meter_is_cpu_single(name,&cpuIdx)){
      draw_cpu_meter_as_mode(y,x,width,cpuIdx,mode,settings,scan);
      return;
   }
   if(strcmp(name,"CPU")==0){
      if(mode==2){ char buf[256]; meter_full_text_line(name,settings,buf,sizeof(buf),scan); draw_text_at(y,x,buf,CP_METER_TEXT,0,x+width); return; }
      /* Bar average like a CPU cell with caption Avg */
      double u=0,ni=0,sy=0,gu=0,io=0,irq=0,soft=0,steal=0; int n=sysinfo.cpuCount;
      for(int i=0;i<n;i++){u+=sysinfo.cpuUser[i]; ni+=sysinfo.cpuNice[i]; sy+=sysinfo.cpuSystem[i]; gu+=sysinfo.cpuGuest[i]; io+=sysinfo.cpuIOWait[i]; irq+=sysinfo.cpuIrq[i]; soft+=sysinfo.cpuSoftIrq[i]; steal+=sysinfo.cpuSteal[i];}
      if(n){u/=n;ni/=n;sy/=n;gu/=n;io/=n;irq/=n;soft/=n;steal/=n;}
      BarSeg segs[8]; int ns=0;
      if(settings->detailed_cpu_time){ segs[ns++]=(BarSeg){ni,CP_CPU_NICE,'|'}; segs[ns++]=(BarSeg){u,CP_CPU_NORMAL,'|'}; segs[ns++]=(BarSeg){sy,CP_CPU_KERNEL,'|'}; segs[ns++]=(BarSeg){io,CP_CPU_IOWAIT,'|'}; segs[ns++]=(BarSeg){irq,CP_CPU_IRQ,'|'}; segs[ns++]=(BarSeg){soft,CP_CPU_SOFTIRQ,'|'}; segs[ns++]=(BarSeg){steal,CP_CPU_STEAL,'|'}; segs[ns++]=(BarSeg){gu,CP_CPU_GUEST,'|'}; }
      else { segs[ns++]=(BarSeg){ni,CP_CPU_NICE,'|'}; segs[ns++]=(BarSeg){u,CP_CPU_NORMAL,'|'}; segs[ns++]=(BarSeg){sy+io+irq+soft+steal,CP_CPU_KERNEL,'|'}; segs[ns++]=(BarSeg){gu,CP_CPU_GUEST,'|'}; }
      char ov[32]; if(settings->show_cpu_usage) snprintf(ov,sizeof(ov),"%.1f%%",cpu_avg_percent()); else ov[0]=0;
      draw_bar_generic(y,x,width,"Avg",segs,ns,100.0,ov);
