   int effMode=mode;
   if(mode==3 || mode==4){
      /* We'll implement simple graph as bar for now (refine later) */
      effMode=1;
   }
   if(effMode==2 || !meter_supports_bar(name)){
      if(strcmp(name,"MemorySwap")==0 && effMode==2){
         /* Memory and Swap text side by side: first Mem segment uses about half width? At wide capture Mem full text then spaces then Swp at... Use two subtexts with Mem drawn into first (?) Width split = width * ??? In capture at width 220 (?) Swp started at position after Mem text plus spaces to a fixed (?) It had Mem line length about 80 and Swp starts at maybe 110 (half). Implement half split */
         char m[512],s[512]; meter_full_text_line("Memory",settings,m,sizeof(m),scan); meter_full_text_line("Swap",settings,s,sizeof(s),scan);
         int half=width/2;
         draw_text_at(y,x,m,CP_METER_TEXT,0,x+half);
         draw_text_at(y,x+half,s,CP_METER_TEXT,0,x+width);
         return;
      }
      if(strcmp(name,"DiskIO")==0 && effMode==2){ char buf[512]; meter_full_text_line(name,settings,buf,sizeof(buf),scan); draw_text_at(y,x,buf,CP_METER_TEXT,0,x+width); return; }
      char buf[1024]; meter_full_text_line(name,settings,buf,sizeof(buf),scan);
      /* Color splits: caption in cyan/bluish, values default/bold etc. Plain capture unaffected. We'll draw whole with meter text color for prefix before ':'? Original text meters: label cyan, value bold white etc. Approx draw all in meter text then values bold? Keep simple: whole line default but first token cyan */
      /* Find colon */
      char* colon=strchr(buf,':');
      if(colon){
         int clen=(int)(colon-buf+1);
         char* cap=xstrndup(buf,clen);
         draw_text_at(y,x,cap,CP_METER_TEXT,0,x+width);
         draw_text_at(y,x+clen,colon+1,CP_DEFAULT,useColorsGlobal?0:A_BOLD,x+width);
         free(cap);
      } else draw_text_at(y,x,buf,CP_METER_TEXT,0,x+width);
      return;
   }
   /* Bar mode specific */
   if(strcmp(name,"Memory")==0){
      unsigned long long total=sysinfo.memTotal;
      unsigned long long cache=sysinfo.cached + (settings->show_cached_memory?sysinfo.sReclaimable:0); if(cache>=sysinfo.shared)cache-=sysinfo.shared; else cache=0;
      unsigned long long used=0; if(total>sysinfo.memFree+sysinfo.buffers+cache) used=total-sysinfo.memFree-sysinfo.buffers-cache;
      unsigned long long usedExcl=used>=sysinfo.shared?used-sysinfo.shared:0;
      BarSeg segs[5]={{(double)usedExcl,CP_MEM_USED,'|'},{(double)sysinfo.shared,CP_MEM_SHARED,'|'},{0,CP_MEM_COMPRESSED,'|'},{(double)sysinfo.buffers,CP_MEM_BUFFERS,'#'},{(double)cache,CP_MEM_CACHE,'$'}};
      char u[32],t[32],ov[64]; format_size_bytes_text(u,sizeof(u),used*1024ULL); format_size_bytes_text(t,sizeof(t),total*1024ULL); snprintf(ov,sizeof(ov),"%s/%s",u,t);
      draw_bar_generic(y,x,width,"Mem",segs,5,(double)total,ov); return;
   }
   if(strcmp(name,"Swap")==0){
      unsigned long long total=sysinfo.swapTotal; unsigned long long used=total>=sysinfo.swapFree?total-sysinfo.swapFree:0;
      BarSeg segs[3]={{(double)(used>=sysinfo.swapCache?used-sysinfo.swapCache:used),CP_SWAP_USED,'|'},{(double)sysinfo.swapCache,CP_SWAP_CACHE,'|'},{0,CP_MEM_COMPRESSED,'|'}};
      char u[32],t[32],ov[64]; format_size_bytes_text(u,sizeof(u),used*1024ULL); format_size_bytes_text(t,sizeof(t),total*1024ULL); snprintf(ov,sizeof(ov),"%s/%s",u,t);
      draw_bar_generic(y,x,width,"Swp",segs,2,total?(double)total:1,ov); return;
   }
   if(strcmp(name,"MemorySwap")==0){
      int w1=width/2; int w2=width-w1;
      /* At widths, first bar maybe gets (?) At W140 col width67, Mem subbar length: "Mem[...17.0G/185G]" up to about31? and Swp begins at x+?? It was separated by space. Split roughly equal */
      draw_meter(y,x,w1,"Memory",1,settings,scan);
      draw_meter(y,x+w1,w2,"Swap",1,settings,scan);
      return;
   }
   if(strcmp(name,"LoadAverage")==0){
      BarSeg segs[1]={{sysinfo.load1,CP_CPU_NORMAL,'|'}};
      char ov[64]; snprintf(ov,sizeof(ov),"%.2f/%.2f/%.2f",sysinfo.load1,sysinfo.load5,sysinfo.load15);
      draw_bar_generic(y,x,width,"Loa",segs,1,(double)sysinfo.cpuCount,ov); return;
   }
   if(strcmp(name,"Load")==0){
      BarSeg segs[1]={{sysinfo.load1,CP_CPU_NORMAL,'|'}}; char ov[32]; snprintf(ov,sizeof(ov),"%.2f",sysinfo.load1);
      draw_bar_generic(y,x,width,"Loa",segs,1,(double)sysinfo.cpuCount,ov); return;
   }
   if(strcmp(name,"Tasks")==0){
      /* Bar segments by states: approximate total tasks filled with sleeping (?) plus running */
      int total=sysinfo.totalTasks; int run=sysinfo.procsRunning;
      BarSeg segs[2]={{(double)(total-run>0?total-run:0),CP_CPU_NORMAL,'|'},{(double)run,CP_CPU_KERNEL,'|'}};
      char ov[64]; snprintf(ov,sizeof(ov),"%d/%d",run,total);
      draw_bar_generic(y,x,width,"Tas",segs,2,total?total:1,ov); return;
   }
   if(strcmp(name,"HugePages")==0){
      unsigned long long total=sysinfo.hugePagesTotal*sysinfo.hugePageSizeKib; unsigned long long used=(sysinfo.hugePagesTotal-sysinfo.hugePagesFree)*sysinfo.hugePageSizeKib;
      BarSeg segs[1]={{(double)used,CP_MEM_USED,'|'}}; char u[32],t[32],ov[64]; format_size_bytes_text(u,sizeof(u),used*1024ULL); format_size_bytes_text(t,sizeof(t),total*1024ULL); snprintf(ov,sizeof(ov),"%s/%s",u,t);
      draw_bar_generic(y,x,width,"HP ",segs,1,total? (double)total:1,ov); return;
   }
   if(strcmp(name,"Battery")==0){ BarSeg segs[1]={{0,CP_MEM_USED,'|'}}; draw_bar_generic(y,x,width,"Bat",segs,1,100,"N/A"); return; }
   if(starts_with(name,"PressureStall")){
      char full[256]; meter_full_text_line(name,settings,full,sizeof(full),scan);
      /* overlay text is after label "PSI some cpu: ..." in bar mode original overlay "some cpu  0.00% ..." (lowercase) */
      const char* kindstr="";
      if(strstr(name,"CPUSome"))kindstr="some cpu";
      else if(strstr(name,"IOSome"))kindstr="some io";
      else if(strstr(name,"IOFull"))kindstr="full io";
      else if(strstr(name,"IRQFull"))kindstr="full irq";
      else if(strstr(name,"MemorySome"))kindstr="some memory";
      else if(strstr(name,"MemoryFull"))kindstr="full memory";
      /* values from full (after colon) */
      char* colon=strchr(full,':'); const char* vals=colon?colon+1:"";
      while(*vals==' ')vals++;
      char ov[256]; snprintf(ov,sizeof(ov),"%s  %s",kindstr,vals);
      BarSeg segs[1]={{0,CP_CPU_NORMAL,'|'}};
      draw_bar_generic(y,x,width,"PSI",segs,1,100,ov); return;
   }
   if(strcmp(name,"ZFSARC")==0){ draw_bar_generic(y,x,width,"ARC",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"0K/0K"); return; }
   if(strcmp(name,"ZFSCARC")==0){ draw_bar_generic(y,x,width,"ARC",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"N/A"); return; }
   if(strcmp(name,"Zram")==0){ draw_bar_generic(y,x,width,"zrm",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"0K(0K)/0K"); return; }
   if(strcmp(name,"DiskIORate")==0 || strcmp(name,"DiskIO")==0 || strcmp(name,"DiskIOTime")==0){
      if(strcmp(name,"DiskIO")==0){
         int w1=width/2; draw_meter(y,x,w1,"DiskIORate",1,settings,scan); draw_meter(y,x+w1,width-w1,"DiskIOTime",1,settings,scan); return;
      }
      if(sysinfo.lastDiskSampleTime==0){ draw_bar_generic(y,x,width,"Dsk",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"init"); return; }
      if(strcmp(name,"DiskIOTime")==0){
         char ov[64]; snprintf(ov,sizeof(ov),"%.1f%% (2disks)",sysinfo.diskBusyPercent);
         draw_bar_generic(y,x,width,"Dsk",(BarSeg[]){{sysinfo.diskBusyPercent,CP_CPU_NORMAL,'|'}},1,100,ov); return;
      }
      /* Disk rate bar total unknown dynamic max? Original fills a huge bar at 82KiB/s with many pipes because total maybe max seen? We'll set total as max(r+w, something) */
      double tot=sysinfo.diskReadRate+sysinfo.diskWriteRate; double mx=tot>0?tot:1;
      char ov[128]; snprintf(ov,sizeof(ov),"r:%.0fKiB/s|w:%.0fKiB/s",sysinfo.diskReadRate/1024.0,sysinfo.diskWriteRate/1024.0);
      BarSeg segs[2]={{sysinfo.diskReadRate,CP_CPU_NORMAL,'|'},{sysinfo.diskWriteRate,CP_CPU_KERNEL,'|'}};
      draw_bar_generic(y,x,width,"Dsk",segs,2,mx,ov); return;
   }
   if(strcmp(name,"NetworkIO")==0){
      if(sysinfo.lastNetSampleTime==0){ draw_bar_generic(y,x,width,"Net",(BarSeg[]){{0,CP_MEM_USED,'|'}},1,1,"init"); return; }
      char ov[128]; snprintf(ov,sizeof(ov),"rx:%.0fKiB/s tx:%.0fKiB/s (%.0f/%.0fpps)",sysinfo.netRecvRate/1024.0,sysinfo.netSendRate/1024.0,sysinfo.netRecvPktRate,sysinfo.netSendPktRate);
      double tot=sysinfo.netRecvRate+sysinfo.netSendRate; draw_bar_generic(y,x,width,"Net",(BarSeg[]){{tot,CP_CPU_NORMAL,'|'}},1,tot>0?tot:1,ov); return;
   }
   if(strcmp(name,"FileDescriptors")==0){
      char ov[64]; snprintf(ov,sizeof(ov),"%llu/unlimited",sysinfo.fileNrAlloc);
      draw_bar_generic(y,x,width,"FDs",(BarSeg[]){{(double)sysinfo.fileNrAlloc,CP_CPU_NORMAL,'|'}},1, (double)(sysinfo.fileNrAlloc>0?sysinfo.fileNrAlloc*20:1),ov); return;
   }
   if(strcmp(name,"GPU")==0){ draw_bar_generic(y,x,width,"GPU",(BarSeg[]){{0,CP_CPU_NORMAL,'|'}},1,100,"0.0%"); return; }
   /* fallback text */
   { char buf[512]; meter_full_text_line(name,settings,buf,sizeof(buf),scan); draw_text_at(y,x,buf,CP_METER_TEXT,0,x+width); }
}

static int compute_header_height(Settings* settings,int hideMeters){
   if(hideMeters) return 0;
   int layoutIdx=header_layout_index(settings->header_layout);
   int ncols=header_layout_num_cols(layoutIdx);
   int maxh=0;
   for(int c=0;c<ncols;c++){
      int h=0;
