{"command":"cat >> src/htop.c <<'EOF'

/* Runtime state */
typedef struct {
   Settings* settings;
   CLIFlags* flags;
   ScanResult scan;
   int selected; /* index in display */
   int scrollTop; /* first display index shown */
   int hscroll; /* columns chars horizontal offset in process row string */
   int follow; /* follow selected pid */
   int followPid;
   int paused;
   int hideMetersRuntime;
   int iteration;
   char* incFilter; /* active filter from F4/CLI combined? CLI filter is in flags; incFilter is separate panel filter applied - they interact: original -F sets inc filter initially and F4 can edit/clear it */
   char* incSearch; /* last search string (?) */
   int quit;
   int cleanExit; /* save settings if changed */
   /* tree allCollapsed applied tracking */
   int collapsedAppliedForScreen[MAX_SCREENS];
} AppState;

static volatile sig_atomic_t gotTermSignal=0;
static void sig_handler(int sig){ (void)sig; gotTermSignal=1; }

static Proc* selected_proc(AppState* app){
   if(app->scan.display.count==0) return NULL;
   if(app->selected<0) app->selected=0;
   if(app->selected>=app->scan.display.count) app->selected=app->scan.display.count-1;
   return app->scan.display.items[app->selected];
}
static ScreenCfg* current_screen(AppState* app){ return &app->settings->screens[app->settings->active_screen]; }

static void build_row_string(Proc* pr, ScreenCfg* screen, Settings* settings, int termW, int hscroll, char* out, size_t outsz){
   /* Build full row string (without terminal truncation except Command limited later) then apply hscroll when drawing copies substring */
   out[0]=0;
   size_t off=0;
   for(int i=0;i<screen->fields.count;i++){
      int colId=screen->fields.items[i];
      const ColDef* def=col_by_id(colId);
      if(!def) continue;
      char val[1024]; format_col_value(pr,colId,val,sizeof(val));
      char segment[2048];
      if(colId==COL_Command){
         const char* cmd=val;
         if(screen->tree_view && pr->tree_prefix){
            snprintf(segment,sizeof(segment),"%s%s",pr->tree_prefix,cmd);
         } else snprintf(segment,sizeof(segment),"%s",cmd);
         /* Add segment */
         size_t l=strlen(segment);
         if(off+l>=outsz) l=outsz-off-1;
         memcpy(out+off,segment,l); off+=l; out[off]=0;
      } else {
         if(def->leftAlign){
            /* truncate to width */
            char tmp[1024]; strncpy(tmp,val,sizeof(tmp)-1); tmp[sizeof(tmp)-1]=0;
            if((int)strlen(tmp)>def->width) tmp[def->width]=0;
            snprintf(segment,sizeof(segment),"%-*s",def->width,tmp);
         } else {
            snprintf(segment,sizeof(segment),"%*s",def->width,val);
         }
         size_t l=strlen(segment);
         if(off+l>=outsz) l=outsz-off-1;
         memcpy(out+off,segment,l); off+=l; out[off]=0;
         if(i<screen->fields.count-1){ if(off+1<outsz){ out[off++]=' '; out[off]=0; } }
      }
   }
   (void)termW; (void)hscroll; (void)settings;
}
static void build_header_string(ScreenCfg* screen, char* out,size_t outsz){
   out[0]=0; size_t off=0;
   int sortKey = screen->tree_view ? (screen->tree_view_always_by_pid? COL_PID: screen->tree_sort_key) : screen->sort_key;
   int sortDir = screen->tree_view ? (screen->tree_view_always_by_pid?1:screen->tree_sort_direction) : screen->sort_direction;
   char marker = sortDir>=0? '+':'-';
   for(int i=0;i<screen->fields.count;i++){
      int colId=screen->fields.items[i];
      const ColDef* def=col_by_id(colId); if(!def)continue;
      char seg[256];
      if(colId==COL_Command){
         snprintf(seg,sizeof(seg),"%s",def->titleSeg);
         if(colId==sortKey) strncat(seg,&marker,1);
      } else {
         snprintf(seg,sizeof(seg),"%s",def->titleSeg);
         if(colId==sortKey){
            size_t l=strlen(seg);
            if(i==screen->fields.count-1){
               /* last non-Command: append/replace final space */
               if(l>0 && seg[l-1]==' ') seg[l-1]=marker; else strncat(seg,&marker,1);
            } else {
               if(l>0 && seg[l-1]==' ') seg[l-1]=marker;
               /* if no trailing space (AGRP/ANI) leave as original (no marker) */
            }
         }
      }
      size_t l=strlen(seg);
      if(off+l>=outsz) l=outsz-off-1;
      memcpy(out+off,seg,l); off+=l; out[off]=0;
   }
}

static int list_start_y(AppState* app){
   int hh=compute_header_height(app->settings, app->hideMetersRuntime);
   int y=hh;
   if(app->settings->screen_tabs) y+=1;
   return y; /* column header line */
}
static int list_rows_available(AppState* app){
   int h=getmaxy(stdscr);
   int y=list_start_y(app);
   int bottom = h - (app->settings->hide_function_bar?0:1);
   int rows=bottom - (y+1);
   if(rows<0)rows=0;
   return rows;
}
static void ensure_selected_visible(AppState* app){
   int rows=list_rows_available(app);
   if(rows<=0)return;
   if(app->selected < app->scrollTop) app->scrollTop=app->selected;
   if(app->selected >= app->scrollTop+rows) app->scrollTop=app->selected-rows+1;
   if(app->scrollTop<0)app->scrollTop=0;
   int maxTop=app->scan.display.count-rows;
   if(maxTop<0)maxTop=0;
   if(app->scrollTop>maxTop) app->scrollTop=maxTop;
}
static void draw_tabs(AppState* app, int y, const char* setupMode){
   if(!app->settings->screen_tabs && !setupMode) return;
   int x=2; int w=getmaxx(stdscr);
   move(y,0); clrtoeol();
   if(setupMode){
      char buf[128]; snprintf(buf,sizeof(buf),"[%s]",setupMode);
      /* Setup tab selected style green */
      set_attr(CP_SCREEN_TAB_ACTIVE,0); mvaddnstr(y,x,buf,w-x); unset_attr(CP_SCREEN_TAB_ACTIVE,0);
      return;
   }
   for(int i=0;i<app->settings->num_screens;i++){
      char buf[128]; snprintf(buf,sizeof(buf),"[%s]",app->settings->screens[i].name);
      int pair=(i==app->settings->active_screen)?CP_SCREEN_TAB_ACTIVE:CP_SCREEN_TAB;
      set_attr(pair,0); mvaddnstr(y,x,buf,w-x); unset_attr(pair,0);
      x+=strlen(buf)+1;
      if(x>=w)break;
   }
}
static void draw_process_list(AppState* app, int startX){
   /* startX used when side panel overlays left */
   Settings* settings=app->settings; ScreenCfg* screen=current_screen(app);
   int termW=getmaxx(stdscr); int termH=getmaxy(stdscr);
   int headerY=list_start_y(app);
   int tabY=headerY- (settings->screen_tabs?1:0);
   if(settings->screen_tabs) draw_tabs(app,tabY,NULL);
   /* header line */
   char hdr[4096]; build_header_string(screen,hdr,sizeof(hdr));
   /* apply hscroll to header similarly? Original horizontal scrolling shifts whole list including header */
   const char* hdrp=hdr;
   if(app->hscroll>0){ if((int)strlen(hdrp)>app->hscroll) hdrp+=app->hscroll; else hdrp=""; }
   int availW=termW-startX;
   set_attr(CP_PANEL_HEADER,0);
   move(headerY,startX);
   /* fill line with header attr spaces */
   for(int i=startX;i<termW;i++) addch(' ');
   mvaddnstr(headerY,startX,hdrp,availW);
   unset_attr(CP_PANEL_HEADER,0);
   int rows=list_rows_available(app);
   ensure_selected_visible(app);
   for(int r=0;r<rows;r++){
      int idx=app->scrollTop+r;
      int y=headerY+1+r;
      if(y>=termH)break;
      move(y,startX); clrtoeol();
      if(idx>=app->scan.display.count) continue;
      Proc* pr=app->scan.display.items[idx];
      char row[8192]; build_row_string(pr,screen,settings,termW,0,row,sizeof(row));
      const char* rp=row;
      if(app->hscroll>0){ if((int)strlen(rp)>app->hscroll) rp+=app->hscroll; else rp=""; }
      int isSel=(idx==app->selected);
      if(isSel){
         set_attr(CP_PANEL_SELECT,0);
         move(y,startX); for(int i=startX;i<termW;i++)addch(' ');
         mvaddnstr(y,startX,rp,availW);
         unset_attr(CP_PANEL_SELECT,0);
      } else {
         /* Colors: tagged yellow-ish, threads maybe diff color, shadow etc approximate */
         int pair=CP_DEFAULT; int extra=0;
         if(pr->tagged){ pair=CP_TAGGED; extra=A_BOLD; }
         else if(settings->highlight_threads && pr->isThread){ pair=CP_CPU_NICE; }
         else if(settings->shadow_other_users && pr->uid!=getuid()){ pair=CP_DEFAULT; extra=A_BOLD; }
         if(settings->highlight_changes && pr->isNewProc){ extra|=A_BOLD; }
         set_attr(pair,extra);
         mvaddnstr(y,startX,rp,availW);
         unset_attr(pair,extra);
         /* State R green overlay and basename etc are omitted in plain	ext */
      }
   }
}
static void draw_main_screen(AppState* app){
   erase();
   draw_header(app->settings,&app->scan,app->hideMetersRuntime);
   draw_process_list(app,0);
   if(!app->settings->hide_function_bar){
      FuncItem* items = current_screen(app)->tree_view? mainFuncTree: mainFunc;
      /* FILTER label uppercase if filter active */
      FuncItem copy[10]; memcpy(copy,items,sizeof(copy));
      int filterActive = (app->incFilter && *app->incFilter) || (app->flags && app->flags->filter);
      if(filterActive) copy[3].label="FILTER";
      if(app->paused){
         /* Paaused indicator? Function bar maybe changes? Original might show header/process with a 'PAUSED' in function bar? Keep copy */
      }
      if(app->follow) copy[5].label="SortBy"; /* no change */
      draw_function_bar(copy,10,NULL);
   }
   /* cursor at selected row? htop hides cursor */
   move(getmaxy(stdscr)-1,0);
   refresh();
}

EOF
"}

