{"command":"cat >> src/htop.c <<'EOF'

/* Generic side panel */
typedef struct {
   const char* title;
   StrVec items;
   int selected;
   int scroll;
   int width;
   const char* enterLabel; /* e.g. Sort */
} SidePanel;

static void side_panel_draw(AppState* app, SidePanel* panel){
   /* Draw main background (header + process list offset), then panel */
   erase();
   draw_header(app->settings,&app->scan,app->hideMetersRuntime);
   draw_process_list(app,panel->width);
   int headerY=list_start_y(app);
   int termW=getmaxx(stdscr); int termH=getmaxy(stdscr);
   (void)termW;
   /* title */
   set_attr(CP_PANEL_HEADER,0);
   move(headerY,0); for(int i=0;i<panel->width;i++)addch(' ');
   mvaddnstr(headerY,0,panel->title,panel->width);
   unset_attr(CP_PANEL_HEADER,0);
   int rows=list_rows_available(app);
   if(panel->selected<panel->scroll)panel->scroll=panel->selected;
   if(panel->selected>=panel->scroll+rows)panel->scroll=panel->selected-rows+1;
   if(panel->scroll<0)panel->scroll=0;
   for(int r=0;r<rows;r++){
      int idx=panel->scroll+r; int y=headerY+1+r; if(y>=termH)break;
      move(y,0); for(int i=0;i<panel->width;i++)addch(' ');
      if(idx>=panel->items.count) continue;
      if(idx==panel->selected){
         set_attr(CP_PANEL_SELECT,0);
         move(y,0); for(int i=0;i<panel->width;i++)addch(' ');
         mvaddnstr(y,0,panel->items.items[idx],panel->width);
         unset_attr(CP_PANEL_SELECT,0);
      } else {
         mvaddnstr(y,0,panel->items.items[idx],panel->width);
      }
   }
   if(!app->settings->hide_function_bar){
      FuncItem items[]={ {"Enter",panel->enterLabel,7}, {"Esc","Cancel",0} };
      draw_function_bar(items,2,NULL);
   }
   refresh();
}
/* returns index selected or -1 cancel, -2 quit app signal */
static int side_panel_run(AppState* app, SidePanel* panel){
   while(1){
      if(gotTermSignal){ app->quit=1; app->cleanExit=0; return -2; }
      side_panel_draw(app,panel);
      int timeoutMs = app->settings->delay*100;
      timeout(timeoutMs);
      int ch=getch();
      if(ch==ERR){
         if(gotTermSignal) continue;
         if(app->paused) continue;
         /* timeout refresh scan */
         /* preserve selected pid maybe */
         Proc* sel=selected_proc(app); int selPid=sel?sel->pid:-1;
         free_scan(&app->scan);
         app->scan.all=scan_processes(app->settings,current_screen(app),0);
         build_display_list(&app->scan,app->settings,current_screen(app),app->flags,app->incFilter);
         /* follow selected pid if possible */
         if(selPid>0){ for(int i=0;i<app->scan.display.count;i++) if(app->scan.display.items[i]->pid==selPid){ app->selected=i; break; } }
         continue;
      }
      if(ch==27){ /* Esc - ncurses may need time to differentiate Alt; plain Esc in tmux returns 27 quickly */
         return -1;
      }
      if(ch=='q'){
         /* In side panels q likely cancels panel? Check: Panel handler in htop: if ch == 'q' maybe ... We'll treat as cancel */
         return -1;
      }
      if(ch==KEY_ENTER || ch=='\n' || ch=='\r' || ch==KEY_F(10)){
         /* F10 in some panels maybe cancel? But enter label - treat F10 as cancel unless Sort? Hmm function bar only Enter/Esc */
         if(ch==KEY_F(10)) return -1;
         return panel->selected;
      }
      int rows=list_rows_available(app); if(rows<1)rows=1;
      switch(ch){
         case KEY_UP: if(panel->selected>0)panel->selected--; break;
         case KEY_DOWN: if(panel->selected<panel->items.count-1)panel->selected++; break;
         case KEY_PPAGE: panel->selected-=rows; if(panel->selected<0)panel->selected=0; break;
         case KEY_NPAGE: panel->selected+=rows; if(panel->selected>=panel->items.count)panel->selected=panel->items.count-1; break;
         case KEY_HOME: panel->selected=0; break;
         case KEY_END: panel->selected=panel->items.count-1; break;
         case KEY_MOUSE: {
            MEVENT ev; if(getmouse(&ev)==OK){
               int headerY=list_start_y(app);
               if(ev.x<panel->width && ev.y>headerY){
                  int idx=panel->scroll+(ev.y-headerY-1);
                  if(idx>=0 && idx<panel->items.count){ 
                     if(ev.bstate & BUTTON1_DOUBLE_CLICKED) { panel->selected=idx; return idx; }
                     panel->selected=idx;
                  }
               }
            }
            break;
         }
         default: break;
      }
   }
}

