} Viewer;
static void viewer_run(AppState* app, const char* title, StrVec* lines, int allowRefreshProcPid, int viewerKind);
static void strvec_wrap_text(StrVec* out, const char* text, int width){
   /* wrap words at width, preserve blank lines */
   if(width<10)width=10;
   const char* p=text;
   while(*p){
      const char* eol=strchr(p,'\n');
      size_t len=eol?(size_t)(eol-p):strlen(p);
      if(len==0){ sv_push_dup(out,""); }
      else {
         size_t off=0;
         while(off<len){
            size_t take=len-off;
            if((int)take>width){
               /* break at last space within width if there is one after 10 chars */
               int br=-1;
               for(int i=width-1;i>10;i--){ if(p[off+i]==' '){br=i;break;} }
               if(br>0) take=br; else take=width;
            }
            char* l=xstrndup(p+off,take); sv_push(out,l);
            off+=take;
            while(off<len && p[off]==' ') off++;
         }
      }
      if(!eol)break;
      p=eol+1;
   }
}
