static void viewer_run(AppState* app, const char* title, StrVec* linesArg, int procPid, int viewerKind){
   /* viewerKind 0 normal (F5 refresh label), 1 trace */
   StrVec lines=*linesArg;
   StrVec displayIdx={0}; /* not used string vec */
   IntVec visible={0};
   char* filter=xstrdup("");
   char* search=xstrdup("");
   int mode=0; /*0 normal,1 search input,2 filter input*/
   int top=0, left=0, selLine=0; /* selLine for search highlight? Viewer is a list where selected line is highlighted? Original OpenFiles screen uses Panel as ListItem lines - there is a selection bar? Plain captures can't see. In env viewer, first content line after blank may be selected with a bar in escape capture. We model as scrollable text without a specific selection except search moves scroll to match. */
   (void)procPid;
   while(1){
      if(gotTermSignal){ app->quit=1; app->cleanExit=0; break; }
      /* build visible indices */
      iv_free(&visible); memset(&visible,0,sizeof(visible));
      for(int i=0;i<lines.count;i++){
         if(filter && *filter && !filter_match(lines.items[i],filter)) continue;
         iv_push(&visible,i);
      }
      int termW=getmaxx(stdscr), termH=getmaxy(stdscr);
      int rows=termH-1; /* excluding function bar, title is first line in lines? Title drawn separately as line0. linesArg should NOT include title; caller gives title param plus body lines. But our title handling below expects body only. */
      erase();
      draw_text_at(0,0,title,CP_DEFAULT,A_BOLD,termW);
      /* body starts at line1, caller includes blank line or header as appropriate */
      int bodyRows=rows-1;
      if(top<0)top=0;
      if(top>visible.count)top=visible.count;
      for(int r=0;r<bodyRows;r++){
         int idx=top+r; if(idx>=visible.count)break;
         const char* s=lines.items[visible.items[idx]];
         if(left>0){ if((int)strlen(s)>left) s+=left; else s=""; }
         int pair=CP_DEFAULT; int extra=0;
         if(idx==selLine && (search && *search)) { /* highlight matched line maybe */ extra=A_BOLD; }
         draw_text_at(1+r,0,s,pair,extra,termW);
      }
      if(mode==1){
         char prompt[1024]; snprintf(prompt,sizeof(prompt),"Search: %s",search);
         FuncItem items[]={{"F3","Next",6},{"S-F3","Prev",7},{"Esc","Cancel",10}};
         draw_function_bar(items,3,prompt);
         /* prompt position in draw_function_bar extraText starts right after items: EscCancel + 4 spaces from pad10 gives "Search:" at expected approx */
      } else if(mode==2){
         char prompt[1024]; snprintf(prompt,sizeof(prompt),"Filter: %s",filter);
         FuncItem items[]={{"Enter","Done",6},{"Esc","Clear",9}};
         draw_function_bar(items,2,prompt);
      } else {
         if(viewerKind==1){
            /* "F3Search F4Filter F8AutoScroll F9Stop Tracing   EscDone" */
            FuncItem items[]={{"F3","Search",7},{"F4","Filter",7},{"F8","AutoScroll ",11},{"F9","Stop Tracing",11},{"Esc","Done",0}};
            draw_function_bar(items,5,NULL);
         } else {
            FuncItem items[]={{"F3","Search",7},{"F4","Filter",7},{"F5","Refresh",7},{"Esc","Done",0}};
            draw_function_bar(items,4,NULL);
         }
      }
      refresh();
      timeout(app->settings->delay*100);
      int ch=getch();
      if(ch==ERR) continue;
      if(mode==1 || mode==2){
         char** target=(mode==1?&search:&filter);
         if(ch==27){ 
            if(mode==2){ free(filter); filter=xstrdup(""); top=0; }
            mode=0; continue;
         }
         if(ch=='\n' || ch=='\r' || ch==KEY_ENTER){ mode=0; continue; }
         if(ch==KEY_F(3) && mode==1){
            /* next match */
            if(*search){
               for(int k=1;k<=visible.count;k++){
                  int ii=visible.items[(selLine+k)%visible.count];
                  if(contains_ci(lines.items[ii],search)){ selLine=(selLine+k)%visible.count; if(selLine<top||selLine>=top+bodyRows)top=selLine; break; }
               }
            }
            continue;
         }
         if(ch==KEY_BACKSPACE || ch==127 || ch==8){
            size_t l=strlen(*target); if(l)(*target)[l-1]=0;
         } else if(ch>=32 && ch<127){
            size_t l=strlen(*target); *target=xrealloc(*target,l+2); (*target)[l]=(char)ch; (*target)[l+1]=0;
         }
         if(mode==1 && *search){
            /* incremental: find first match from current sel */
            for(int k=0;k<visible.count;k++){
               int ii=visible.items[k];
               if(contains_ci(lines.items[ii],search)){ selLine=k; if(selLine<top||selLine>=top+bodyRows)top=selLine; break; }
            }
         } else if(mode==2){ top=0; selLine=0; }
         continue;
      }
      /* normal mode */
      if(ch==27 || ch=='q' || ch==KEY_F(10)) break;
      if(ch==KEY_F(3) || ch=='/'){ mode=1; continue; }
      if(ch==KEY_F(4) || ch=='\\'){ mode=2; continue; }
      if(ch==KEY_F(5)){
         /* Refresh handled by caller? Our static lines can't refresh. Breaking with a special? For now do nothing (caller could regenerate before call, viewer stays) */
         continue;
      }
      switch(ch){
         case KEY_DOWN: if(top+bodyRows<visible.count) top++; if(selLine<visible.count-1)selLine++; break;
         case KEY_UP: if(top>0)top--; if(selLine>0)selLine--; break;
         case KEY_NPAGE: top+=bodyRows; if(top>visible.count)top=visible.count; break;
         case KEY_PPAGE: top-=bodyRows; if(top<0)top=0; break;
         case KEY_HOME: top=0; selLine=0; break;
         case KEY_END: top=visible.count-bodyRows; if(top<0)top=0; selLine=visible.count-1; break;
         case KEY_LEFT: if(left>0)left--; break;
         case KEY_RIGHT: left++; break;
         default: break;
      }
   }
   iv_free(&visible); sv_free(&displayIdx); free(filter); free(search);
   *linesArg=lines;
}

/* Generate viewer contents */
static StrVec make_env_lines(Proc* pr){
   StrVec lines={0}; sv_push_dup(&lines,"");
   char path[128]; snprintf(path,sizeof(path),"/proc/%d/environ",pr->tgid?pr->tgid:pr->pid);
   size_t len=0; char* data=read_file_alloc(path,&len);
   if(!data || len==0){ sv_push_dup(&lines,"Could not read process environment."); free(data); return lines; }
   size_t off=0;
   while(off<len){
      char* s=data+off; size_t l=strlen(s);
      if(l) sv_push_dup(&lines,s);
      off+=l+1;
   }
   free(data);
   return lines;
}
static StrVec make_cmd_lines(Proc* pr,int width){
   StrVec lines={0}; sv_push_dup(&lines,"");
   /* wrap at terminal width */
   StrVec wrapped={0}; strvec_wrap_text(&wrapped,pr->cmdline?pr->cmdline:"",width>0?width:80);
   for(int i=0;i<wrapped.count;i++) sv_push(&lines,wrapped.items[i]);
   free(wrapped.items);
   return lines;
}
static StrVec make_locks_lines(Proc* pr){
   StrVec lines={0};
   sv_push_dup(&lines,"   FD TYPE       EXCLUSION  READ/WRITE DEVICE       NODE               START                 END  FILE");
   /* /proc/locks format: id: type excl rw pid major:minor inode start end */
   char* data=read_file_alloc("/proc/locks",NULL);
   int found=0;
   if(data){
      char* save=NULL;
      for(char* line=strtok_r(data,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
         int id=0, lpid=0; char type[32]={0},excl[32]={0},rw[32]={0}; int maj=0,minorr=0; unsigned long long inode=0,start=0; long long end=0;
         /* "1: POSIX  ADVISORY  WRITE 1234 08:01:123 0 EOF" variant: after pid device is major:minor:inode colon separated as one token */
         char devtok[128]={0};
         if(sscanf(line,"%d: %31s %31s %31s %d %127s %llu %lld",&id,type,excl,rw,&lpid,devtok,&start,&end)>=7){
            if(lpid!=pr->tgid && lpid!=pr->pid) continue;
            /* parse devtok major:minor:inode */
            char *c1=strchr(devtok,':'); char *c2=c1?strchr(c1+1,':'):NULL;
            if(c1&&c2){ maj=atoi(devtok); minorr=atoi(c1+1); inode=strtoull(c2+1,NULL,10); }
            /* Find file by scanning fds inode? simplified leave blank/unknown */
            char out[512];
            char endstr[64]; if(end==0) snprintf(endstr,sizeof(endstr),"EOF"); else snprintf(endstr,sizeof(endstr),"%lld",end);
            snprintf(out,sizeof(out),"%5d %-10s %-10s %-10s %02x:%02x %-15llu %-15llu %-15s",id,type,excl,rw,maj,minorr,inode,start,endstr);
            /* NOTE exact formatting of locks table in original is more specific; there are no locks in tests likely */
            sv_push_dup(&lines,out); found++;
         }
      }
      free(data);
   }
   if(!found) sv_push_dup(&lines,"No locks have been found for the selected process.");
   return lines;
}
static int find_executable_in_path(const char* name){
   char* path=getenv("PATH"); if(!path)return 0;
   char* dup=xstrdup(path); char* save=NULL;
   for(char* tok=strtok_r(dup,":",&save); tok; tok=strtok_r(NULL,":",&save)){
      char buf[PATH_MAX]; snprintf(buf,sizeof(buf),"%s/%s",tok[0]?tok:".",name);
      if(access(buf,X_OK)==0){ free(dup); return 1; }
   }
   free(dup); return 0;
}
static StrVec make_lsof_lines(Proc* pr){
   StrVec lines={0};
   sv_push_dup(&lines,"   FD TYPE    MODE DEVICE           SIZE     OFFSET       NODE  NAME");
   if(!find_executable_in_path("lsof")){
      sv_push_dup(&lines,"Could not execute 'lsof'. Please make sure it is available in your $PATH.");
      return lines;
   }
   char cmd[256]; snprintf(cmd,sizeof(cmd),"lsof -P -p %d 2>/dev/null",pr->tgid?pr->tgid:pr->pid);
   FILE* fp=popen(cmd,"r");
   if(!fp){ sv_push_dup(&lines,"Could not execute 'lsof'. Please make sure it is available in your $PATH."); return lines; }
   char buf[4096];
   int first=1;
   while(fgets(buf,sizeof(buf),fp)){
      trim_trailing_spaces(buf);
      if(first){ first=0; continue; } /* skip lsof header */
      /* lsof fields COMMAND PID USER FD TYPE DEVICE SIZE/OFF NODE NAME - htop parses and formats into its columns. Simplified: output raw line after fields? We'll output buf as is for now */
      sv_push_dup(&lines,buf);
   }
   pclose(fp);
   return lines;
}
static StrVec make_trace_lines(Proc* pr){
   StrVec lines={0}; sv_push_dup(&lines,"");
   (void)pr;
   if(!find_executable_in_path("strace")){
      sv_push_dup(&lines,"Could not execute 'strace'. Please make sure it is available in your $PATH.");
   } else {
      sv_push_dup(&lines,"(strace output not implemented)");
   }
   return lines;
}
