{"command":"cat >> src/htop.c <<'EOF'

#define ALT_KEY_BASE 10000
static int read_key_with_timeout(int timeoutMs){
   timeout(timeoutMs);
   int ch=getch();
   if(ch!=27) return ch;
   timeout(0);
   int c2=getch();
   if(c2==ERR) return 27;
   if(c2=='[' || c2=='O'){ ungetch(c2); return 27; }
   if(c2>=1 && c2<127) return ALT_KEY_BASE + c2;
   ungetch(c2); return 27;
}

/* Setup screen */
typedef struct {
   const char* label;
   int* valuePtr; /* boolean for checkboxes, for special handling null */
   int kind; /*0 header text,1 bool current screen,2 bool global,3 number delay,4 number highlightdelay,5 number functionbar*/
   int screenField; /* for current screen bools: 0 tree_view 1 tree_by_pid 2 all_collapsed */
} DisplayOption;
static void mark_changed(AppState* app){ app->settings->changed=1; }

static void setup_apply_header_layout_change(Settings* s,int newIdx){
   int oldIdx=header_layout_index(s->header_layout);
   int oldCols=header_layout_num_cols(oldIdx);
   int newCols=header_layout_num_cols(newIdx);
   if(newIdx==oldIdx) return;
   free(s->header_layout); s->header_layout=xstrdup(headerLayoutNames[newIdx]);
   if(newCols<oldCols){
      /* move meters from removed columns in order, each column's list reversed appended to last remaining */
      int dest=newCols-1;
      for(int c=newCols;c<oldCols;c++){
         for(int i=s->header[c].meters.count-1;i>=0;i--){
            if(strcmp(s->header[c].meters.items[i],"!")==0) continue;
            sv_push_dup(&s->header[dest].meters,s->header[c].meters.items[i]);
            int mode=i<s->header[c].modes.count?s->header[c].modes.items[i]:2;
            iv_push(&s->header[dest].modes,mode);
         }
         sv_free(&s->header[c].meters); iv_free(&s->header[c].modes);
         memset(&s->header[c],0,sizeof(HeaderCol));
         /* write empty as ! handled by writer if needed but cols beyond not written */
      }
   } else if(newCols>oldCols){
      for(int c=oldCols;c<newCols;c++){
         sv_free(&s->header[c].meters); iv_free(&s->header[c].modes); memset(&s->header[c],0,sizeof(HeaderCol));
         sv_push_dup(&s->header[c].meters,"!"); iv_push(&s->header[c].modes,0);
      }
   }
}

typedef struct {
   char* title;
   StrVec items;
   int selected;
   int scroll;
   int width;
} SetupPanel;
static void setup_panel_draw(int y0,int x,int width,const char* title, StrVec* items,int selected,int* scrollPtr,int focused,int rows){
   int termW=getmaxx(stdscr);
   int w=width;
   if(x+w>termW) w=termW-x;
   /* title */
   set_attr(CP_PANEL_HEADER,0); move(y0,x); for(int i=0;i<w;i++)addch(' '); mvaddnstr(y0,x,title,w); unset_attr(CP_PANEL_HEADER,0);
   int scroll=*scrollPtr;
   if(selected<scroll)scroll=selected;
   if(selected>=scroll+rows)scroll=selected-rows+1;
   if(scroll<0)scroll=0; *scrollPtr=scroll;
   for(int r=0;r<rows;r++){
      int idx=scroll+r; int y=y0+1+r;
      move(y,x); for(int i=0;i<w;i++)addch(' ');
      if(idx>=items->count) continue;
      if(idx==selected){
         int pair=focused?CP_PANEL_SELECT:CP_PANEL_SELECT_UNFOCUS;
         set_attr(pair,0); move(y,x); for(int i=0;i<w;i++)addch(' '); mvaddnstr(y,x,items->items[idx],w); unset_attr(pair,0);
      } else mvaddnstr(y,x,items->items[idx],w);
   }
}
EOF
