      refresh();
      int ch=read_key_with_timeout(s->delay*100);
      if(ch==ERR){
         /* refresh scan on timeout (header meters update) */
         free_scan(&app->scan);
         app->scan.all=scan_processes(s,current_screen(app),0);
         build_display_list(&app->scan,s,current_screen(app),app->flags,app->incFilter);
         continue;
      }
      if(editMode){
         if(ch=='\n' || ch=='\r' || ch==KEY_ENTER){
            if(editBuf[0]){
               if(editMode==1 && selScreenTab>=0 && selScreenTab<s->num_screens){ free(s->screens[selScreenTab].name); s->screens[selScreenTab].name=xstrdup(editBuf); mark_changed(app); }
               else if(editMode==2){
                  ScreenCfg* ns=settings_add_screen(s,editBuf);
                  /* new screen defaults fields Main-like? Original New screens default fields maybe PID USER Command? Check later. For now duplicate current selected screen fields or default PID Command */
                  iv_push(&ns->fields,0); iv_push(&ns->fields,48); iv_push(&ns->fields,1);
                  selScreenTab=s->num_screens-1; mark_changed(app);
               }
            }
            editMode=0; continue;
         } else if(ch==27){ editMode=0; continue; }
         else if(ch==KEY_BACKSPACE || ch==127 || ch==8){ size_t l=strlen(editBuf); if(l)editBuf[l-1]=0; continue; }
         else if(ch>=32 && ch<127){ size_t l=strlen(editBuf); if(l<sizeof(editBuf)-1){editBuf[l]=ch; editBuf[l+1]=0;} continue; }
         continue;
      }
      if(ch==KEY_F(10) || ch==27){
         /* Esc in Available meters returns to previous panel rather than exit setup */
         if(ch==27 && category==2 && focus==1+header_layout_num_cols(header_layout_index(s->header_layout))){ focus--; continue; }
         return;
      }
      if(ch=='q'){
         /* In setup q exits setup? Tests later. Might be typing in panels to search. Use return to main (common) */
         return;
      }
      /* Focus navigation */
      int maxFocus=1;
      if(category==2) maxFocus=1+header_layout_num_cols(header_layout_index(s->header_layout));
      else if(category==3) maxFocus=3;
      else maxFocus=1;
      if(meterMoveMode){
         /* Move mode key handling for meters */
         int c=meterMoveCol;
         if(ch==' ' || ch==KEY_F(0)){ /* style */ }
         if(ch==' '){
            int idx=meterColSel[c];
            if(idx>=0 && idx<s->header[c].modes.count){ int m=s->header[c].modes.items[idx]; m=m%4+1; s->header[c].modes.items[idx]=m; mark_changed(app); }
            continue;
         }
         if(ch=='\n' || ch=='\r' || ch==KEY_ENTER){ meterMoveMode=0; continue; }
         if(ch==KEY_UP){
            int idx=meterColSel[c]; if(idx>0){ /* swap with previous */ char* tmp=s->header[c].meters.items[idx-1]; s->header[c].meters.items[idx-1]=s->header[c].meters.items[idx]; s->header[c].meters.items[idx]=tmp; int tm=s->header[c].modes.items[idx-1]; s->header[c].modes.items[idx-1]=s->header[c].modes.items[idx]; s->header[c].modes.items[idx]=tm; meterColSel[c]--; mark_changed(app);} continue;
         }
         if(ch==KEY_DOWN){
            int idx=meterColSel[c]; if(idx>=0 && idx<s->header[c].meters.count-1){ char* tmp=s->header[c].meters.items[idx+1]; s->header[c].meters.items[idx+1]=s->header[c].meters.items[idx]; s->header[c].meters.items[idx]=tmp; int tm=s->header[c].modes.items[idx+1]; s->header[c].modes.items[idx+1]=s->header[c].modes.items[idx]; s->header[c].modes.items[idx]=tm; meterColSel[c]++; mark_changed(app);} continue;
         }
         if(ch==KEY_LEFT || ch==KEY_RIGHT){
            int dir=(ch==KEY_RIGHT)?1:-1;
            int nc=c+dir; int ncols=header_layout_num_cols(header_layout_index(s->header_layout));
            if(nc>=0 && nc<ncols){
               int idx=meterColSel[c];
               if(idx>=0 && idx<s->header[c].meters.count){
                  char* name=s->header[c].meters.items[idx]; int mode=s->header[c].modes.items[idx];
                  /* move to other column at same position if possible or end */
                  /* remove from old (manual shift without free for name string ownership transfer) */
                  for(int i=idx;i<s->header[c].meters.count-1;i++){ s->header[c].meters.items[i]=s->header[c].meters.items[i+1]; s->header[c].modes.items[i]=s->header[c].modes.items[i+1]; }
                  s->header[c].meters.count--; s->header[c].modes.count--;
                  int insertPos=meterColSel[nc];
                  /* If target column is empty/! clear placeholder */
                  if(s->header[nc].meters.count==1 && strcmp(s->header[nc].meters.items[0],"!")==0){ sv_free(&s->header[nc].meters); iv_free(&s->header[nc].modes); memset(&s->header[nc],0,sizeof(HeaderCol)); insertPos=0; }
                  if(insertPos<0)insertPos=0; if(insertPos>s->header[nc].meters.count)insertPos=s->header[nc].meters.count;
                  sv_insert(&s->header[nc].meters,insertPos,name);
                  iv_insert(&s->header[nc].modes,insertPos,mode);
                  meterMoveCol=nc; meterColSel[nc]=insertPos; focus=1+nc; mark_changed(app);
               }
            }
            continue;
         }
         if(ch==KEY_DC){
            int idx=meterColSel[c]; if(idx>=0 && idx<s->header[c].meters.count){ sv_remove(&s->header[c].meters,idx); iv_remove(&s->header[c].modes,idx); if(meterColSel[c]>=s->header[c].meters.count)meterColSel[c]=s->header[c].meters.count-1; if(meterColSel[c]<0)meterColSel[c]=0; mark_changed(app); }
            continue;
         }
         continue;
      }
      if(ch==KEY_RIGHT){ if(focus<maxFocus) focus++; continue; }
      if(ch==KEY_LEFT){ if(focus>0) focus--; continue; }
      if(focus==0){
         switch(ch){
            case KEY_UP: if(catSelected>0)catSelected--; break;
            case KEY_DOWN: if(catSelected<4)catSelected++; break;
            case KEY_HOME: catSelected=0; break;
            case KEY_END: catSelected=4; break;
            case KEY_NPAGE: catSelected+=rows; if(catSelected>4)catSelected=4; break;
            case KEY_PPAGE: catSelected-=rows; if(catSelected<0)catSelected=0; break;
            default: break;
         }
         continue;
      }
      /* Focused panels */
      if(category==0 && focus==1){
         /* We need mapping by index; implement a helper switch on selDisplay */
         if(ch==KEY_UP){ if(selDisplay>0)selDisplay--; continue; }
         if(ch==KEY_DOWN){ if(selDisplay<32)selDisplay++; continue; }
         if(ch==KEY_HOME){selDisplay=0; continue;}
         if(ch==KEY_END){selDisplay=32; continue;}
         if(ch==KEY_NPAGE){selDisplay+=rows; if(selDisplay>32)selDisplay=32; continue;}
         if(ch==KEY_PPAGE){selDisplay-=rows; if(selDisplay<0)selDisplay=0; continue;}
         if(ch==' ' || ch=='\n' || ch=='\r' || ch==KEY_ENTER){
            int idx=selDisplay;
            /* Numbers handling: Space/Enter for numeric items might open a text input or cycle/increment. Original behavior for number options in htop: pressing Space/Enter (?) Let's test later. For now Space cycles hide function bar 0..2, Enter for delay maybe increments? Placeholder */
            switch(idx){
               case 0: case 4: break; /* headers */
               case 1: curScreen->tree_view=!curScreen->tree_view; mark_changed(app); break;
               case 2: curScreen->tree_view_always_by_pid=!curScreen->tree_view_always_by_pid; mark_changed(app); break;
               case 3: curScreen->all_branches_collapsed=!curScreen->all_branches_collapsed; app->collapsedAppliedForScreen[s->active_screen]=0; mark_changed(app); break;
               case 5: s->screen_tabs=!s->screen_tabs; mark_changed(app); break;
               case 6: s->shadow_other_users=!s->shadow_other_users; mark_changed(app); break;
               case 7: s->hide_kernel_threads=!s->hide_kernel_threads; mark_changed(app); break;
               case 8: s->hide_userland_threads=!s->hide_userland_threads; mark_changed(app); break;
               case 9: s->hide_running_in_container=!s->hide_running_in_container; mark_changed(app); break;
               case 10: s->highlight_threads=!s->highlight_threads; mark_changed(app); break;
               case 11: s->show_thread_names=!s->show_thread_names; mark_changed(app); break;
               case 12: s->show_program_path=!s->show_program_path; mark_changed(app); break;
               case 13: s->highlight_base_name=!s->highlight_base_name; mark_changed(app); break;
               case 14: s->highlight_deleted_exe=!s->highlight_deleted_exe; mark_changed(app); break;
               case 15: s->shadow_distribution_path_prefix=!s->shadow_distribution_path_prefix; mark_changed(app); break;
               case 16: s->show_merged_command=!s->show_merged_command; mark_changed(app); break;
               case 17: s->find_comm_in_cmdline=!s->find_comm_in_cmdline; mark_changed(app); break;
               case 18: s->strip_exe_from_cmdline=!s->strip_exe_from_cmdline; mark_changed(app); break;
               case 19: s->highlight_megabytes=!s->highlight_megabytes; mark_changed(app); break;
               case 20: s->header_margin=!s->header_margin; mark_changed(app); break;
               case 21: s->detailed_cpu_time=!s->detailed_cpu_time; mark_changed(app); break;
               case 22: s->cpu_count_from_one=!s->cpu_count_from_one; mark_changed(app); break;
               case 23: s->update_process_names=!s->update_process_names; mark_changed(app); break;
               case 24: s->account_guest_in_cpu_meter=!s->account_guest_in_cpu_meter; mark_changed(app); break;
               case 25: s->show_cpu_usage=!s->show_cpu_usage; mark_changed(app); break;
               case 26: s->show_cpu_frequency=!s->show_cpu_frequency; mark_changed(app); break;
               case 27: s->show_cached_memory=!s->show_cached_memory; mark_changed(app); break;
               case 28: s->enable_mouse=!s->enable_mouse; mark_changed(app); break;
               case 29: /* delay number: original probably prompts / increases by ? We'll cycle +? Temporary: Space increments by 1 tenth? Investigate later */ break;
               case 30: s->highlight_changes=!s->highlight_changes; mark_changed(app); break;
               case 31: break;
               case 32: s->hide_function_bar=(s->hide_function_bar+1)%3; mark_changed(app); break;
               default: break;
            }
            /* rescan/redraw will reflect options where relevant */
            continue;
         }
         if((ch=='+' || ch=='-' ) && (selDisplay==29 || selDisplay==31 || selDisplay==32)){
            int dir=(ch=='+')?1:-1;
            if(selDisplay==29){ s->delay+=dir; if(s->delay<1)s->delay=1; if(s->delay>100)s->delay=100; mark_changed(app); }
            if(selDisplay==31){ s->highlight_changes_delay_secs+=dir; if(s->highlight_changes_delay_secs<1)s->highlight_changes_delay_secs=1; mark_changed(app); }
            if(selDisplay==32){ s->hide_function_bar+=dir; if(s->hide_function_bar<0)s->hide_function_bar=0; if(s->hide_function_bar>2)s->hide_function_bar=2; mark_changed(app); }
            continue;
         }
         continue;
      }
      if(category==1 && focus==1){
         if(ch==KEY_UP){ if(selLayout>0)selLayout--; continue; }
         if(ch==KEY_DOWN){ if(selLayout<12)selLayout++; continue; }
         if(ch==KEY_HOME){selLayout=0; continue;} if(ch==KEY_END){selLayout=12; continue;}
         if(ch==' '||ch=='\n'||ch=='\r'||ch==KEY_ENTER){ setup_apply_header_layout_change(s,selLayout); mark_changed(app); continue; }
         continue;
      }
      if(category==4 && focus==1){
         if(ch==KEY_UP){ if(selColors>0)selColors--; continue; }
         if(ch==KEY_DOWN){ if(selColors<7)selColors++; continue; }
         if(ch==' '||ch=='\n'||ch=='\r'||ch==KEY_ENTER){ s->color_scheme=selColors; colorSchemeGlobal=selColors; useColorsGlobal=app->flags->useColors; if(selColors==1) useColorsGlobal=0; init_colors(); mark_changed(app); continue; }
         continue;
      }
      if(category==2){
         int ncols=header_layout_num_cols(header_layout_index(s->header_layout));
         if(focus>=1 && focus<=ncols){
            int c=focus-1;
            int count=0; for(int i=0;i<s->header[c].meters.count;i++) if(strcmp(s->header[c].meters.items[i],"!")!=0) count++;
            if(ch==KEY_UP){ if(meterColSel[c]>0)meterColSel[c]--; continue; }
            if(ch==KEY_DOWN){ if(meterColSel[c]<count-1)meterColSel[c]++; continue; }
            if(ch==KEY_HOME){meterColSel[c]=0; continue;} if(ch==KEY_END){meterColSel[c]=count-1; if(meterColSel[c]<0)meterColSel[c]=0; continue;}
            if(ch==KEY_NPAGE){meterColSel[c]+=rows; if(meterColSel[c]>=count)meterColSel[c]=count-1; continue;}
            if(ch==KEY_PPAGE){meterColSel[c]-=rows; if(meterColSel[c]<0)meterColSel[c]=0; continue;}
            if(ch==' '){
               int idx=meterColSel[c]; if(idx>=0&&idx<s->header[c].modes.count){ int m=s->header[c].modes.items[idx]; m=m%4+1; s->header[c].modes.items[idx]=m; mark_changed(app);} continue;
            }
            if(ch=='\n'||ch=='\r'||ch==KEY_ENTER){ if(count>0){ meterMoveMode=1; meterMoveCol=c; } continue; }
            if(ch==KEY_DC){
               int idx=meterColSel[c]; if(idx>=0&&idx<s->header[c].meters.count){ sv_remove(&s->header[c].meters,idx); iv_remove(&s->header[c].modes,idx); if(meterColSel[c]>=s->header[c].meters.count)meterColSel[c]=s->header[c].meters.count-1; if(meterColSel[c]<0)meterColSel[c]=0; mark_changed(app);} continue;
            }
            continue;
         } else if(focus==1+ncols){
            int totalAvail=meterDefsCount+sysinfo.cpuCount;
            if(ch==KEY_UP){ if(selAvailMeter>0)selAvailMeter--; continue; }
            if(ch==KEY_DOWN){ if(selAvailMeter<totalAvail-1)selAvailMeter++; continue; }
            if(ch==KEY_HOME){selAvailMeter=0; continue;} if(ch==KEY_END){selAvailMeter=totalAvail-1; continue;}
            if(ch==KEY_NPAGE){selAvailMeter+=rows; if(selAvailMeter>=totalAvail)selAvailMeter=totalAvail-1; continue;}
            if(ch==KEY_PPAGE){selAvailMeter-=rows; if(selAvailMeter<0)selAvailMeter=0; continue;}
            if(ch=='\n'||ch=='\r'||ch==KEY_ENTER){
               int targetCol=ncols-1; /* Which column was last focused? Original Available adds to the column selected before moving to Available (focus path). Our focus sequential Right passes through all columns, last before Available is last column. But if user Right from Column1 direct? Focus increments sequential; if they intended column1 they would need ... SetupPanels in original: AvailableMeters panel is linked to the *currently selected meter column panel* which may be not focus sequential: navigating Right from Column1 goes to Column2, Right again to Available associated with Column2. To add to Column1, user might press Enter on available while Column1 is "selected" via something else? Observations from add_many: we further Right to Column2 then Available and adds to Column2. Good default last column if arrived sequentially. We'll track last meter column focus as meterMoveCol? Use variable based on previous focus before this: focus-1 column = ncols-1. */
               targetCol=focus-2; if(targetCol<0)targetCol=0; if(targetCol>=ncols)targetCol=ncols-1;
               const char* meterName=NULL; int defaultMode=2; char cpuNameBuf[32]="";
               if(selAvailMeter<meterDefsCount){ meterName=meterDefs[selAvailMeter].name; defaultMode=meterDefs[selAvailMeter].defaultMode; }
               else { int cpu=selAvailMeter-meterDefsCount; snprintf(cpuNameBuf,sizeof(cpuNameBuf),"CPU(%d)",cpu+1); meterName=cpuNameBuf; defaultMode=1; }
               /* Clear placeholder ! if present */
               if(s->header[targetCol].meters.count==1 && strcmp(s->header[targetCol].meters.items[0],"!")==0){ sv_free(&s->header[targetCol].meters); iv_free(&s->header[targetCol].modes); memset(&s->header[targetCol],0,sizeof(HeaderCol)); }
               sv_push_dup(&s->header[targetCol].meters,meterName);
               iv_push(&s->header[targetCol].modes,defaultMode);
               meterColSel[targetCol]=s->header[targetCol].meters.count-1;
               meterMoveCol=targetCol; meterMoveMode=1; focus=1+targetCol; mark_changed(app);
               continue;
            }
            continue;
         }
      }
      if(category==3){
         ScreenCfg* sc=&s->screens[selScreenTab>=0&&selScreenTab<s->num_screens?selScreenTab:0];
         if(focus==1){
            if(ch==KEY_UP){ if(selScreenTab>0)selScreenTab--; continue; }
            if(ch==KEY_DOWN){ if(selScreenTab<s->num_screens-1)selScreenTab++; continue; }
            if(ch==KEY_F(2)){
               strncpy(editBuf,sc->name,sizeof(editBuf)-1); editBuf[sizeof(editBuf)-1]=0; editMode=1; continue;
            }
            if(ch==KEY_F(5)){
               editBuf[0]=0; editMode=2; continue;
            }
            if(ch==KEY_F(7)){
               if(selScreenTab>0){ ScreenCfg tmp=s->screens[selScreenTab-1]; s->screens[selScreenTab-1]=s->screens[selScreenTab]; s->screens[selScreenTab]=tmp; selScreenTab--; mark_changed(app);} continue;
            }
            if(ch==KEY_F(8)){
               if(selScreenTab<s->num_screens-1){ ScreenCfg tmp=s->screens[selScreenTab+1]; s->screens[selScreenTab+1]=s->screens[selScreenTab]; s->screens[selScreenTab]=tmp; selScreenTab++; mark_changed(app);} continue;
            }
            if(ch==KEY_F(9)){
               if(s->num_screens>1){
                  free(sc->name); iv_free(&sc->fields);
                  for(int i=selScreenTab;i<s->num_screens-1;i++) s->screens[i]=s->screens[i+1];
                  s->num_screens--; if(selScreenTab>=s->num_screens)selScreenTab=s->num_screens-1;
                  if(s->active_screen>=s->num_screens)s->active_screen=s->num_screens-1;
                  mark_changed(app);
               } continue;
            }
            continue;
         } else if(focus==2){
            if(ch==KEY_UP){ if(selActiveCol>0)selActiveCol--; continue; }
            if(ch==KEY_DOWN){ if(selActiveCol<sc->fields.count-1)selActiveCol++; continue; }
            if(ch==KEY_HOME){selActiveCol=0; continue;} if(ch==KEY_END){selActiveCol=sc->fields.count-1; continue;}
            if(ch==KEY_F(7)){ if(selActiveCol>0){ int t=sc->fields.items[selActiveCol-1]; sc->fields.items[selActiveCol-1]=sc->fields.items[selActiveCol]; sc->fields.items[selActiveCol]=t; selActiveCol--; mark_changed(app);} continue; }
            if(ch==KEY_F(8)){ if(selActiveCol<sc->fields.count-1){ int t=sc->fields.items[selActiveCol+1]; sc->fields.items[selActiveCol+1]=sc->fields.items[selActiveCol]; sc->fields.items[selActiveCol]=t; selActiveCol++; mark_changed(app);} continue; }
            if(ch==KEY_F(9) || ch==KEY_DC){ if(selActiveCol>=0&&selActiveCol<sc->fields.count){ iv_remove(&sc->fields,selActiveCol); if(selActiveCol>=sc->fields.count)selActiveCol=sc->fields.count-1; if(selActiveCol<0)selActiveCol=0; mark_changed(app);} continue; }
            continue;
         } else if(focus==3){
            if(ch==KEY_UP){ if(selAvailCol>0)selAvailCol--; continue; }
            if(ch==KEY_DOWN){ if(selAvailCol<colDefsCount-1)selAvailCol++; continue; }
            if(ch==KEY_HOME){selAvailCol=0; continue;} if(ch==KEY_END){selAvailCol=colDefsCount-1; continue;}
            if(ch==KEY_NPAGE){selAvailCol+=rows; if(selAvailCol>=colDefsCount)selAvailCol=colDefsCount-1; continue;}
            if(ch==KEY_PPAGE){selAvailCol-=rows; if(selAvailCol<0)selAvailCol=0; continue;}
            if(ch==KEY_F(5) || ch=='\n' || ch=='\r' || ch==KEY_ENTER){
               int colId=colDefs[selAvailCol].id;
               /* Original behavior when adding Command etc and duplicates? It may allow duplicate columns? Check later. It inserts at selected active position or appends before Command? We'll append before Command if Command is last and new not Command, else append */
               int insertPos=sc->fields.count;
               if(colId!=COL_Command && sc->fields.count>0 && sc->fields.items[sc->fields.count-1]==COL_Command) insertPos=sc->fields.count-1;
               iv_insert(&sc->fields,insertPos,colId);
               selActiveCol=insertPos; mark_changed(app);
               continue;
            }
            continue;
         }
      }
   }
}
EOF
"}

