            12 show_program_path
            13 highlight_base_name
            14 highlight_deleted_exe
            15 shadow_distribution
            16 show_merged_command
            17 find_comm
            18 strip_exe
            19 highlight_megabytes
            20 header_margin
            21 detailed_cpu_time
            22 cpu_count_from_one
            23 update_process_names
            24 account_guest
            25 show_cpu_usage
            26 show_cpu_frequency
