            32 hide_function_bar number
         */
         struct DispOpt { const char* label; int isHeader; int* boolPtr; int numberKind; int screenBoolKind; } opts[40];
         int nopts=0;
         opts[nopts++]=(struct DispOpt){"",1,NULL,0,-1};
         opts[nopts++]=(struct DispOpt){"Tree view",0,NULL,0,0};
         opts[nopts++]=(struct DispOpt){"- Tree view is always sorted by PID (htop 2 behavior)",0,NULL,0,1};
         opts[nopts++]=(struct DispOpt){"- Tree view is collapsed by default",0,NULL,0,2};
