static void action_sched_panel(AppState* app){
   Proc* sel=selected_proc(app); if(!sel) return;
   if(app->flags->readonly) return;
   int resetOnFork=0;
   /* Get current policy+reset flag */
   int curPol=sched_getscheduler(sel->pid);
   if(curPol>=0 && (curPol & 0x40000000)) { /* SCHED_RESET_ON_FORK 0x40000000 */ resetOnFork=1; curPol &= ~0x40000000; }
   while(1){
      SidePanel panel={0}; panel.title="New policy:"; panel.width=19; panel.enterLabel="Select";
      char buf[64]; snprintf(buf,sizeof(buf),"Reset on fork: %s",resetOnFork?"on":"off"); sv_push_dup(&panel.items,buf);
      const char* names[]={"Other","FiFo","RoundRobin","Batch","Idle"};
      int pols[]={SCHED_OTHER,SCHED_FIFO,SCHED_RR,3,5}; /* SCHED_BATCH 3, SCHED_IDLE 5 */
      for(int i=0;i<5;i++){
         sv_push_dup(&panel.items,names[i]);
         if(pols[i]==curPol) { /* initial selected is Reset item according capture - not policy. Keep 0 */ }
      }
      panel.selected=0;
      int r=-99;
      /* custom run to intercept Enter on item0 toggling */
      while(1){
         side_panel_draw(app,&panel);
         int ch=read_key_with_timeout(app->settings->delay*100);
         if(ch==ERR){ rescan_and_rebuild(app); continue; }
         if(gotTermSignal){app->quit=1;app->cleanExit=0; sv_free(&panel.items); return;}
         if(ch==27 || ch=='q'){ r=-1; break; }
         if(ch=='\n'||ch=='\r'||ch==KEY_ENTER){
            if(panel.selected==0){
               resetOnFork=!resetOnFork;
               char b[64]; snprintf(b,sizeof(b),"Reset on fork: %s",resetOnFork?"on":"off"); free(panel.items.items[0]); panel.items.items[0]=xstrdup(b);
               continue;
            }
            r=panel.selected; break;
         }
         int rows=list_rows_available(app); if(rows<1)rows=1;
         switch(ch){
            case KEY_UP: if(panel.selected>0)panel.selected--; break;
            case KEY_DOWN: if(panel.selected<panel.items.count-1)panel.selected++; break;
            case KEY_HOME: panel.selected=0; break;
            case KEY_END: panel.selected=panel.items.count-1; break;
            case KEY_PPAGE: panel.selected-=rows; if(panel.selected<0)panel.selected=0; break;
            case KEY_NPAGE: panel.selected+=rows; if(panel.selected>=panel.items.count)panel.selected=panel.items.count-1; break;
         }
      }
      sv_free(&panel.items);
      if(r<0) return;
      int policy=pols[r-1];
      int priority=0;
      if(policy==SCHED_FIFO || policy==SCHED_RR){
         /* priority panel 1..99 items as strings */
         SidePanel pp={0}; pp.title="Priority:"; pp.width=17; pp.enterLabel="Select";
         for(int pr=1;pr<=99;pr++){ char b[32]; snprintf(b,sizeof(b),"%d",pr); sv_push_dup(&pp.items,b); }
         /* default priority: current sched param if RT else maybe (min+max)/2? Need check selected in capture; default maybe 50? We'll check with selparse later */
         struct sched_param sp; if(sched_getparam(sel->pid,&sp)==0 && sp.sched_priority>=1 && sp.sched_priority<=99) pp.selected=sp.sched_priority-1; else pp.selected=0;
         int pr2=side_panel_run(app,&pp);
         sv_free(&pp.items);
         if(pr2<0){ /* Esc from priority likely goes back to policy panel or cancels all? If it cancels all, return. We'll decide go back to policy loop? That matches side panel chaining in htop ScreenManager where Esc pops a panel. */
            continue;
         }
         priority=pr2+1;
      }
      struct sched_param param; memset(&param,0,sizeof(param)); param.sched_priority=priority;
      int polWithFlag=policy | (resetOnFork? 0x40000000:0);
      int* pids=NULL; int np=collect_target_pids(app,&pids);
      for(int i=0;i<np;i++) sched_setscheduler(pids[i],polWithFlag,&param);
      free(pids); rescan_and_rebuild(app); return;
   }
}
