            case KEY_DOWN: if(panel.selected<panel.items.count-1)panel.selected++; break;
            case KEY_HOME: panel.selected=0; break;
            case KEY_END: panel.selected=panel.items.count-1; break;
            case KEY_PPAGE: panel.selected-=rows; if(panel.selected<0)panel.selected=0; break;
            case KEY_NPAGE: panel.selected+=rows; if(panel.selected>=panel.items.count)panel.selected=panel.items.count-1; break;
         }
      }
      sv_free(&panel.items);
      if(r<0) return;
      int policy=pols[r-1];
      int priority=0;
      if(policy==SCHED_FIFO || policy==SCHED_RR){
         /* priority panel 1..99 items as strings */
         SidePanel pp={0}; pp.title="Priority:"; pp.width=17; pp.enterLabel="Select";
         for(int pr=1;pr<=99;pr++){ char b[32]; snprintf(b,sizeof(b),"%d",pr); sv_push_dup(&pp.items,b); }
         /* default priority: current sched param if RT else maybe (min+max)/2? Need check selected in capture; default maybe 50? We'll check with selparse later */
         struct sched_param sp; if(sched_getparam(sel->pid,&sp)==0 && sp.sched_priority>=1 && sp.sched_priority<=99) pp.selected=sp.sched_priority-1; else pp.selected=0;
