static void set_tagged_cache(Proc* pr,int tagged){
   pr->tagged=tagged;
   CacheEntry* ce=cache_get(pr->pid,pr->starttime_ticks,1); if(ce)ce->tagged=tagged;
}
static void set_show_children_cache(Proc* pr,int show){
   pr->show_children=show; pr->collapsed=!show;
   CacheEntry* ce=cache_get(pr->pid,pr->starttime_ticks,1); if(ce)ce->show_children=show;
}
static void apply_collapse_all(AppState* app, ScreenCfg* sc){
   /* Determine root pids based on app->scan.all ppid presence */
   for(int i=0;i<app->scan.all.count;i++){
      Proc* pr=app->scan.all.items[i];
      int parentExists=0;
      int effP=pr->isThread?pr->tgid:pr->ppid;
      if(effP>0 && effP!=pr->pid){
         for(int j=0;j<app->scan.all.count;j++) if(app->scan.all.items[j]->pid==effP && !app->scan.all.items[j]->isThread){parentExists=1;break;}
      }
      set_show_children_cache(pr, parentExists?0:1);
   }
   (void)sc;
}
static int function_bar_visible(AppState* app, int tempHidden){
   if(app->settings->hide_function_bar==2) return 0;
   if(app->settings->hide_function_bar!=0 && app->settings->hide_function_bar!=1) return 0;
   if(tempHidden) return 0;
   return 1;
}

/* Incremental search/filter submode on main screen. mode 0 search, 1 filter. Returns after Enter/Esc */
static void inc_mode_run(AppState* app,int isFilter){
   Settings* s=app->settings;
   char buf[1024]="";
   int origSelected=app->selected;
   char* origFilter=app->incFilter?xstrdup(app->incFilter):NULL;
   if(isFilter && app->incFilter) strncpy(buf,app->incFilter,sizeof(buf)-1);
   if(!isFilter && app->incSearch) strncpy(buf,app->incSearch,sizeof(buf)-1);
   /* In search if we start with previous term, does original display it or empty? Pressing / after a previous search likely starts empty? Testing later. For now start search empty if coming via '/'? app incSearch usage for F3 outside mode only. We'll start empty for search */
   if(!isFilter) buf[0]=0;
   while(1){
      if(gotTermSignal){ app->quit=1; app->cleanExit=0; free(origFilter); return; }
      /* draw main with current filter (if filter mode, app->incFilter synced to buf) */
      if(isFilter){
         free(app->incFilter); app->incFilter=xstrdup(buf);
         rebuild_only(app);
      }
      /* draw, but replace function bar */
      erase(); draw_header(s,&app->scan,app->hideMetersRuntime); draw_process_list(app,0);
      if(isFilter){
         char prompt[1200]; snprintf(prompt,sizeof(prompt),"Filter: %s",buf);
         FuncItem items[]={{"Enter","Done",6},{"Esc","Clear",9}};
         draw_function_bar(items,2,prompt);
      } else {
         char prompt[1200]; snprintf(prompt,sizeof(prompt),"Search: %s",buf);
         FuncItem items[]={{"F3","Next",6},{"S-F3","Prev",7},{"Esc","Cancel",10}};
         draw_function_bar(items,3,prompt);
      }
      refresh();
      int ch=read_key_with_timeout(s->delay*100);
      if(ch==ERR){
         if(!app->paused) rescan_and_rebuild(app);
         continue;
      }
      if(ch==27){
         if(isFilter){ free(app->incFilter); app->incFilter=xstrdup(""); rebuild_only(app); }
         else { app->selected=origSelected; }
         free(origFilter); return;
      }
      if(ch=='\n'||ch=='\r'||ch==KEY_ENTER){
         if(isFilter){ free(app->incFilter); app->incFilter=xstrdup(buf); }
         else { free(app->incSearch); app->incSearch=xstrdup(buf); }
         free(origFilter); return;
      }
      if(!isFilter && (ch==KEY_F(3))){
         /* next */
         if(buf[0] && app->scan.display.count>0){
            int start=app->selected;
            for(int k=1;k<=app->scan.display.count;k++){ int idx=(start+k)%app->scan.display.count; if(filter_match(app->scan.display.items[idx]->cmdline,buf)){app->selected=idx; break;} }
         }
         continue;
      }
      if(!isFilter && ch==KEY_F(15)){ /* Shift-F3 - ncurses KEY_F(15)? Shift F3 is F15 (3+12) */
         if(buf[0] && app->scan.display.count>0){
            int start=app->selected;
            for(int k=1;k<=app->scan.display.count;k++){ int idx=(start-k+app->scan.display.count*100)%app->scan.display.count; if(filter_match(app->scan.display.items[idx]->cmdline,buf)){app->selected=idx; break;} }
         }
         continue;
      }
      if(ch==KEY_BACKSPACE || ch==127 || ch==8){
         size_t l=strlen(buf); if(l)buf[l-1]=0;
      } else if(ch==21){ /* Ctrl-U clear */
         buf[0]=0;
      } else if(ch>=32 && ch<127){
         size_t l=strlen(buf); if(l<sizeof(buf)-1){buf[l]=(char)ch; buf[l+1]=0;}
      } else {
         continue;
      }
      if(!isFilter){
         /* incremental search from original selected (?) or from top? Use first match at or after origSelected, wrap */
         if(buf[0] && app->scan.display.count>0){
            int found=-1;
            for(int k=0;k<app->scan.display.count;k++){ int idx=(origSelected+k)%app->scan.display.count; if(filter_match(app->scan.display.items[idx]->cmdline,buf)){found=idx;break;} }
            if(found>=0) app->selected=found;
         } else app->selected=origSelected;
      } else {
         app->selected=0; app->scrollTop=0;
      }
   }
}

