   int frameCount=0;
   while(!app.quit){
      if(gotTermSignal){ app.cleanExit=0; break; }
      /* update function bar visibility settings value in draw: draw_main uses settings hide_function_bar directly and will draw if 1 but temp handling done by temporarily setting? We'll manage by patching settings? Instead draw_main checks settings only. For tempHidden, we temporarily set hide=2 around draw then restore */
      {
         int savedHide=settings->hide_function_bar;
         if(functionBarTempHidden) settings->hide_function_bar=2;
