                     FILE* f=fopen(path,"w"); if(f){ fprintf(f,"%ld",nv); fclose(f); }
                  }
               }
               free(pids); rescan_and_rebuild(&app);
            }
            break;
         }
         case 'k': action_kill_panel(&app); break;
         case 'I': if(sc->tree_view) sc->tree_sort_direction*=-1; else sc->sort_direction*=-1; mark_changed(&app); rebuild_only(&app); break;
         case '+': case '-': case '*': {
            if(sc->tree_view){
               if(ch=='*'){
                  sc->all_branches_collapsed=!sc->all_branches_collapsed;
                  if(sc->all_branches_collapsed){ apply_collapse_all(&app,sc); app.collapsedAppliedForScreen[settings->active_screen]=1; }
                  else { for(int i=0;i<app.scan.all.count;i++) set_show_children_cache(app.scan.all.items[i],1); app.collapsedAppliedForScreen[settings->active_screen]=0; }
                  mark_changed(&app);
               } else if(sel){
                  set_show_children_cache(sel, ch=='+');
               }
               rebuild_only(&app);
            }
            break;
         }
         case 'a': action_affinity_panel(&app); break;
         case 'u': action_user_panel(&app); break;
         case 'N': case 'P': case 'M': case 'T': {
            int colId = ch=='N'?COL_PID: ch=='P'?COL_PERCENT_CPU: ch=='M'?COL_PERCENT_MEM: COL_TIME;
            const ColDef* cd=col_by_id(colId);
            sc->tree_view=0; sc->sort_key=colId; if(cd)sc->sort_direction=cd->defaultDir;
            mark_changed(&app); rebuild_only(&app); break;
         }
         case 'F': app.follow=!app.follow; if(app.follow && sel) app.followPid=sel->pid; break;
         case 'K': settings->hide_kernel_threads=!settings->hide_kernel_threads; mark_changed(&app); rescan_and_rebuild(&app); break;
         case 'H': settings->hide_userland_threads=!settings->hide_userland_threads; mark_changed(&app); rescan_and_rebuild(&app); break;
         case 'O': settings->hide_running_in_container=!settings->hide_running_in_container; mark_changed(&app); rescan_and_rebuild(&app); break;
         case 'p': settings->show_program_path=!settings->show_program_path; mark_changed(&app); rescan_and_rebuild(&app); break;
         case 'm': settings->show_merged_command=!settings->show_merged_command; mark_changed(&app); rescan_and_rebuild(&app); break;
         case 'Z': app.paused=!app.paused; break;
         case '#': app.hideMetersRuntime=!app.hideMetersRuntime; break;
         case 's': if(sel){ char title[1024]; snprintf(title,sizeof(title),"Trace of process %d - %s",sel->pid,sel->cmdline?sel->cmdline:""); StrVec lines=make_trace_lines(sel); viewer_run(&app,title,&lines,sel->pid,1); sv_free(&lines); } break;
         case 'l': if(sel){ char title[1024]; snprintf(title,sizeof(title),"Snapshot of files open in process %d - %s",sel->pid,sel->cmdline?sel->cmdline:""); StrVec lines=make_lsof_lines(sel); viewer_run(&app,title,&lines,sel->pid,0); sv_free(&lines); } break;
         case 'w': if(sel){ char title[1024]; snprintf(title,sizeof(title),"Command of process %d - %s",sel->pid,sel->cmdline?sel->cmdline:""); StrVec lines=make_cmd_lines(sel,getmaxx(stdscr)); viewer_run(&app,title,&lines,sel->pid,0); sv_free(&lines); } break;
         case 'x': if(sel){ char title[1024]; snprintf(title,sizeof(title),"Snapshot of file locks of process %d - %s",sel->pid,sel->cmdline?sel->cmdline:""); StrVec lines=make_locks_lines(sel); viewer_run(&app,title,&lines,sel->pid,0); sv_free(&lines); } break;
         case 'e': if(sel){ char title[1024]; snprintf(title,sizeof(title),"Environment of process %d - %s",sel->pid,sel->cmdline?sel->cmdline:""); StrVec lines=make_env_lines(sel); viewer_run(&app,title,&lines,sel->pid,0); sv_free(&lines); } break;
         case 'i': action_ioprio_panel(&app); break;
         case 'Y': action_sched_panel(&app); break;
         default: {
            if(ch>=32 && ch<127){
               /* Start search with this character (unbound) */
               /* To implement, set a one-char initial search by using inc_mode with preset - our inc_mode starts empty. We'll push char as if typed: temporary store in incSearch and call a variant by ungetting? Simpler: start search mode and inject ch via ungetch before mode loop reads keys with getch (but our read_key wraps getch, ungetch works). */
               ungetch(ch);
               inc_mode_run(&app,0);
            }
            break;
         }
      }
      if(app.quit) break;
   }
   endwin();
   /* Save config if clean exit and changed */
   int exitCode=0;
   if(app.cleanExit && settings->changed){
      settings_write(settings);
   }
   /* free minimal */
   return exitCode;
}
