    if perms[2]=='x': add('exec_perm',size)
    if inode and perms[2]=='x': add('inode_exec',size)
    if inode and perms[3]=='p': add('inode_private',size) # perms 4th char?
    if 'lib' in path: add('path_contains_lib',size)
    if path.startswith('/usr/lib'): add('usr_lib',size)
    if path.startswith('/usr/lib') or '.so' in path: add('usrlib_or_so',size)
