new='''static void format_size_kib(char* buf, size_t bufsz, unsigned long long kib){
   if(kib < 100000ULL){
      snprintf(buf,bufsz,"%llu",kib);
      return;
   }
   double v = kib / 1024.0;
   const char units[] = "MGTPE";
   int u=0;
   while(v >= 10000.0 && u < (int)sizeof(units)-2){
      v /= 1024.0; u++;
   }
   if(v < 10) snprintf(buf,bufsz,"%.2f%c",v,units[u]);
   else if(v < 100) snprintf(buf,bufsz,"%.1f%c",v,units[u]);
   else snprintf(buf,bufsz,"%.0f%c",v,units[u]);
}
