start=s.index("static void format_size_bytes_text")
end=s.index("/* format io rate")
new2='''static void format_size_bytes_text(char* buf, size_t bufsz, unsigned long long bytes){
   if(bytes==0){ snprintf(buf,bufsz,"0K"); return; }
   const char* units[]={"K","M","G","T","P","E"};
   double v = bytes/1024.0;
   int u=0;
   while(v>=1024 && u<5){ v/=1024.0; u++; }
   if(v < 10) snprintf(buf,bufsz,"%.2f%s",v,units[u]);
   else if(v < 100) snprintf(buf,bufsz,"%.1f%s",v,units[u]);
   else snprintf(buf,bufsz,"%.0f%s",v,units[u]);
   /* For K values, original shows e.g. 0K; small K values with 2 decimals are unlikely in memory meters (values are page multiples) */
   if(u==0 && v>=1){
      /* Trim format to integer for whole K if v is integral (?) Memory cache 0K handled; keep 3-sig for now but avoid "5.00K" -> "5K"? */
      /* printSize in htop for <10K may show decimals based bytes - uncertain. */
   }
}
'''
s=s[:start]+new2+s[end:]
p.write_text(s)
print("patched formats")
