block='''   FILE* f=fopen("/proc/diskstats","r");
   if(f){
      unsigned long long readSec=0,writeSec=0,timeIO=0;
      int diskCount=0;
      char* line=NULL; size_t cap=0;
      while(getline(&line,&cap,f)>0){
         int major,minor; char name[64];
         unsigned long long readsComp=0,readsMerged=0,rs=0,timeRead=0,writesComp=0,writesMerged=0,ws=0,timeWrite=0,iosProg=0,timeDoing=0,weighted=0;
         if(sscanf(line,"%d %d %63s %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",&major,&minor,name,&readsComp,&readsMerged,&rs,&timeRead,&writesComp,&writesMerged,&ws,&timeWrite,&iosProg,&timeDoing,&weighted)>=13){
            (void)major;(void)minor;(void)weighted;(void)iosProg;
            /* only whole disks present in /sys/block */
            char syspath[256]; snprintf(syspath,sizeof(syspath),"/sys/block/%s",name);
            struct stat st; if(stat(syspath,&st)!=0) continue;
            if(strncmp(name,"loop",4)==0 || strncmp(name,"ram",3)==0) continue;
