      unsigned long long rb=readSec*512ULL, wb=writeSec*512ULL;
      if(sysinfo.lastDiskSampleTime>0 && t>sysinfo.lastDiskSampleTime){
         double dt=t-sysinfo.lastDiskSampleTime;
         sysinfo.diskReadRate = (rb>=sysinfo.diskReadBytesPrev)? (rb-sysinfo.diskReadBytesPrev)/dt:0;
         sysinfo.diskWriteRate = (wb>=sysinfo.diskWriteBytesPrev)? (wb-sysinfo.diskWriteBytesPrev)/dt:0;
         if(timeIO>=sysinfo.diskTimePrev){
            double denom=dt*1000.0*(diskCount>0?diskCount:1);
            sysinfo.diskBusyPercent = denom>0? 100.0*((timeIO-sysinfo.diskTimePrev))/denom:0;
            /* If original sums without dividing disks, busy may ?? We choose average to remain percent */
         }
         if(sysinfo.diskBusyPercent>100) sysinfo.diskBusyPercent=100;
         if(sysinfo.diskBusyPercent<0) sysinfo.diskBusyPercent=0;
      }
      sysinfo.diskReadBytesPrev=rb; sysinfo.diskWriteBytesPrev=wb; sysinfo.diskTimePrev=timeIO; sysinfo.lastDiskSampleTime=t;
   }
'''
