{"command":"cat > /tmp/patch_tree.py << 'PY'
from pathlib import Path
p=Path("src/htop.c"); s=p.read_text()
start=s.index("   if(!screen->tree_view){")
end=s.index("static void free_scan")
new_block='''   if(!screen->tree_view){
      g_sort_key=screen->sort_key; g_sort_dir=screen->sort_direction;
      if(visible.count>1) qsort(visible.items,visible.count,sizeof(Proc*),proc_qcmp);
      res->display=visible;
      for(int i=0;i<res->display.count;i++){ res->display.items[i]->tree_depth=0; free(res->display.items[i]->tree_prefix); res->display.items[i]->tree_prefix=NULL; }
   } else {
      /* Release visible vector (will rebuild structurally) */
      free(visible.items); visible.items=NULL; visible.count=visible.cap=0;
      /* Structural list: hide settings only (text/user/pid filters applied after tree indentation) */
      ProcVec structural={0};
      for(int i=0;i<res->all.count;i++){
         Proc* pr=res->all.items[i];
         if(settings->hide_kernel_threads && pr->isKernelThread) continue;
         if(settings->hide_userland_threads && pr->isThread) continue;
         if(settings->hide_running_in_container && pr->is_container) continue;
         pv_push(&structural,pr);
      }
      int tkey=screen->tree_view_always_by_pid? COL_PID: screen->tree_sort_key;
      int tdir=screen->tree_view_always_by_pid? 1: screen->tree_sort_direction;
      g_sort_key=tkey; g_sort_dir=tdir;
      if(structural.count>1) qsort(structural.items,structural.count,sizeof(Proc*),proc_qcmp);
      int n=structural.count;
      typedef struct StackItem { Proc* pr; int depth; char* displayPrefix; char* childBasePrefix; } StackItem;
      int stackCap=n+16; StackItem* stack=xmalloc(sizeof(StackItem)*stackCap); int sp=0;
      for(int i=n-1;i>=0;i--){
         Proc* pr=structural.items[i];
         int effParent = pr->isThread? pr->tgid : pr->ppid;
         int parentExists=0;
         if(effParent>0 && effParent!=pr->pid){
            for(int j=0;j<n;j++) if(structural.items[j]->pid==effParent){ parentExists=1; break; }
         }
         if(!parentExists){
            stack[sp].pr=pr; stack[sp].depth=0; stack[sp].displayPrefix=xstrdup(""); stack[sp].childBasePrefix=xstrdup(""); sp++;
         }
      }
      ProcVec candidates={0};
      while(sp>0){
         StackItem it=stack[--sp];
         Proc* pr=it.pr;
         int already=0; for(int i=0;i<candidates.count;i++) if(candidates.items[i]==pr){already=1;break;}
         if(already){ free(it.displayPrefix); free(it.childBasePrefix); continue; }
         pr->tree_depth=it.depth;
         free(pr->tree_prefix); pr->tree_prefix=it.displayPrefix;
         pv_push(&candidates,pr);
         if(pr->show_children){
            Proc* children[8192]; int nchild=0;
            for(int i=0;i<n && nchild<8192;i++){
               Proc* ch=structural.items[i];
               int effP=ch->isThread? ch->tgid: ch->ppid;
               if(effP==pr->pid && ch!=pr) children[nchild++]=ch;
            }
            for(int ci=nchild-1; ci>=0; ci--){
               Proc* ch=children[ci];
               int isLast=(ci==nchild-1);
               const char* glyph = ch->show_children? "`- " : "`+ ";
               char* disp=NULL;
               if(it.depth==0) disp=xstrdup(glyph);
               else disp=str_cat3(it.childBasePrefix,glyph,NULL);
               const char* continuation = isLast? "   " : "|  ";
               char* childBase=NULL;
               if(it.depth==0) childBase=xstrdup(continuation);
               else childBase=str_cat3(it.childBasePrefix,continuation,NULL);
               if(sp>=stackCap){ stackCap*=2; stack=xrealloc(stack,sizeof(StackItem)*stackCap); }
               stack[sp].pr=ch; stack[sp].depth=it.depth+1; stack[sp].displayPrefix=disp; stack[sp].childBasePrefix=childBase; sp++;
            }
         }
         free(it.childBasePrefix);
      }
      free(stack);
      /* Display candidates after pid/user/text filters (proc_visible_basic handles these; runtime user handled below) */
      for(int i=0;i<candidates.count;i++){
