from pathlib import Path
p=Path("src/htop.c"); s=p.read_text()
# Elapsed use scan now double
s=s.replace("pr->elapsed = ((double)time(NULL) - pr->starttime_epoch);", "pr->elapsed = (now - pr->starttime_epoch);")
# IO path task-specific
old='''      /* io file per process (tgid) - thread io uses task io? Use pr->pid path if exists */
      snprintf(path,sizeof(path),"/proc/%d/io",pr->pid);
      char* io=read_file_alloc(path,NULL);
      if(!io){ snprintf(path,sizeof(path),"/proc/%d/io",pid); io=read_file_alloc(path,NULL); }'''
new='''      if(pr->tgid>0) snprintf(path,sizeof(path),"/proc/%d/task/%d/io",pr->tgid,pr->pid);
      else snprintf(path,sizeof(path),"/proc/%d/io",pr->pid);
      char* io=read_file_alloc(path,NULL);
      if(!io){ snprintf(path,sizeof(path),"/proc/%d/io",pid); io=read_file_alloc(path,NULL); }'''
assert old in s; s=s.replace(old,new)
# PSS: skip for threads. Change if(need_pss) to if(need_pss && !pr->isThread); the else already sets m_pss=resident - need set 0 for thread in else. Replace else block values with condition in patch after.
s=s.replace("   if(need_pss){\n      unsigned long long privSum=0;", "   if(need_pss && !pr->isThread){\n      unsigned long long privSum=0;")
old2='''   } else {
      pr->m_priv_kib = rssAnonKib;
      pr->m_pss_kib=pr->m_resident_kib;
   }'''
new2='''   } else {
      if(pr->isThread){ pr->m_priv_kib=0; pr->m_pss_kib=0; pr->m_psswp_kib=0; }
      else { pr->m_priv_kib = rssAnonKib; pr->m_pss_kib=pr->m_resident_kib; }
   }
   if(pr->isThread){ pr->m_trs_kib=0; pr->m_drs_kib=0; }'''
assert old2 in s; s=s.replace(old2,new2)
# EXE handling: don't set pr->exe for threads or on failure
old3='''         const char* base=strrchr(buf,'/');
         pr->exe=xstrdup(base?base+1:buf);
      } else {
         pr->exe=xstrdup("");
      }'''
new3='''         if(!pr->isThread){ const char* base=strrchr(buf,'/'); pr->exe=xstrdup(base?base+1:buf); }
      } else {
         pr->exe=NULL;
      }'''
assert old3 in s; s=s.replace(old3,new3)
# CWD failure leave NULL
s=s.replace('if(n>=0){buf[n]=0; pr->cwd=xstrdup(buf);} else pr->cwd=xstrdup("");', 'if(n>=0){buf[n]=0; pr->cwd=xstrdup(buf);} else pr->cwd=NULL;')
# SECATTR failure leave NULL
s=s.replace('if(data){ /* string may have trailing NUL; data len */ pr->secattr=trim_newline_dup(data); free(data); } else pr->secattr=xstrdup("");', 'if(data){ pr->secattr=trim_newline_dup(data); free(data); } else pr->secattr=NULL;')
# Format N/A
s=s.replace('case COL_SECATTR: snprintf(buf,sz,"%s",pr->secattr?pr->secattr:""); break;', 'case COL_SECATTR: snprintf(buf,sz,"%s",pr->secattr?pr->secattr:"N/A"); break;')
s=s.replace('case COL_EXE: snprintf(buf,sz,"%s",pr->exe?pr->exe:""); break;', 'case COL_EXE: snprintf(buf,sz,"%s",pr->exe?pr->exe:"N/A"); break;')
s=s.replace('case COL_CWD: snprintf(buf,sz,"%s",pr->cwd?pr->cwd:""); break;', 'case COL_CWD: snprintf(buf,sz,"%s",pr->cwd?pr->cwd:"N/A"); break;')
# cgroup default: if raw missing leave pr->cgroup null? Keep "/" because file usually exists; but to give N/A on failure, change fallback
s=s.replace('pr->cgroup=raw?raw:xstrdup("/");', 'pr->cgroup=raw; /* NULL if unreadable */')
s=s.replace('case COL_CGROUP: snprintf(buf,sz,"%s",pr->cgroup?pr->cgroup:""); break;', 'case COL_CGROUP: snprintf(buf,sz,"%s",pr->cgroup?pr->cgroup:"N/A"); break;')
s=s.replace('case COL_CCGROUP: snprintf(buf,sz,"%s",pr->ccgroup?pr->ccgroup:""); break;', 'case COL_CCGROUP: snprintf(buf,sz,"%s",pr->ccgroup?pr->ccgroup:"N/A"); break;')
s=s.replace('case COL_CONTAINER: snprintf(buf,sz,"%s",pr->container?pr->container:""); break;', 'case COL_CONTAINER: snprintf(buf,sz,"%s",pr->container?pr->container:"N/A"); break;')
# condense_cgroup handles NULL returning strdup("") currently - for missing cgroup ccgroup should be NULL. Adjust assignment after cgroup: currently 'pr->ccgroup=condense_cgroup(pr->cgroup);'
s=s.replace('pr->ccgroup=condense_cgroup(pr->cgroup);', 'pr->ccgroup=pr->cgroup?condense_cgroup(pr->cgroup):NULL;')
# guess_container called with NULL returns xstrdup("") - change assignment in fill to only if cgroup present
s=s.replace('int isc=0; pr->container=guess_container(pr->cgroup,&isc); pr->is_container=isc;', 'int isc=0; pr->container=pr->cgroup?guess_container(pr->cgroup,&isc):NULL; pr->is_container=isc;')
p.write_text(s)
print('patched')
