from pathlib import Path
p=Path("src/htop.c"); s=p.read_text()
# Remove path strip from get_cmdline_for
start=s.index("   /* show_program_path off:")
end=s.index("   return result;\n}", start)
s=s[:start]+s[end:]
# Insert build_display function after get_cmdline_for (after its closing brace following return result)
marker="static char* trim_newline_dup"
buildfunc=r'''
static char* build_display_command(Proc* pr, const char* raw, Settings* settings){
   if(settings && pr->isThread && settings->show_thread_names){
      return xstrdup(pr->comm?pr->comm:"");
   }
   if(settings && settings->show_merged_command){
      if(pr->exe_path && pr->exe_path[0]){
         const char* rest=raw?raw:"";
         if(settings->strip_exe_from_cmdline){
            const char* sp=strchr(rest,' ');
            if(sp) rest=sp+1; else rest="";
         }
         size_t need=strlen(pr->exe_path)+(pr->comm?strlen(pr->comm):0)+strlen(rest)+16;
         char* merged=xmalloc(need);
         if(pr->comm && pr->exe && strcmp(pr->comm,pr->exe)!=0) snprintf(merged,need,"%s (%s) %s",pr->exe_path,pr->comm,rest);
         else if(rest && *rest) snprintf(merged,need,"%s %s",pr->exe_path,rest);
         else snprintf(merged,need,"%s",pr->exe_path);
         trim_trailing_spaces(merged);
         return merged;
      }
      return xstrdup(raw?raw:"");
   }
   char* result=xstrdup(raw?raw:"");
   if(settings && !settings->show_program_path && result[0]){
      char* space=strchr(result,' ');
      char* first=space?xstrndup(result,(size_t)(space-result)):xstrdup(result);
      const char* base=strrchr(first,'/');
      if(base){
         char* nr=space?str_cat3(base+1,space,NULL):xstrdup(base+1);
         free(result); result=nr;
      }
      free(first);
   }
   return result;
}
'''
assert marker in s; s=s.replace(marker,buildfunc+marker,1)
# Replace command construction in scan_processes
start=s.index("         if(settings && !settings->update_process_names && ce->cmdline_cached){")
end=s.index("         /* CPU percent */")
newblock=r'''         {
            char* rawCmdline=NULL;
            if(settings && !settings->update_process_names && ce->cmdline_cached){
               rawCmdline=xstrdup(ce->cmdline_cached);
            } else {
               rawCmdline=get_cmdline_for(pr->pid,pr->tgid,pr->comm,NULL);
               if(ce->cmdline_cached) free(ce->cmdline_cached);
               ce->cmdline_cached=xstrdup(rawCmdline?rawCmdline:"");
            }
            /* Thread cmdline raw is same as process; if show_thread_names display builder picks comm. But cache key is per tid and ce raw may have been stored from its own get_cmdline_for (which uses tgid) */
            pr->cmdline=build_display_command(pr,rawCmdline,settings);
            free(rawCmdline);
         }
'''
s=s[:start]+newblock+s[end:]
# Remove rescans from setters: kill
s=s.replace("      free(pids);\n      rescan_and_rebuild(app);\n   }\n   sv_free(&panel.items);\n}\nstatic void action_user_panel", "      free(pids);\n   }\n   sv_free(&panel.items);\n}\nstatic void action_user_panel")
# affinity: after free(pids); rescan...; break;
s=s.replace("free(pids); rescan_and_rebuild(app); break;", "free(pids); break;")
# ioprio: free(pids); rescan...
s=s.replace("free(pids); rescan_and_rebuild(app);\n#endif", "free(pids);\n#endif")
# sched: free(pids); rescan...; return;
s=s.replace("free(pids); rescan_and_rebuild(app); return;", "free(pids); return;")
# toggles in main: replace specific cases
for key,field in [("K","hide_kernel_threads"),("H","hide_userland_threads"),("O","hide_running_in_container"),("p","show_program_path"),("m","show_merged_command")]:
    old=f"case '{key}': settings->{field}=!settings->{field}; mark_changed(&app); rescan_and_rebuild(&app); break;"
    new=f"case '{key}': settings->{field}=!settings->{field}; mark_changed(&app); rebuild_only(&app); break;"
    if old not in s: print("toggle missing",key)
    s=s.replace(old,new)
# Renice block replace
start=s.index("         case ']': case '[': {")
end=s.index("         case '}': case '{': {")
newrenice=r'''         case ']': case '[': {
            if(!flags.readonly && sel){
               int dir=(ch==']')?-1:1;
               int* pids=NULL; int np=collect_target_pids(&app,&pids);
               for(int i=0;i<np;i++){
                  errno=0; int cur=getpriority(PRIO_PROCESS,pids[i]); if(errno!=0){
                     /* find proc nice */ cur=0; for(int j=0;j<app.scan.all.count;j++) if(app.scan.all.items[j]->pid==pids[i]){cur=(int)app.scan.all.items[j]->nice;break;}
                  }
                  int nv=cur+dir; if(nv<-20)nv=-20; if(nv>19)nv=19;
                  if(setpriority(PRIO_PROCESS,pids[i],nv)==0){
                     for(int j=0;j<app.scan.all.count;j++) if(app.scan.all.items[j]->pid==pids[i]) app.scan.all.items[j]->nice=nv;
                  }
               }
               free(pids);
            }
            break;
         }
'''
s=s[:start]+newrenice+s[end:]
# Autogroup: remove rescan and update field on success (current code has if(f){fprintf...;fclose} then free/rescan)
s=s.replace("FILE* f=fopen(path,\"w\"); if(f){ fprintf(f,\"%ld\",nv); fclose(f); }", "FILE* f=fopen(path,\"w\"); if(f){ fprintf(f,\"%ld\",nv); if(fclose(f)==0){ for(int j=0;j<app.scan.all.count;j++) if(app.scan.all.items[j]->pid==pids[i]) app.scan.all.items[j]->autogroup_nice=nv; } }")
# The autogroup block still has free(pids); rescan_and_rebuild
s=s.replace("free(pids); rescan_and_rebuild(&app);\n            }\n            break;\n         }\n         case 'k':", "free(pids);\n            }\n            break;\n         }\n         case 'k':")
p.write_text(s)
print("patched")
