{"command":"cat > /tmp/patch_merge.py << 'PY'
from pathlib import Path
p=Path("src/htop.c");s=p.read_text()
start=s.index("static char* build_display_command")
end=s.index("static char* trim_newline_dup")
new=r'''static int comm_found_in_cmdline(const char* cmdline,const char* comm){
   if(!cmdline||!comm||!*comm)return 0;
   size_t cl=strlen(comm);
   const char* p=cmdline;
   while((p=strstr(p,comm))!=NULL){
      int startOk = (p==cmdline || p[-1]==' ' || p[-1]=='/');
      char after=p[cl];
      int endOk = (after=='\0' || after==' ');
      if(startOk && endOk) return 1;
      p++;
   }
   return 0;
}
static char* build_display_command(Proc* pr, const char* raw, Settings* settings){
   if(settings && pr->isThread && settings->show_thread_names && !settings->show_merged_command){
      return xstrdup(pr->comm?pr->comm:"");
   }
   if(settings && settings->show_merged_command){
      if(pr->exe_path && pr->exe_path[0]){
         const char* exeFull=pr->exe_path;
         const char* base=strrchr(exeFull,'/');
         const char* exeBase=base?base+1:exeFull;
         const char* exeDisp=settings->show_program_path?exeFull:exeBase;
         const char* L=raw?raw:"";
         const char* R=L;
         int stripped=0;
         if(settings->strip_exe_from_cmdline){
            size_t el=strlen(exeFull);
            if(strncmp(L,exeFull,el)==0 && (L[el]=='\0' || L[el]==' ')){ R=L+el; stripped=1; }
            else {
               size_t bl=strlen(exeBase);
               if(strncmp(L,exeBase,bl)==0 && (L[bl]=='\0' || L[bl]==' ')){ R=L+bl; stripped=1; }
            }
         }
         int includeComm=0;
         if(pr->comm && pr->comm[0] && strcmp(pr->comm,exeBase)!=0){
            includeComm=1;
            if(settings->find_comm_in_cmdline && comm_found_in_cmdline(L,pr->comm)) includeComm=0;
         }
         size_t need=strlen(exeDisp)+(includeComm?strlen(pr->comm)+1:0)+strlen(stripped?R:L)+4;
         char* out=xmalloc(need); out[0]=0;
         strcat(out,exeDisp);
         if(includeComm){ strcat(out,"|"); strcat(out,pr->comm); }
         if(stripped){
            if(includeComm) strcat(out,"|");
            strcat(out,R);
         } else {
            if(L[0]){ strcat(out,"|"); strcat(out,L); }
         }
         return out;
      }
      return xstrdup(raw?raw:"");
   }
   char* result=xstrdup(raw?raw:"");
   if(settings && !settings->show_program_path && result[0]){
      char* space=strchr(result,' ');
      char* first=space?xstrndup(result,(size_t)(space-result)):xstrdup(result);
      const char* base=strrchr(first,'/');
      if(base){
         char* nr=space?str_cat3(base+1,space,NULL):xstrdup(base+1);
         free(result); result=nr;
      }
      free(first);
   }
   return result;
}
'''
