      set_attr(CP_TAB_BRACKET_ACTIVE,0); mvaddstr(y,x+1+(int)strlen(setupMode),"]"); unset_attr(CP_TAB_BRACKET_ACTIVE,0);
      return;
   }
   for(int i=0;i<app->settings->num_screens;i++){
      int active=(i==app->settings->active_screen);
      int pair=active?CP_SCREEN_TAB_ACTIVE:CP_SCREEN_TAB;
      int bracketPair=active?CP_TAB_BRACKET_ACTIVE:CP_TAB_BRACKET;
      const char* nm=app->settings->screens[i].name;
      if(x>=w)break;
      set_attr(bracketPair,0); mvaddstr(y,x,"["); unset_attr(bracketPair,0);
