{"command":"cat > /tmp/patch_cpuopts.py << 'PY'
from pathlib import Path
p=Path("src/htop.c");s=p.read_text()
# PROCESSOR format needs settings but format_col_value doesn't have settings param. It can access a global? Add a global current settings pointer set in main? Simpler: format_col_value is called with settings in build_row_string but its signature doesn't include settings. Add a static global pointer g_settingsForFormat set at each draw/scan? A less invasive: add a global int g_cpuCountFromOne set from settings in scan_processes and draw etc.
s=s.replace("static SystemInfo sysinfo;", "static SystemInfo sysinfo;\nstatic int g_cpuCountFromOne=0;")
# set in scan_processes at start (after sysinfo scans)? Find "   sysinfo_scan_cpu();" first occurrence in scan_processes
s=s.replace("   sysinfo_scan_cpu();\n   sysinfo_scan_mem();", "   if(settings) g_cpuCountFromOne=settings->cpu_count_from_one;\n   sysinfo_scan_cpu();\n   sysinfo_scan_mem();",1)
s=s.replace('case COL_PROCESSOR: snprintf(buf,sz,"%d",pr->processor); break;', 'case COL_PROCESSOR: snprintf(buf,sz,"%d",pr->processor + (g_cpuCountFromOne?1:0)); break;')
# CPU bar overlay freq
old='''   char overlay[64]="";
   if(settings->show_cpu_usage){
      double pct=sysinfo.cpuPercent[cpu];
      if(settings->show_cpu_frequency && sysinfo.cpuFreqMHz[cpu]>0){
         /* Frequency appended? format unknown */
         snprintf(overlay,sizeof(overlay),"%.1f%%",pct);
      } else snprintf(overlay,sizeof(overlay),"%.1f%%",pct);
   }'''
new='''   char overlay[64]="";
   {
      int pos=0;
      if(settings->show_cpu_usage){ pos+=snprintf(overlay+pos,sizeof(overlay)-pos,"%.1f%%",sysinfo.cpuPercent[cpu]); }
      if(settings->show_cpu_frequency){ int mhz=(cpu>=0&&cpu<512)?sysinfo.cpuFreqMHz[cpu]:0; if(mhz>0) snprintf(overlay+pos,sizeof(overlay)-pos,"%s%dMHz",pos?" ":"",mhz); }
   }'''
assert old in s; s=s.replace(old,new)
# CPU average bar overlay
old2='''      char ov[32]; if(settings->show_cpu_usage) snprintf(ov,sizeof(ov),"%.1f%%",cpu_avg_percent()); else ov[0]=0;'''
new2='''      char ov[64]=""; { int pp=0; if(settings->show_cpu_usage) pp+=snprintf(ov+pp,sizeof(ov)-pp,"%.1f%%",cpu_avg_percent()); if(settings->show_cpu_frequency){ long sum=0; int cnt=0; for(int ii=0;ii<sysinfo.cpuCount&&ii<512;ii++) if(sysinfo.cpuFreqMHz[ii]>0){sum+=sysinfo.cpuFreqMHz[ii];cnt++;} if(cnt) snprintf(ov+pp,sizeof(ov)-pp,"%s%ldMHz",pp?" ":"",sum/cnt); } }'''
assert old2 in s; s=s.replace(old2,new2)
# Memory cache calculations: in meter_text_value, cache currently conditional on show_cached for SReclaimable. Remove conditional.
s=s.replace("unsigned long long cache = sysinfo.cached + (settings->show_cached_memory?sysinfo.sReclaimable:0);", "unsigned long long cache = sysinfo.cached + sysinfo.sReclaimable;")
# In meter_primary_fraction for memory same replacement pattern with settings conditional expression
s=s.replace("unsigned long long cache=sysinfo.cached + (settings->show_cached_memory?sysinfo.sReclaimable:0);", "unsigned long long cache=sysinfo.cached + sysinfo.sReclaimable;")
# Memory bar segment cache value conditional. Original block computes cache similarly with ternary; replace cache computation and segment value.
s=s.replace("unsigned long long cache=sysinfo.cached + (settings->show_cached_memory?sysinfo.sReclaimable:0); if(cache>=sysinfo.shared)cache-=sysinfo.shared; else cache=0;", "unsigned long long cache=sysinfo.cached + sysinfo.sReclaimable; if(cache>=sysinfo.shared)cache-=sysinfo.shared; else cache=0;")
# Find Memory BarSeg segment cache entry and conditionalize value
s=s.replace("{(double)cache,CP_MEM_CACHE,useColorsGlobal?'|':'$'}};", "{settings->show_cached_memory?(double)cache:0,CP_MEM_CACHE,useColorsGlobal?'|':'$'}};")
# For graph fraction of memory: if show_cached off, fraction should be used only not +cache. Current code in meter_primary_fraction returns (used+cache)/total. Replace return line with conditional
s=s.replace("return total? (double)(used+cache)/(double)total:0;", "return total? (double)(used+(settings->show_cached_memory?cache:0))/(double)total:0;")
p.write_text(s)
print('patched')
