# F5 handler in viewer normal mode - find exact block
old='''      if(ch==KEY_F(5)){
         /* Refresh handled by caller? Our static lines can't refresh. Breaking with a special? For now do nothing (caller could regenerate before call, viewer stays) */
         continue;
      }'''
new='''      if(ch==KEY_F(5) && viewerKind!=1 && refreshProc){
         StrVec newLines={0};
         if(viewerKind==0) newLines=make_env_lines(refreshProc);
         else if(viewerKind==2){
            char* raw=get_cmdline_for(refreshProc->pid,refreshProc->tgid,refreshProc->comm,NULL);
            free(refreshProc->cmdline); refreshProc->cmdline=build_display_command(refreshProc,raw,app->settings); free(raw);
            newLines=make_cmd_lines(refreshProc,getmaxx(stdscr));
         }
